local config = {
  ui_story_5076_50760100_1_dialog_content = "Apúrate... ¡Despierta, Re...!",
  ui_story_5076_50760100_2_dialog_content = "¿Quién está ahí?",
  ui_story_5076_50760100_3_dialog_content = "Está atrapado en la pesadilla... debemos... el Colossus...",
  ui_story_5076_50760100_4_dialog_content = "Espera, ¿no eres tú...?",
  ui_story_5076_50760100_5_dialog_content = "<size=45>Regresa—</size>",
  ui_story_5076_50760100_6_dialog_content = "Oh, finalmente estás despierto. Me asustaste por un minuto.",
  ui_story_5076_50760100_7_dialog_content = "¿Qué pasa con esa mirada? ¿No recuerdas a tu amigo Celestita? ¡Soy yo, Ludweiss!",
  ui_story_5076_50760100_8_dialog_content = "Parecía que estabas teniendo una pesadilla realmente mala justo ahora. No te despertabas, así que Marcela me llamó.",
  ui_story_5076_50760100_9_dialog_content = "¿Marcela? Marcela...",
  ui_story_5076_50760100_10_dialog_content = "¿Comandante? ¿Estás bien? Es una cosa olvidarte de un vagabundo como yo, pero ¿cómo podrías olvidarte de tu prometida?",
  ui_story_5076_50760100_11_dialog_content = "Estoy justo aquí, Adras... ¿Te sientes mal? Te ves muy pálido.",
  ui_story_5076_50760100_12_dialog_content = "Marcela... Tu ropa...",
  ui_story_5076_50760100_13_dialog_content = "... N-No me mires así. Ludweiss todavía está aquí, ya sabes.",
  ui_story_5076_50760100_14_dialog_content = "¿Sigues disfrutando de la vista incluso después de los últimos días, eh, Comandante? Tiene sentido, ya que el atuendo de Marcela es mucho más lindo que antes.",
  ui_story_5076_50760100_15_dialog_content = "Por favor, no me provoques así...",
  ui_story_5076_50760100_16_dialog_content = "Y mi ropa...",
  ui_story_5076_50760100_17_dialog_content = "¿Estás seguro de que estás despierto? No me digas que olvidaste la boda.",
  ui_story_5076_50760100_18_dialog_content = "La boda... Así es, estaba soñando justo ahora.",
  ui_story_5076_50760100_19_dialog_content = "Estaba de pie en la oscuridad, y todo lo que podía ver era un mural en una pared... Era vago, pero creo que era sobre una boda.",
  ui_story_5076_50760100_20_dialog_content = "Estuve atrapado allí durante tanto tiempo, y no podía recordar nada. Fue un sueño terrible... Uno que duró mil años.",
  ui_story_5076_50760100_21_dialog_content = "No creo que Adras solo tuviera una pesadilla, Ludweiss. ¿Crees que podría estar enfermo?",
  ui_story_5076_50760100_22_dialog_content = "No puedo decirlo con seguridad, pero déjame intentar usar mis poderes psíquicos en él.",
  ui_story_5076_50760100_23_dialog_content = "Adras, ¿estás despierto?",
  ui_story_5076_50760100_24_dialog_content = "...",
  ui_story_5076_50760100_25_dialog_content = "Esto es-!",
  ui_story_5076_50760100_26_dialog_content = "¿Por qué... Por qué estás llorando?",
  ui_story_5076_50760100_27_dialog_content = "¿Estabas soñando con el futuro lejano, Adras? ¿O soñaste conmigo después de todos esos años?",
  ui_story_5076_50760100_28_dialog_content = "¿De qué estás hablando, Ludweiss?",
  ui_story_5076_50760100_29_dialog_content = "¿Ah?",
  ui_story_5076_50760100_30_dialog_content = "Lo siento, caí en la pesadilla de Adras y me perdí por un segundo...",
  ui_story_5076_50760100_31_dialog_content = "Entonces, ¿incluso los Caelestites pueden ser molestados por los sueños, eh?",
  ui_story_5076_50760100_32_dialog_content = "T-Tú finalmente estás despierto... ¡Oye, deja de reír! Solo agradece que te saqué de esa pesadilla!",
  ui_story_5076_50760100_33_dialog_content = "Gracias, Ludweiss. Estaba empezando a preocuparme mucho.",
  ui_story_5076_50760100_34_dialog_content = "Gracias... Pero lo que dijiste sobre mi sueño justo ahora—",
  ui_story_5076_50760100_35_dialog_content = "Comandante, lamento la intrusión, ¡pero hay un mensaje urgente!",
  ui_story_5076_50760100_36_dialog_content = "El General Aquiles ordena a la legión que se reúna.",
  ui_story_5076_50760100_37_dialog_content = "Entendido. Estaré allí en breve.",
  ui_story_5076_50760100_38_dialog_content = "Perdóname por hacer que los dos se preocupen tanto. Prometo que volveré pronto.",
  ui_story_5076_50760100_39_dialog_content = "Jeje, solo intenta no hacer esperar a Marcela.",
  ui_story_5076_50760100_40_dialog_content = "De nuevo, seguías hablando de una boda en tus sueños, así que probablemente no necesites que te lo recuerde.",
  ui_story_5076_50760100_41_dialog_content = "N-No la escuches. La misión es lo primero, y el General Aquiles te está esperando.",
  ui_story_5076_50760100_42_dialog_content = "Volveré lo más pronto posible.",
  ui_story_5076_50760100_43_dialog_content = "... Los malvados Eclipsites han reaparecido en el norte, amenazando con invadir nuestras fronteras.",
  ui_story_5076_50760100_44_dialog_content = "¡El rey nos ha ordenado erradicar a esos monstruos!",
  ui_story_5076_50760100_45_dialog_content = "Una vez que estés despedido, recoge tus equipos y despídete de tus seres queridos.",
  ui_story_5076_50760100_46_dialog_content = "¡Entendido!",
  ui_story_5076_50760100_47_dialog_content = "¿Cómo te ha tratado la vida normal, Adras?",
  ui_story_5076_50760100_48_dialog_content = "Es pacífico. Todavía no estoy completamente acostumbrado a ello.",
  ui_story_5076_50760100_49_dialog_content = "Comandante, es hora de dejar las batallas atrás y aceptar esta vida pacífica.",
  ui_story_5076_50760100_50_dialog_content = "Vas a casarte pronto, pero todavía estás... Es bastante preocupante.",
  ui_story_5076_50760100_51_dialog_content = "Estamos a punto de irnos, Adras, pero felicidades por tu boda.",
  ui_story_5076_50760100_52_dialog_content = "¿De qué estás hablando? Casi parece que no tienes intención de dejarme ir en esta misión.",
  ui_story_5076_50760100_53_dialog_content = "Así es. Los Eclipsites reportados en el norte no justifican la totalidad de nuestras fuerzas.",
  ui_story_5076_50760100_54_dialog_content = "Tu misión es quedarte aquí y disfrutar de la vida que has creado para ti mismo.",
  ui_story_5076_50760100_55_dialog_content = "Has sacrificado años de tu vida por el bien de los demás, y ahora es el momento de que persigas tu propia felicidad. Al menos, puedes ver todo lo que has protegido con Marcela a tu lado.",
  ui_story_5076_50760100_56_dialog_content = "General, yo...",
  ui_story_5076_50760100_57_dialog_content = "Comandante Adras, de acuerdo con las leyes y políticas del reino, se le concede permiso matrimonial para que pueda disfrutar de su boda!",
  ui_story_5076_50760100_58_dialog_content = "Tranquiliza tu mente y disfruta de tu tiempo libre.",
  ui_story_5076_50760100_59_dialog_content = "¡Felicitaciones, Comandante Adras!",
  ui_story_5076_50760100_60_dialog_content = "Tú...",
  ui_story_5076_50760100_61_dialog_content = "¡Quizás ya tengas un pequeño cuando volvamos!",
  ui_story_5076_50760100_62_dialog_content = "El comandante puede que no sea el mejor con los niños. Crucemos los dedos para que su hijo se parezca más a su madre.",
  ui_story_5076_50760100_63_dialog_content = "Muy bien, todos, dejen sus regalos y sigan con sus asuntos. Adras, tú quédate aquí.",
  ui_story_5076_50760100_64_dialog_content = "¿Has oído hablar sobre el <color=#FFB400>Alto Sacerdote Lucius</color> regresando a la capital real?",
  ui_story_5076_50760100_65_dialog_content = "¿Lucius? ¿Quieres decir que él...",
  ui_story_5076_50760100_66_dialog_content = "Comandante Adras, todos los rebeldes están aquí.",
  ui_story_5076_50760100_67_dialog_content = "¡Déjame ir, déjame ir! ¿Sabes quién soy?",
  ui_story_5076_50760100_68_dialog_content = "Soy Lucius, ¡el Sumo Sacerdote al que todos deberían reverenciar! ¡Muéstrenme algo de respeto!",
  ui_story_5076_50760100_69_dialog_content = "Todo lo que veo es un traidor, y nada más.",
  ui_story_5076_50760100_70_dialog_content = "¿Oh? ¿Así que nuestro poderoso héroe es el que organizó todo esto? No es de extrañar que tuvieran la audacia de irrumpir con una fuerza tan escasa.",
  ui_story_5076_50760100_71_dialog_content = "¡¿Cómo te atreves a ser tan pretencioso cuando no eres más que un simple plebeyo?!",
  ui_story_5076_50760100_72_dialog_content = "¡Has puesto en peligro la paz del reino y por lo tanto estás bajo arresto!",
  ui_story_5076_50760100_73_dialog_content = "Arrepiéntete por el daño que has causado a la gente.",
  ui_story_5076_50760100_74_dialog_content = "¡Suéltame! ¿Quién te crees que eres?! ¡No eres más que una pieza de ajedrez del Anciano Primordial!",
  ui_story_5076_50760100_75_dialog_content = "¡Vivirás para arrepentirte de esto! Marca mis palabras, personalmente te haré pagar—",
  ui_story_5076_50760100_76_dialog_content = "¿No fue declarado culpable de traición?",
  ui_story_5076_50760100_77_dialog_content = "Sí, pero Lucius sigue siendo un noble. A pesar de tener contacto con los rebeldes, solo fue declarado culpable por asociación.",
  ui_story_5076_50760100_78_dialog_content = "Cuando cayó del poder, la influencia del Consejo de Ancianos creció de manera sin precedentes. Su regreso a la relevancia política es solo para que el rey pueda mantener al control al Anciano Principal.",
  ui_story_5076_50760100_79_dialog_content = "El rey y yo hemos sido amigos durante muchos años, sin embargo, últimamente se ha vuelto cada vez más un extraño para mí. Parece que se ha vuelto bastante hábil en el uso de métodos como estos.",
  ui_story_5076_50760100_80_dialog_content = "Ten cuidado, Adras.",
  ui_story_5076_50760100_81_dialog_content = "Solo estoy cumpliendo con mis órdenes. No debería tenerlo en contra mía.",
  ui_story_5076_50760100_82_dialog_content = "No todos siguen las reglas y la razón tanto como tú.",
  ui_story_5076_50760100_83_dialog_content = "En cualquier caso, recuerda mantenerte alerta incluso en tu pacífica y nueva vida. La desgracia siempre está al acecho en las sombras.",
  ui_story_5076_50760100_84_dialog_content = "Cuando el ejército rebelde ocupaba la ciudad... Fue entonces cuando la conocí.",
  ui_story_5076_50760100_85_dialog_content = "Hay más en este mundo que solo desgracia.",
  ui_story_5076_50760100_86_dialog_content = "Has cambiado, Adras.",
  ui_story_5076_50760100_87_dialog_content = "Estoy feliz por ti. Parece que finalmente has encontrado las respuestas que buscabas en la vida.",
  ui_story_5076_50760100_88_dialog_content = "Bien, eso es todo de mi parte, los regalos también están aquí. ¡Disfruta los buenos momentos que vienen!",
  ui_story_5076_50760100_89_dialog_content = "Estaré rezando por tu regreso seguro, General Aquiles.",
  ui_story_5076_50760100_90_dialog_content = "Gracias, ahora vete. Ya casi es hora para la boda, así que no hagas esperar a Marcela.",
  ui_story_5076_50760200_1_dialog_content = "¡Mira allí! Ese es el héroe legendario, Adras, caminando hacia nosotros!",
  ui_story_5076_50760200_2_dialog_content = "¿Adras? ¿El héroe que sofocó la rebelión en aquellos días?",
  ui_story_5076_50760200_3_dialog_content = "¿En aquellos tiempos? Soy algo nuevo aquí; ¿qué pasó en ese entonces?",
  ui_story_5076_50760200_4_dialog_content = "Déjame decirte, durante esos años...",
  ui_story_5076_50760200_5_dialog_content = "¡Rebeldes! Yo, en nombre de la Legión Northwind, estoy aquí para ofreceros una oportunidad: vuestros refuerzos han sido cortados; ¡RENDEOS AHORA!",
  ui_story_5076_50760200_6_dialog_content = "¡Sigue soñando! Mientras esta ciudad se mantenga en pie, no perderemos...",
  ui_story_5076_50760200_7_dialog_content = "¡Arqueros! ¡Fuego! Alguien, traiga a esas personas aquí! ¡Dejen que ellos protejan el ataque!",
  ui_story_5076_50760200_8_dialog_content = "¿La primera legión? ¿Y qué? Con todos estos rehenes que tenemos en la ciudad...",
  ui_story_5076_50760200_9_dialog_content = "¡Capitán, mira! ¡Están cargando contra nosotros con los escudos en alto!",
  ui_story_5076_50760200_10_dialog_content = "¿Qué? ¿Creen que son invencibles? ¡Sigue disparando! ¡No dejes que se acerquen más a las murallas de la ciudad!",
  ui_story_5076_50760200_11_dialog_content = "Urgh—!",
  ui_story_5076_50760200_12_dialog_content = "¿Qué está pasando ahí abajo?",
  ui_story_5076_50760200_13_dialog_content = "¡Un escuadrón se infiltró desde la retaguardia durante el caos! ¡Ya están en la ciudad!",
  ui_story_5076_50760200_14_dialog_content = "¿Cuántos hay?",
  ui_story_5076_50760200_15_dialog_content = "¡Solo unos pocos de ellos, cada uno empuñando solo una espada, escalaron la pared con sus propias manos!",
  ui_story_5076_50760200_16_dialog_content = "¡Banda inútil! ¿Tengo que manejar esto yo mismo?!",
  ui_story_5076_50760200_17_dialog_content = "Pero... el tipo que los lidera es increíblemente fuerte...",
  ui_story_5076_50760200_18_dialog_content = "¡Deja de resistirte! ¡No voy a atacar a civiles desarmados!",
  ui_story_5076_50760200_19_dialog_content = "¡También son ciudadanos de este reino, así que dejen de lastimar a sus compatriotas!",
  ui_story_5076_50760200_20_dialog_content = "Idiotas tontos, rodeados por nosotros pero aún así actuando duro... ¡ATRÁPENLOS!",
  ui_story_5076_50760200_21_dialog_content = "Tuviste tu oportunidad, villanos—¡Todas las fuerzas, maten al enemigo a la vista!",
  ui_story_5076_50760200_22_dialog_content = "¡Derriben a su comandante y abran camino para nuestros hermanos que atacan la ciudad! ¡Síganme!",
  ui_story_5076_50760200_23_dialog_content = "¡Deténganlos! ¡Traigan a los arqueros aquí!",
  ui_story_5076_50760200_24_dialog_content = "¡Capitán, malas noticias! Alguien asaltó la mazmorra donde se encuentran los residentes, ¡y nuestro almacén está en llamas!",
  ui_story_5076_50760200_25_dialog_content = "¡Capitán! Se ha abierto la puerta oeste; alguien está ayudando a los civiles a escapar!",
  ui_story_5076_50760200_26_dialog_content = "¡Cap-Capitán! ¡Detrás de nosotros!",
  ui_story_5076_50760200_27_dialog_content = "<size=40>¡Maldita sea!</size> ¿Qué demonios está pasando de nuevo—!",
  ui_story_5076_50760200_28_dialog_content = "<size=45>¡Morir!</size>",
  ui_story_5076_50760200_29_dialog_content = "¡Capitán!",
  ui_story_5076_50760200_30_dialog_content = "¡Rebeldes! ¡Vuestro capitán está muerto! ¡Bajad las armas, todos vosotros!",
  ui_story_5076_50760200_31_dialog_content = "¡Ha habido suficientes asesinatos sin sentido en la ciudad, pero ahora es el momento de terminar con esto! Nadie más tiene que morir siempre y cuando me traigas a tu líder!",
  ui_story_5076_50760200_32_dialog_content = "¿Por qué deberíamos creerte? ¿Cuál es tu prueba...",
  ui_story_5076_50760200_33_dialog_content = "¡Porque soy Adras!",
  ui_story_5076_50760200_34_dialog_content = "¡El hombre que terminará esta guerra!",
  ui_story_5076_50760200_35_dialog_content = "¡Mira qué rápido está corriendo! ¿Quizás también se unió a la expedición?",
  ui_story_5076_50760200_36_dialog_content = "Si ese héroe también va allí, mi hijo en el ejército debería estar más seguro, ¿verdad...?",
  ui_story_5076_50760200_37_dialog_content = "¿Olvidaste? El héroe está a punto de casarse; la ceremonia está toda preparada.",
  ui_story_5076_50760200_38_dialog_content = "¡Marcela!",
  ui_story_5076_50760200_39_dialog_content = "¡Guau! ¡No me asustes así! ¿Qué pasa?",
  ui_story_5076_50760200_40_dialog_content = "No te hice esperar demasiado... ¿Verdad?",
  ui_story_5076_50760200_41_dialog_content = "Estoy bien. Eres tú de quien me preocupo. ¿Qué está pasando en la Legión?",
  ui_story_5076_50760200_42_dialog_content = "Los Eclipsites están comenzando a concentrarse en el norte. El general tiene órdenes de eliminarlos.",
  ui_story_5076_50760200_43_dialog_content = "¿Y tú no vas?",
  ui_story_5076_50760200_44_dialog_content = "El General Aquiles dice que sus números no requieren mi presencia. Me dio permiso para que pudiéramos pasar nuestra boda en paz.",
  ui_story_5076_50760200_45_dialog_content = "Si es por mi bien, no tienes que—",
  ui_story_5076_50760200_46_dialog_content = "Dijiste que el techo del orfanato necesitaba reparación, ¿verdad? Tengo tiempo para encargarme de eso ahora.",
  ui_story_5076_50760200_47_dialog_content = "Me gustaría pasar unos días contigo fuera de la ciudad, ¿eso estaría bien?",
  ui_story_5076_50760200_48_dialog_content = "... Claro. Me encantaría.",
  ui_story_5076_50760200_49_dialog_content = "<color=#e8d9bb>Varios días después</color>",
  ui_story_5076_50760200_50_dialog_content = "La boda está a la vuelta de la esquina, ¿y ustedes dos de repente quieren hacer un viaje fuera de la ciudad?",
  ui_story_5076_50760200_51_dialog_content = "¿Eh? Solo pensé que estaríamos ocupados los próximos días, así que quería preparar suficiente material de enseñanza para los niños.",
  ui_story_5076_50760200_52_dialog_content = "¿Y no podías simplemente dejarme eso a mí?",
  ui_story_5076_50760200_53_dialog_content = "¿No vas a viajar a un nuevo lugar pronto? Además, ya me has ayudado bastante compilándolo. No puedo seguir dependiendo de ti.",
  ui_story_5076_50760200_54_dialog_content = "¿Vas a la carretera de nuevo, eh? Cuídate bien, Ludweiss.",
  ui_story_5076_50760200_55_dialog_content = "Igual para ustedes dos... El orfanato se ve mucho mejor esta vez. Realmente han estado dando todo de ustedes, ¿no es así, Adras?",
  ui_story_5076_50760200_56_dialog_content = "No me importa, siempre y cuando sea por los niños.",
  ui_story_5076_50760200_57_dialog_content = "¿Así que en qué andas ahora?",
  ui_story_5076_50760200_58_dialog_content = "Haciendo pan.",
  ui_story_5076_50760200_59_dialog_content = "Qué forma tan elegante. No te queda nada bien, ya sabes.",
  ui_story_5076_50760200_60_dialog_content = "Puedes tener un poco, si quieres.",
  ui_story_5076_50760200_61_dialog_content = "Adras es bastante hábil haciendo pan. Antes de convertirse en soldado, prácticamente adoraba al panadero local e incluso fue su aprendiz durante un tiempo.",
  ui_story_5076_50760200_62_dialog_content = "Eso es porque siempre repartía pan a los niños en la calle.",
  ui_story_5076_50760200_63_dialog_content = "Adras, es Adras!",
  ui_story_5076_50760200_64_dialog_content = "No me abraces. Estoy cubierto de harina.",
  ui_story_5076_50760200_65_dialog_content = "Todavía no tenemos hambre; practiquemos primero.",
  ui_story_5076_50760200_66_dialog_content = "Por favor, enséñanos algunas habilidades con la espada; ¡también queremos proteger a Marcela!",
  ui_story_5076_50760200_67_dialog_content = "No podrás comer este pan si no lo horneo ahora mismo.",
  ui_story_5076_50760200_68_dialog_content = "¡Primero las habilidades con la espada! Eso es más importante, ¡sabes!",
  ui_story_5076_50760200_69_dialog_content = "Marcela...",
  ui_story_5076_50760200_70_dialog_content = "Dale algo de espacio. Estará contigo una vez que termine de meter el pan en el horno, ¿de acuerdo?",
  ui_story_5076_50760200_71_dialog_content = "Multa...",
  ui_story_5076_50760200_72_dialog_content = "Adras es incapaz con esos niños, y sin embargo, puedes hacer que te escuchen con solo unas pocas palabras.",
  ui_story_5076_50760200_73_dialog_content = "Bueno, después de todo, los he estado manteniendo bajo control desde que eran pequeños.",
  ui_story_5076_50760200_74_dialog_content = "Casi lo olvido... Aunque eres más joven que yo, has estado administrando este orfanato durante años. Realmente eres una persona increíble.",
  ui_story_5076_50760200_75_dialog_content = "He visto todo tipo de guerra y conflicto en mis viajes, pero es raro encontrar a alguien como tú que ayuda a los niños que lo han perdido todo.",
  ui_story_5076_50760200_76_dialog_content = "Tal vez sea porque... Yo también crecí en un orfanato.",
  ui_story_5076_50760200_77_dialog_content = "Y aunque lo perdí todo, he tenido a tantas personas bondadosas cuidándome todo este tiempo. Esta es mi forma de expresar mi agradecimiento y devolver la bondad que el mundo me ha mostrado.",
  ui_story_5076_50760200_78_dialog_content = "... Eso debería bastar. Marcela, voy a... ir a entrenar con los niños ahora.",
  ui_story_5076_50760200_79_dialog_content = "No seas demasiado duro con ellos, ¿de acuerdo?",
  ui_story_5076_50760200_80_dialog_content = "Ludweiss.",
  ui_story_5076_50760200_81_dialog_content = "¿Mmm?",
  ui_story_5076_50760200_82_dialog_content = "Estoy seguro de que has visto más tragedias en tus viajes de las que puedes contar... Pero por favor no te desanimes. Este mundo todavía está lleno de bondad.",
  ui_story_5076_50760200_83_dialog_content = "Por favor, no dejes de creer en los demás.",
  ui_story_5076_50760200_84_dialog_content = "Por supuesto que lo sé. Después de todo, conocer a los dos fue simplemente otra cosa buena de este mundo.",
  ui_story_5076_50760200_85_dialog_content = "Es increíble pensar que llegué a este reino justo cuando todos estaban celebrando el regreso de Adras.",
  ui_story_5076_50760200_86_dialog_content = "Incluso ahora, todavía puedo recordar las sonrisas y los aplausos en cada calle de la capital real.",
  ui_story_5076_50760200_87_dialog_content = "¡Entiendo lo que quieres decir! Conocer al héroe Adras por primera vez siempre tiene un efecto deslumbrante en las personas.",
  ui_story_5076_50760200_88_dialog_content = "Suena a mucha fanfarronería para mí, futura Sra. Adras.",
  ui_story_5076_50760200_89_dialog_content = "¡E-Eso no es lo que quise decir!",
  ui_story_5076_50760200_90_dialog_content = "También he oído hablar todo el tiempo de la historia heroica de Adras. Así es como entiendo por qué la gente se siente tan segura cuando lo ve.",
  ui_story_5076_50760200_91_dialog_content = "Todos los niños también lo admiran. Es el héroe de todos, pero...",
  ui_story_5076_50760200_92_dialog_content = "¿Marcela?",
  ui_story_5076_50760200_93_dialog_content = "¿Eh? ¡O-Oh, no es nada!",
  ui_story_5076_50760200_94_dialog_content = "Olvidé preguntar antes, pero ¿a dónde vas después?",
  ui_story_5076_50760200_95_dialog_content = "Voy a viajar por el reino con algunos nuevos amigos antes de regresar aquí. Son personas bastante interesantes, al igual que Adras.",
  ui_story_5076_50760200_96_dialog_content = "Lamentablemente, ahora no es el momento de hablar de esto. Te los presentaré cuando tenga la oportunidad.",
  ui_story_5076_50760200_97_dialog_content = "Vas a quedarte para nuestra boda al menos, ¿verdad...?",
  ui_story_5076_50760200_98_dialog_content = "Claro que soy yo. No te preocupes por eso.",
  ui_story_5076_50760300_1_dialog_content = "¿Buscas algo, Adras? ¿Por qué te ves tan preocupado?",
  ui_story_5076_50760300_2_dialog_content = "Ludweiss, ¿has visto a Marcela? Desapareció sin decir una palabra esta mañana...",
  ui_story_5076_50760300_3_dialog_content = "No te preocupes tanto. Es solo una mañana.",
  ui_story_5076_50760300_4_dialog_content = "... Con la boda acercándose, parece que algo pesa en su corazón, pero no me dirá qué es.",
  ui_story_5076_50760300_5_dialog_content = "¿Podrías ayudarme a buscarla, Ludweiss?",
  ui_story_5076_50760300_6_dialog_content = "Entiendo. No te preocupes. Usaré mis poderes psíquicos para ayudarte a encontrarla.",
  ui_story_5076_50760300_7_dialog_content = "Simplemente cálmate y sígueme.",
  ui_story_5076_50760300_8_dialog_content = "¡Ahí! ¡Ella está frente al templo!",
  ui_story_5076_50760300_9_dialog_content = "¿Eh? Ella está... ¿alimentando a un gato?",
  ui_story_5076_50760300_10_dialog_content = "No, parece que está aturdida. Ese gato casi ha terminado de comer la comida que ella le trajo, algo debe estar molestando después de todo.",
  ui_story_5076_50760300_11_dialog_content = "Ludweiss... ¿Podrías por favor ir a hablar con ella?",
  ui_story_5076_50760300_12_dialog_content = "¿Qué pasa? ¿Nuestro valiente comandante tiene miedo de que su propia prometida no quiera hablar con él?",
  ui_story_5076_50760300_13_dialog_content = "No... Tengo miedo de que ella no me diga la verdad.",
  ui_story_5076_50760300_14_dialog_content = "Pero si habla con una Caelestite que lee la mente, es muy probable que te diga lo que tiene en mente... No quiero que oculte sus problemas por mí.",
  ui_story_5076_50760300_15_dialog_content = "Bien, bien. Honestamente, están actuando como un par de adolescentes incómodos a pesar de que se van a casar mañana.",
  ui_story_5076_50760300_16_dialog_content = "¡E-Ejem! ¡Qué sorpresa verte aquí, Marcela! ¿Estás alimentando a uno de los cerdos salvajes, eh?",
  ui_story_5076_50760300_17_dialog_content = "¿L-Ludweiss?",
  ui_story_5076_50760300_18_dialog_content = "Un cierto comandante estaría preocupado al verte aquí completamente solo.",
  ui_story_5076_50760300_19_dialog_content = "¿Eh? ¡Ah!",
  ui_story_5076_50760300_20_dialog_content = "Tienes razón, probablemente Adras esté preocupado por mí. ¡Debería volver—",
  ui_story_5076_50760300_21_dialog_content = "¿Cuál es la prisa? ¿No quieres decirme primero qué tienes en mente?",
  ui_story_5076_50760300_22_dialog_content = "No tiene sentido ocultármelo. Después de todo, nosotros los Caelestites somos conocidos por nuestra habilidad para comprender las emociones. ¡Incluso podrías decir que somos el pueblo del amor!",
  ui_story_5076_50760300_23_dialog_content = "Algo te ha estado molestando durante los últimos días, ¿no es así?",
  ui_story_5076_50760300_24_dialog_content = "Ya veo... Realmente no hay cómo ocultarte las cosas.",
  ui_story_5076_50760300_25_dialog_content = "Entonces, ¿qué te ha estado preocupando últimamente?",
  ui_story_5076_50760300_26_dialog_content = "No es nada realmente, solo que... Tal vez es porque la boda está tan cerca, pero siento un poco de miedo.",
  ui_story_5076_50760300_27_dialog_content = "¿Asustada?",
  ui_story_5076_50760300_28_dialog_content = "Hace mucho tiempo, yo era como todos los demás que habían escuchado las historias de Adras, el héroe del pueblo.",
  ui_story_5076_50760300_29_dialog_content = "Siempre pensé que conocer a una leyenda como él era imposible, pero en el caos de ese día... lo vi.",
  ui_story_5076_50760300_30_dialog_content = "A pesar de sus heridas, derrotó a esas personas tan fácilmente y declaró que la ciudad estaba segura.",
  ui_story_5076_50760300_31_dialog_content = "Un cuento clásico de una joven doncella enamorándose de un caballero de brillante armadura. ¿Fue entonces cuando te enamoraste locamente de él?",
  ui_story_5076_50760300_32_dialog_content = "Lo contrario, en realidad—Mi corazón se sentía insoportablemente triste porque no podía aceptar que nuestro héroe no fuera completamente honesto.",
  ui_story_5076_50760300_33_dialog_content = "El héroe en nuestras leyendas se suponía que era invencible, y sin embargo, estaba cubierto de innumerables heridas. Me hizo preguntarme cuántas veces le había sucedido esto, y si alguien alguna vez se molestó en cuidarlo.",
  ui_story_5076_50760300_34_dialog_content = "No pasó mucho tiempo, me encontré haciendo exactamente eso. Cuidándolo, comprendiéndolo...",
  ui_story_5076_50760300_35_dialog_content = "¿Pero no es eso algo bueno? ¿Tratarlo como a una persona viva y respirando?",
  ui_story_5076_50760300_36_dialog_content = "Pero... ¿no crees que me he entrometido demasiado en su vida?",
  ui_story_5076_50760300_37_dialog_content = "Por mi culpa, él no puede ir a una misión importante con sus compañeros soldados... ¿Realmente está dispuesto a abandonar sus deberes de esta manera?",
  ui_story_5076_50760300_38_dialog_content = "Adras parece perfectamente feliz para mí, ¿no crees?",
  ui_story_5076_50760300_39_dialog_content = "Una vez me dijo que incluso siendo un niño, nunca estuvo lejos del campo de batalla. Debido a eso, no sabía lo que significaba ser feliz. Por eso, me llena de alegría verlo jugar felizmente con los niños...",
  ui_story_5076_50760300_40_dialog_content = "Pero puedo decir que no está acostumbrado a vivir así, y parece que solo lo está haciendo por mí.",
  ui_story_5076_50760300_41_dialog_content = "Darle un hogar al que regresar es algo maravilloso—",
  ui_story_5076_50760300_42_dialog_content = "Y aún así, esta vida normal es la razón por la que comenzó a tener pesadillas tan terribles.",
  ui_story_5076_50760300_43_dialog_content = "Adras es... un héroe para la gente. Solo me preocupa que lo esté reteniendo.",
  ui_story_5076_50760300_44_dialog_content = "Ah, pero no te preocupes demasiado por eso. Estoy seguro de que solo son los nervios previos a la boda que me afectan...",
  ui_story_5076_50760300_45_dialog_content = "¿Has mencionado algo de esto a Adras? No, ¿verdad?",
  ui_story_5076_50760300_46_dialog_content = "... En el Día del Triunfo, el rey le visitó personalmente. Algunas personas incluso sugirieron erigir una estatua de él en la plaza del pueblo.",
  ui_story_5076_50760300_47_dialog_content = "Pero después de eso, las hazañas heroicas de Adras llegaron a su fin. La gente comenzó lentamente a olvidarse de él, y el asunto quedó sin resolver.",
  ui_story_5076_50760300_48_dialog_content = "Sé que a él no le importa la fama o la gloria, pero no puedo evitar sentir que ha renunciado a tanto por mí.",
  ui_story_5076_50760300_49_dialog_content = "Estoy muy agradecida con él por ayudarme a dirigir este orfanato, pero él sigue siendo Adras, el héroe del pueblo.",
  ui_story_5076_50760300_50_dialog_content = "Él sigue siendo una estrella brillante, una que arde con grandes ambiciones.",
  ui_story_5076_50760300_51_dialog_content = "Al igual que tengo cosas que solo yo puedo hacer, Adras tiene cosas que solo él puede lograr.",
  ui_story_5076_50760300_52_dialog_content = "No estás diciendo estas cosas porque quieres dejarlo, ¿verdad...?",
  ui_story_5076_50760300_53_dialog_content = "¿Estás bromeando? Solo lo lastimaría haciendo algo así... así como a mí mismo.",
  ui_story_5076_50760300_54_dialog_content = "Solo deseo que él pudiera ser libre.",
  ui_story_5076_50760300_55_dialog_content = "Si su corazón le dice que luche por su hogar y su país, entonces eso es exactamente lo que quiero que haga. No quiero que se quede aquí solo por mí...",
  ui_story_5076_50760300_56_dialog_content = "¿Eso es lo que piensas? Porque hasta donde puedo ver, Adras sigue siendo el mismo héroe que era aquel día.",
  ui_story_5076_50760300_57_dialog_content = "Ayuda a los ancianos a cortar leña, repara el techo del templo, entrena a la milicia y encuentra tiempo para jugar con los niños...",
  ui_story_5076_50760300_58_dialog_content = "Está utilizando cada onza de su fuerza para hacer el bien, y por eso todos en esta ciudad lo aman.",
  ui_story_5076_50760300_59_dialog_content = "¿No es eso lo que se supone que debe hacer un héroe?",
  ui_story_5076_50760300_60_dialog_content = "Pero... La amenaza de los Eclipsites sigue siendo muy real en este mundo.",
  ui_story_5076_50760300_61_dialog_content = "Esta guerra ha costado a tantas personas sus hogares e incluso sus familias. Adras y yo no somos una excepción...",
  ui_story_5076_50760300_62_dialog_content = "Me preocupa que si Adras no utiliza sus talentos, algún día lo lamentará.",
  ui_story_5076_50760300_63_dialog_content = "Deberías decírselo si esto realmente te preocupa.",
  ui_story_5076_50760300_64_dialog_content = "No conocerán los pensamientos del otro sobre el asunto si sigues reprimiendo tus sentimientos.",
  ui_story_5076_50760300_65_dialog_content = "Los forasteros como nosotros solo lo conoceremos como el comandante invencible.",
  ui_story_5076_50760300_66_dialog_content = "Tú, por otro lado, eres el único que puede ver las heridas debajo de su armadura y preocuparte por la muerte de sus ambiciones.",
  ui_story_5076_50760300_67_dialog_content = "Estoy seguro de que él entenderá si compartes tus sentimientos con él.",
  ui_story_5076_50760300_68_dialog_content = "Pero tengo miedo de que entierre sus sueños solo para acomodarme.",
  ui_story_5076_50760300_69_dialog_content = "¿Eso es lo que te ha estado preocupando todo este tiempo?",
  ui_story_5076_50760300_70_dialog_content = "Es mi culpa por molestarte de esta manera.",
  ui_story_5076_50760300_71_dialog_content = "¿¡Adras?!",
  ui_story_5076_50760300_72_dialog_content = "¡N-No, yo soy el que debería disculparse por preocuparte!",
  ui_story_5076_50760300_73_dialog_content = "Oh, Adras. ¿Es esta la primera vez que no logras hacer que alguien se sienta seguro?",
  ui_story_5076_50760300_74_dialog_content = "Perdí mi hogar a manos de los Eclipsites hace mucho tiempo. Desde que era niño, no sentía más que odio hacia ellos, así que me alisté en el ejército tan pronto como pude.",
  ui_story_5076_50760300_75_dialog_content = "Quizás por eso, nunca he podido entender lo que significa vivir en paz. Aun así, me dio la determinación para proteger todo lo que aprecio.",
  ui_story_5076_50760300_76_dialog_content = "Siempre que dormía en mi tienda, mis sueños estaban llenos del hedor a sangre.",
  ui_story_5076_50760300_77_dialog_content = "El odio, la rabia y la camaradería me mantuvieron cargando contra el enemigo.",
  ui_story_5076_50760300_78_dialog_content = "No había un final a la vista, pero estaba dispuesto a seguir luchando por el bien de aquellos que estaban detrás de mí.",
  ui_story_5076_50760300_79_dialog_content = "No viví y luché por ellos porque tuviera que hacerlo, sino porque quería hacerlo. Mientras hubiera alguien detrás de mí, me negaba a caer.",
  ui_story_5076_50760300_80_dialog_content = "Adras...",
  ui_story_5076_50760300_81_dialog_content = "Pero ese día, cuando puse fin a la rebelión y entré a la ciudad—",
  ui_story_5076_50760300_82_dialog_content = "Fue entonces cuando entraste en mi mundo. Solo eras otra persona en la multitud, manteniendo a un grupo de huérfanos a salvo.",
  ui_story_5076_50760300_83_dialog_content = "Pero entonces corriste hacia mí de repente, regañándome mientras limpiabas y vendabas mis heridas.",
  ui_story_5076_50760300_84_dialog_content = "En ese momento, cuando me dijiste que me quedara quieto y que dejara de exigirme tanto—",
  ui_story_5076_50760300_85_dialog_content = "Sabía que finalmente había encontrado la salvación de una vida de muerte y destrucción.",
  ui_story_5076_50760300_86_dialog_content = "¿Todavía recuerdas el sueño que me diste ese día?",
  ui_story_5076_50760300_87_dialog_content = "Si el mundo alguna vez regresa a la paz una vez más, ¿qué hará el gran Adras?",
  ui_story_5076_50760300_88_dialog_content = "¿Qué más puedo hacer?",
  ui_story_5076_50760300_89_dialog_content = "Todo lo que sé es la guerra, pero ¿quizás podría convertirme en un bardo viajero? En el pasado, la gente prácticamente volvía corriendo al trabajo cada vez que me oían cantar.",
  ui_story_5076_50760300_90_dialog_content = "¡Debes tener una voz bastante única entonces!",
  ui_story_5076_50760300_91_dialog_content = "Nunca he pensado en la vida después de la guerra, así que realmente no tengo ninguna idea.",
  ui_story_5076_50760300_92_dialog_content = "Parece que planificar no es exactamente tu fuerte, pero no te preocupes. Te ayudaré a pensar en algo.",
  ui_story_5076_50760300_93_dialog_content = "Con tu imponente estatura, podrías tener éxito en ventas o negociaciones.",
  ui_story_5076_50760300_94_dialog_content = "También eres muy fuerte, por lo que vale la pena considerar la construcción y reparación de estructuras.",
  ui_story_5076_50760300_95_dialog_content = "Estoy seguro de que podrías convertirte en un panadero de primera categoría con tus habilidades para hacer pan también.",
  ui_story_5076_50760300_96_dialog_content = "No estoy seguro de poder enumerar todas tus cualidades positivas de una vez, pero una cosa es segura: tu futuro será brillante.",
  ui_story_5076_50760300_97_dialog_content = "Mi futuro... no será brillante a menos que tú estés en él.",
  ui_story_5076_50760300_98_dialog_content = "¿Qué harías si realmente volviera la paz, Marcela?",
  ui_story_5076_50760300_99_dialog_content = "¿Yo? Bueno... para ser honesto, no tengo grandes aspiraciones de las que hablar.",
  ui_story_5076_50760300_100_dialog_content = "Pero en un mundo pacífico, me encantaría construir una pequeña cabaña en el campo y convertirme en un granjero de trigo... Y tal vez adoptar a algunos niños también.",
  ui_story_5076_50760300_101_dialog_content = "Y si estuvieras allí conmigo, te llevaría a ti y a los niños a cosechar los campos conmigo en otoño.",
  ui_story_5076_50760300_102_dialog_content = "Estaría feliz de pasar esos días tranquilos contigo, observando los dorados campos de trigo bajo el cálido resplandor del sol—",
  ui_story_5076_50760300_103_dialog_content = "Entonces ese también es mi sueño.",
  ui_story_5076_50760300_104_dialog_content = "Marcela, mi pasado está lejos de ser feliz, por lo que tengo muy poca fe en cualquier dios. Aun así, te lo juro—",
  ui_story_5076_50760300_105_dialog_content = "Que yo, Adras, nunca dejaré de luchar por nuestro sueño dorado. Ni jamás me alejaré de tu lado.",
  ui_story_5076_50760300_106_dialog_content = "Hicimos esa promesa juntos, pero has estado sufriendo mucho por ella.",
  ui_story_5076_50760300_107_dialog_content = "En el pasado, no me importaba si vivía o moría en el campo de batalla. Luché por las personas que quería proteger sin casi ninguna consideración por mi propia seguridad.",
  ui_story_5076_50760300_108_dialog_content = "Pero después de enamorarme de ti, comencé a recordar tu rostro incluso en medio de la batalla. Cada encuentro con los Eclipsites me hizo preocuparme de que no podría volver a verte.",
  ui_story_5076_50760300_109_dialog_content = "Una vez que tuve a alguien de quien preocuparme, aparentemente perdí la habilidad de luchar como un demonio. En un momento, me pregunté si eso me estaba debilitando—",
  ui_story_5076_50760300_110_dialog_content = "Pero luego volví a casa contigo y los niños. Me acosaron con preguntas y me rogaron que jugara con ellos, todo sin el más mínimo indicio de dolor u odio en sus ojos.",
  ui_story_5076_50760300_111_dialog_content = "Lo que había estado protegiendo todo el tiempo... Eso fue cuando me quedó claro por primera vez.",
  ui_story_5076_50760300_112_dialog_content = "Adras...",
  ui_story_5076_50760300_113_dialog_content = "No me volví más débil por ti, Marcela. Me hice más fuerte.",
  ui_story_5076_50760300_114_dialog_content = "Finalmente tuve miedo a la muerte, y ese miedo me hizo querer seguir viviendo para poder permanecer a tu lado.",
  ui_story_5076_50760300_115_dialog_content = "Después de una vida larga y dolorosa, finalmente entendí lo que significaba vivir.",
  ui_story_5076_50760300_116_dialog_content = "No necesito estatuas o gloria eterna. De hecho, ¡estaría encantado si todos se olvidaran completamente de mí!",
  ui_story_5076_50760300_117_dialog_content = "Si ese día llega, entonces el mundo definitivamente estará en paz.",
  ui_story_5076_50760300_118_dialog_content = "Todo lo que quiero es seguir creando recuerdos contigo, no importa lo ordinarios que puedan ser.",
  ui_story_5076_50760300_119_dialog_content = "Adras... ¡Lo siento mucho! No sé lo que estaba pensando.",
  ui_story_5076_50760300_120_dialog_content = "Nunca me detuve a considerar tus sentimientos.",
  ui_story_5076_50760300_121_dialog_content = "No necesitas preocuparte por eso, Marcela. Por nuestros sueños y recuerdos por venir, nunca me rendiré a mí mismo.",
  ui_story_5076_50760300_122_dialog_content = "Si el mundo alguna vez me necesita algún día, entonces volveré a pisar el campo de batalla una vez más.",
  ui_story_5076_50760300_123_dialog_content = "Porque sé que un mundo tan hermoso como este merece ser protegido—",
  ui_story_5076_50760300_124_dialog_content = "Entonces, por favor no te preocupes, Marcela.",
  ui_story_5076_50760300_125_dialog_content = "¡Con los dioses y Ludweiss como nuestros testigos, por favor deja tus miedos y cásate conmigo!",
  ui_story_5076_50760300_126_dialog_content = "¡Yo... lo haré!",
  ui_story_5076_50760300_127_dialog_content = "<color=#e8d9bb>Al día siguiente, la ciudad organiza una gran boda para el héroe, y todos derraman bendiciones sinceras sobre la pareja.</color>",
  ui_story_5076_50760300_128_dialog_content = "Mientras trabajamos hacia nuestro sueño, sigamos creando hermosos recuerdos juntos.",
  ui_story_5076_50760300_129_dialog_content = "Prometo apreciar cada maravilloso momento de nuestras vidas—",
  ui_story_5076_50760300_130_dialog_content = "Te amo, Marcela.",
  ui_story_5076_50760300_131_dialog_content = "Yo también, mi querido Adras—",
  ui_story_5076_50760300_132_dialog_content = "Te amo.",
  ui_story_5076_50760400_1_dialog_content = "... Así es básicamente cómo están las cosas en el frente; la fuerza expedicionaria está pasando por momentos difíciles y regresará a la capital en breve.",
  ui_story_5076_50760400_2_dialog_content = "Cuando el General Aquiles regrese, solicitaré mi regreso inmediato al deber.",
  ui_story_5076_50760400_3_dialog_content = "Lucharé al lado de todos en la próxima batalla.",
  ui_story_5076_50760400_4_dialog_content = "Pero, Comandante, según las órdenes del General, tus vacaciones aún no han terminado.",
  ui_story_5076_50760400_5_dialog_content = "Y aún no tienes herederos, y el General Aquiles no aprobará que vayas al frente de batalla.",
  ui_story_5076_50760400_6_dialog_content = "La salud de Marcela no nos permite tener un hijo propio... Además, los niños del orfanato también son nuestra familia—",
  ui_story_5076_50760400_7_dialog_content = "¿Vaya? ¿Tenemos un visitante?",
  ui_story_5076_50760400_8_dialog_content = "¡Agustín! ¿Qué buenas noticias nos has traído hoy?",
  ui_story_5076_50760400_9_dialog_content = "Ha pasado un tiempo, señora, y te has vuelto aún más hermosa.",
  ui_story_5076_50760400_10_dialog_content = "Acabo de traer algunas noticias de la capital. Ha pasado un tiempo desde que vimos al Comandante, y todos lo extrañamos.",
  ui_story_5076_50760400_11_dialog_content = "Estoy seguro de que a Adras también le extrañan todos ustedes. ¿Necesitan que regrese antes de lo esperado?",
  ui_story_5076_50760400_12_dialog_content = "Todos seguramente estarían muy contentos, pero, señora, no nos atrevemos a quitarle al Comandante así como así.",
  ui_story_5076_50760400_13_dialog_content = "Se está haciendo tarde, Comandante Adras. También debería regresar a la capital ahora.",
  ui_story_5076_50760400_14_dialog_content = "Cuídate. Estaré allí pronto.",
  ui_story_5076_50760400_15_dialog_content = "Cuídense mucho también, ambos.",
  ui_story_5076_50760400_16_dialog_content = "Adras, es la fuerza de expedición...",
  ui_story_5076_50760400_17_dialog_content = "Están bien, Marcela. No escuches los rumores.",
  ui_story_5076_50760400_18_dialog_content = "¿Quieres volver, verdad?",
  ui_story_5076_50760400_19_dialog_content = "... Prueba esto. He estado trabajando en una nueva técnica de preparación.",
  ui_story_5076_50760400_20_dialog_content = "¿Y exactamente dónde aprendiste—Mmm! ¡Es tan dulce!",
  ui_story_5076_50760400_21_dialog_content = "¡Y no se quema para nada! ¡Me encanta!",
  ui_story_5076_50760400_22_dialog_content = "Lo aprendí de los sacerdotes.",
  ui_story_5076_50760400_23_dialog_content = "¿Así que has estado ayudando con las reparaciones del templo para robar sus técnicas de elaboración de vino?",
  ui_story_5076_50760400_24_dialog_content = "Eso no suena como tú en absoluto, oh gran héroe.",
  ui_story_5076_50760400_25_dialog_content = "Compartieron su conocimiento conmigo voluntariamente para tu información. También dijeron que es bueno para el cuerpo, así que hice dos barriles de eso solo para ti.",
  ui_story_5076_50760400_26_dialog_content = "Los ingredientes que utilicé también fueron un regalo de otros, una muestra de aprecio por todo lo que has hecho por ellos.",
  ui_story_5076_50760400_27_dialog_content = "¿Has estado aceptando regalos por mí cuando no estoy? Es una cosa que te agradezcan por ayudar en el pueblo, pero ¿qué he hecho yo?",
  ui_story_5076_50760400_28_dialog_content = "Deberías simplemente aceptar sus regalos. Devolverlos solo avergonzaría a todos.",
  ui_story_5076_50760400_29_dialog_content = "Bueno, gracias a tu carisma, nuestra casa está llena hasta el tope de regalos.",
  ui_story_5076_50760400_30_dialog_content = "¿Crees que tengo carisma?",
  ui_story_5076_50760400_31_dialog_content = "¡Así es!",
  ui_story_5076_50760400_32_dialog_content = "No, creo que esas personas son realmente amables. Los niños también están siendo especialmente útiles ahora. Justo esta tarde, fueron conmigo a cosechar los campos cerca del orfanato.",
  ui_story_5076_50760400_33_dialog_content = "... Así que sé que estarás cuidado incluso si no estoy cerca por un tiempo.",
  ui_story_5076_50760400_34_dialog_content = "Siempre he sido bueno con las personas, Adras. ¿O lo has olvidado?",
  ui_story_5076_50760400_35_dialog_content = "Sé que hay muchas personas que te necesitan además de nosotros. Nuestros vecinos también lo saben, por eso han sido tan amables últimamente.",
  ui_story_5076_50760400_36_dialog_content = "No quieren tenerte todo para ellos aquí, porque saben que tienes cosas más importantes que hacer.",
  ui_story_5076_50760400_37_dialog_content = "Las llamas de la guerra han costado a tantas personas sus hogares. Al menos, quiero proteger este rincón pacífico de nuestro mundo.",
  ui_story_5076_50760400_38_dialog_content = "Prometo que volveré tan pronto como pueda, Marcela.",
  ui_story_5076_50760400_39_dialog_content = "No te preocupes. Estaremos aquí esperándote.",
  ui_story_5076_50760400_40_dialog_content = "Cuidaremos de nuestro hogar en tu ausencia... Para que nuestro héroe siempre tenga un lugar al que pueda regresar.",
  ui_story_5076_50760400_41_dialog_content = "Volveré a salvo a ti, mi querida Marcela—",
  ui_story_5076_50760400_42_dialog_content = "Por ti y por estas amables personas, eliminaré el mal que nos amenaza en nuestro mundo.",
  ui_story_5076_50760400_43_dialog_content = "Y cuando regrese, nos encontraremos de nuevo en un mar de trigo dorado.",
  ui_story_5076_50760400_44_dialog_content = "Entonces es una promesa.",
  ui_story_5076_50760400_45_dialog_content = "Adras?",
  ui_story_5076_50760400_46_dialog_content = "¿Ludweiss? ¿Qué estás haciendo aquí? ¿Viniste aquí con la fuerza de expedición?",
  ui_story_5076_50760400_47_dialog_content = "Es complicado, y no estoy seguro de por dónde empezar... Aún así, estoy feliz de verte de nuevo.",
  ui_story_5076_50760400_48_dialog_content = "Estoy seguro de que a Aquiles también le alegrará verte. Ven conmigo.",
  ui_story_5076_50760400_49_dialog_content = "¿Es ese... Comandante Adras?",
  ui_story_5076_50760400_50_dialog_content = "¿Comandante Adras ha regresado?",
  ui_story_5076_50760400_51_dialog_content = "¡Comandante Adras!",
  ui_story_5076_50760400_52_dialog_content = "Comandante Adras, ¿estás volviendo al deber?",
  ui_story_5076_50760400_53_dialog_content = "¿Cómo... Cómo terminaron todos tan heridos?",
  ui_story_5076_50760400_54_dialog_content = "Nosotros...",
  ui_story_5076_50760400_55_dialog_content = "¡Dominic! ¡Bruno! ¿Dónde están?",
  ui_story_5076_50760400_56_dialog_content = "Comandante, es realmente bueno verte.",
  ui_story_5076_50760400_57_dialog_content = "Anthony... ¿Qué le pasó a tus ojos?",
  ui_story_5076_50760400_58_dialog_content = "Supongo que estoy envejeciendo después de todo. Tuve un lapsus momentáneo y un astuto Eclipsite me quitó uno de ellos.",
  ui_story_5076_50760400_59_dialog_content = "Lo siento, Comandante, he decepcionado a Dominick. Todo fue porque perdí mi escudo, y para salvarme, él...",
  ui_story_5076_50760400_60_dialog_content = "¿Qué demonios pasó durante la expedición?",
  ui_story_5076_50760400_61_dialog_content = "¿Adras? ¿Eres tú?",
  ui_story_5076_50760400_62_dialog_content = "Realmente eres tú... Todos deben estar tan aliviados de verte, Adras.",
  ui_story_5076_50760400_63_dialog_content = "¿General? Pareces completamente agotado. ¿Qué pasó con el...",
  ui_story_5076_50760400_64_dialog_content = "Nos encontramos con un abismo sombrío en el extremo norte.",
  ui_story_5076_50760400_65_dialog_content = "Innumerables y poderosos Eclipsites seguían saliendo de allí... En términos de fuerza y números, eran como nada que hubiéramos visto antes.",
  ui_story_5076_50760400_66_dialog_content = "Fallé en comandar adecuadamente nuestras tropas, y por lo tanto sufrimos bajas devastadoras.",
  ui_story_5076_50760400_67_dialog_content = "Durante nuestra retirada, Ludweiss también fue herido por el poder de los Eclipsites.",
  ui_story_5076_50760400_68_dialog_content = "No te veas tan preocupado, Adras. ¡Afortunadamente, la Santa Silenciosa estaba allí para salvarme y hacerme sentir como nuevo!",
  ui_story_5076_50760400_69_dialog_content = "Nunca había visto Eclipsites como esos. No son algo que podamos manejar en este momento.",
  ui_story_5076_50760400_70_dialog_content = "Y algunos de ellos... Están más allá de nuestra comprensión. Ni siquiera puedo imaginar una forma de derrotar a esas monstruosidades.",
  ui_story_5076_50760400_71_dialog_content = "No pudimos erradicarlos en el norte, y ahora están marchando hacia la capital real... ¡Malditos sean todos!",
  ui_story_5076_50760400_72_dialog_content = "Tranquilícese, por ahora, General Aquiles. Estoy listo para volver al frente y luchar al lado de todos.",
  ui_story_5076_50760400_73_dialog_content = "Solo nos tomaron desprevenidos la última vez. Con las preparaciones adecuadas, estoy seguro de que podemos poner fin a su maldad.",
  ui_story_5076_50760400_74_dialog_content = "Adras tiene razón. No podemos darnos el lujo de perder contra esas cosas.",
  ui_story_5076_50760400_75_dialog_content = "Para desviar la horda invasora de Eclipsites, creo que lo mejor es que vuelva a la fuerza y comencemos juntos los preparativos de combate.",
  ui_story_5076_50760400_76_dialog_content = "De esa manera, podemos detener su marcha antes de que lleguen a nuestra casa.",
  ui_story_5076_50760400_77_dialog_content = "Adras... Realmente has cambiado.",
  ui_story_5076_50760400_78_dialog_content = "¿Cómo están las cosas últimamente?",
  ui_story_5076_50760400_79_dialog_content = "He estado bien. Nuestros vecinos nos han estado cuidando bien allí afuera.",
  ui_story_5076_50760400_80_dialog_content = "Finalmente entendí lo que querías decir cuando me hablaste sobre la \"belleza de la paz\".",
  ui_story_5076_50760400_81_dialog_content = "¿No temerás a la muerte si te envío de nuevo al frente de batalla?",
  ui_story_5076_50760400_82_dialog_content = "Ya no eres el mismo hombre. ¿Realmente puedes abandonar tu instinto de autopreservación como antes?",
  ui_story_5076_50760400_83_dialog_content = "No puedo, y eso es porque... ahora entiendo el significado del miedo.",
  ui_story_5076_50760400_84_dialog_content = "Pero incluso así, tengo que proteger esos campos de trigo dorado y a las personas que llaman hogar a ese lugar.",
  ui_story_5076_50760400_85_dialog_content = "Por eso tengo que sobrevivir.",
  ui_story_5076_50760400_86_dialog_content = "Sobreviviré junto con mis camaradas en armas, y volveremos a nuestros seres queridos juntos.",
  ui_story_5076_50760400_87_dialog_content = "Ya veo... Eso es un alivio.",
  ui_story_5076_50760400_88_dialog_content = "Eres mucho más fuerte ahora que en el pasado.",
  ui_story_5076_50760400_89_dialog_content = "Estoy seguro de que puedo confiar en tu escudo con mi vida, igual que antes.",
  ui_story_5076_50760400_90_dialog_content = "Por la gloria de nuestro reino, cabalgaremos una vez más hacia la batalla.",
  ui_story_5076_50760400_91_dialog_content = "Parece que te sientes mucho mejor ahora. ¡No me di cuenta de que Adras era un orador tan poderoso!",
  ui_story_5076_50760400_92_dialog_content = "Supongo que Adras realmente es un héroe para todos.",
  ui_story_5076_50760400_93_dialog_content = "De acuerdo. Si todos en nuestro ejército fueran como Adras... Incluso los Eclipsites más fuertes no tendrían oportunidad contra nosotros.",
  ui_story_5076_50760400_94_dialog_content = "¡No me importaría ser parte de ese ejército!",
  ui_story_5076_50760400_95_dialog_content = "Debería comenzar los preparativos de inmediato. Si me disculpas.",
  ui_story_5076_50760400_96_dialog_content = "Adras.",
  ui_story_5076_50760400_97_dialog_content = "¿Si?",
  ui_story_5076_50760400_98_dialog_content = "Aprecia todo lo que tienes en la vida.",
  ui_story_5076_50760400_99_dialog_content = "No tengo intención de hacer lo contrario, señor.",
  ui_story_5076_50760400_100_dialog_content = "Después de todo, le hice una promesa a ella.",
  ui_story_5076_50760501_1_dialog_content = "Esto debería ser lo último. No creo que haya nada más que sacar del orfanato.",
  ui_story_5076_50760501_2_dialog_content = "¿Son estas... espadas de entrenamiento de madera Adras?",
  ui_story_5076_50760501_3_dialog_content = "Los niños siguen pidiendo aprender esgrima para poder proteger la ciudad. Traer estos de vuelta podría hacer que se calmen.",
  ui_story_5076_50760501_4_dialog_content = "Ah, si tan sólo pudiera traer este mural de nuestro día de boda. Fue un momento tan precioso...",
  ui_story_5076_50760501_5_dialog_content = "Nunca pensé que los Eclipsites llegarían a este lugar.",
  ui_story_5076_50760501_6_dialog_content = "¿Cuánto tiempo más permanecerá cerrado el orfanato? Desearía poder ver a esos niños felices corriendo por los campos de trigo una vez más.",
  ui_story_5076_50760501_7_dialog_content = "Todo estará bien. Mientras Adras y los demás luchan en el frente, nosotros lucharemos para mantener esta ciudad segura.",
  ui_story_5076_50760501_8_dialog_content = "Lamento que aún no me haya recuperado... De lo contrario, estaría allí fuera ayudando a todos también.",
  ui_story_5076_50760501_9_dialog_content = "No necesitas disculparte, Ludweiss. Ya has hecho tanto por nosotros.",
  ui_story_5076_50760501_10_dialog_content = "Tus advertencias oportunas nos han mantenido a salvo estos últimos días.",
  ui_story_5076_50760501_11_dialog_content = "¿Se están reparando ahora las defensas de la ciudad?",
  ui_story_5076_50760501_12_dialog_content = "Sí. También estamos construyendo un refugio debajo del templo y un túnel de escape.",
  ui_story_5076_50760501_13_dialog_content = "Todos están trabajando tan duro juntos y animándose mutuamente todo el camino.",
  ui_story_5076_50760501_14_dialog_content = "Las personas Adras entrenadas también han formado una pequeña milicia. Puedo decir que todos están llenos de esperanza.",
  ui_story_5076_50760501_15_dialog_content = "Todo es gracias a ti, Marcela... Antes de que llegaran los refuerzos, fuiste tú quien les dio esperanza y los impulsó a actuar.",
  ui_story_5076_50760501_16_dialog_content = "Solo estaba haciendo mi pequeña parte. Ellos son los que hicieron todo el trabajo—",
  ui_story_5076_50760501_17_dialog_content = "Vamos, traigamos estas cosas de vuelta para los niños.",
  ui_story_5076_50760501_18_dialog_content = "¿Achilles te envió para entregar esta carta? ¿Cuál es la situación en el frente de batalla?",
  ui_story_5076_50760501_19_dialog_content = "El Comandante Adras, con su legión, está repeliendo el masivo ataque a la capital y ha asegurado una serie de victorias.",
  ui_story_5076_50760501_20_dialog_content = "Su Majestad le ordenó que asistiera al General Aquiles en liderar las tropas para perseguir y exterminar a los Eclipsites.",
  ui_story_5076_50760501_21_dialog_content = "El comandante asignado aquí para defender esta ciudad es un seguidor del Sumo Sacerdote Lucius. Eso es todo el mensaje que se supone que debo entregar.",
  ui_story_5076_50760501_22_dialog_content = "Pero aparte de eso, señorita Ludweiss, tengo algo de información...",
  ui_story_5076_50760501_23_dialog_content = "Parece que el Sumo Sacerdote Lucius está compitiendo por el mérito, con la intención de concentrar fuerzas para atacar los flancos de los Eclipsites. ¡Ya se ha ido y ha reubicado las fuerzas defensoras en el camino!",
  ui_story_5076_50760501_24_dialog_content = "En otras palabras, es poco probable que esta ciudad reciba algún apoyo militar. ¿Es eso?",
  ui_story_5076_50760501_25_dialog_content = "... Me quedaré, incluso si significa dar mi vida para proteger a los civiles en la ciudad.",
  ui_story_5076_50760501_26_dialog_content = "¡No digas eso!",
  ui_story_5076_50760501_27_dialog_content = "¡La vida es lo más preciado en este mundo! ¡No hables de ella como si fuera algo menos que eso!",
  ui_story_5076_50760501_28_dialog_content = "¡S-Sí! ¡Pido disculpas por eso!",
  ui_story_5076_50760501_29_dialog_content = "Tienes experiencia militar. Dejaré el mando de la milicia en tus manos.",
  ui_story_5076_50760501_30_dialog_content = "Tengo que...",
  ui_story_5076_50760501_31_dialog_content = "¿Tengo que hacer qué, Ludweiss?",
  ui_story_5076_50760501_32_dialog_content = "¿Marcela...?",
  ui_story_5076_50760501_33_dialog_content = "Voy a ayudar a defender las paredes de la ciudad.",
  ui_story_5076_50760501_34_dialog_content = "¿Así que escuchaste todo?",
  ui_story_5076_50760501_35_dialog_content = "Sí, pero no le diré a nadie sobre esto todavía. Ustedes dos deben hacer lo mismo.",
  ui_story_5076_50760501_36_dialog_content = "Voy a defender este lugar con todos. Esta es nuestra casa, así como la casa del gran héroe Adras.",
  ui_story_5076_50760501_37_dialog_content = "Tengo que salir por un rato, Marcela.",
  ui_story_5076_50760501_38_dialog_content = "Entonces por favor ten cuidado... Y no te esfuerces demasiado.",
  ui_story_5076_50760501_39_dialog_content = "¿A dónde exactamente vas?",
  ui_story_5076_50760501_40_dialog_content = "La horda de Eclipsites estará aquí pronto. Tengo que hacer algo que solo nosotros, los Caelestites, podemos hacer...",
  ui_story_5076_50760501_41_dialog_content = "Usaré mis poderos para deslizarme entre sus filas y entregar un mensaje a Adras.",
  ui_story_5076_50760501_42_dialog_content = "¡Pero eso es demasiado peligroso!",
  ui_story_5076_50760501_43_dialog_content = "Adras necesita saberlo. Por tu bien, y por el bien de toda la ciudad.",
  ui_story_5076_50760501_44_dialog_content = "Nunca podríamos pagarte por todo lo que haces por nosotros, Ludweiss...",
  ui_story_5076_50760501_45_dialog_content = "Por favor tenga cuidado.",
  ui_story_5076_50760501_46_dialog_content = "Solo soy una vagabunda que perdió su camino. Solo gracias a todos aquí recordé la belleza de Eraveil, mi hogar.",
  ui_story_5076_50760501_47_dialog_content = "Me aseguraré de traer a Adras aquí. Hasta entonces, mantente alerta y no pierdas la esperanza.",
  ui_story_5076_50760501_48_dialog_content = "(Definitivamente lo lograré—)",
  ui_story_5076_50760501_49_dialog_content = "(No importa cuán lejos o cuán difícil pueda ser el camino—)",
  ui_story_5076_50760501_50_dialog_content = "<color=#e8d9bb>Los Eclipsites del lejano norte han infestado todo el continente, incendiando incluso la naturaleza salvaje.</color>",
  ui_story_5076_50760501_51_dialog_content = "<color=#e8d9bb>El fuego devasta las casas de los civiles, y los campos de trigo que una vez fueron serenos están casi completamente quemados.</color>",
  ui_story_5076_50760501_52_dialog_content = "Adras!",
  ui_story_5076_50760501_53_dialog_content = "¿Eh? ¿Qué pasa con todos los gritos?",
  ui_story_5076_50760501_54_dialog_content = "Adras! Yo... Finalmente te encontré...",
  ui_story_5076_50760501_55_dialog_content = "¿Ludweiss? ¿Qué haces aquí? Esas quemaduras... ¡Estás seriamente herido!",
  ui_story_5076_50760501_56_dialog_content = "¡Llama a un médico, Anthony!",
  ui_story_5076_50760501_57_dialog_content = "¡Olvida eso! ¡T-Tú tienes que venir conmigo!",
  ui_story_5076_50760501_58_dialog_content = "¡Lucius trasladó todas sus fuerzas fuera de la ciudad! ¡Dejó a Marcela y a los demás para que se defendieran por sí mismos!",
  ui_story_5076_50760501_59_dialog_content = "¿Qué dijiste?",
  ui_story_5076_50760501_60_dialog_content = "Marcela, yo...",
  ui_story_5076_50760501_61_dialog_content = "¡Maldita sea! Estábamos a punto de lanzar un contraataque decisivo!",
  ui_story_5076_50760501_62_dialog_content = "Como comandante en funciones, no puedo simplemente abandonar a mis soldados.",
  ui_story_5076_50760501_63_dialog_content = "Ve, Adras.",
  ui_story_5076_50760501_64_dialog_content = "Pero General—",
  ui_story_5076_50760501_65_dialog_content = "El enemigo está prácticamente muerto. Tú y la Legión Northwind ya han hecho suficiente por el reino.",
  ui_story_5076_50760501_66_dialog_content = "Nuestras fuerzas principales deberían ser las que protegen tu hogar, pero desafortunadamente... Tú y tus hombres tendrán que hacer este viaje solos.",
  ui_story_5076_50760501_67_dialog_content = "Es una orden.",
  ui_story_5076_50760501_68_dialog_content = "General Aquiles... entendido.",
  ui_story_5076_50760501_69_dialog_content = "¿Estás seguro de que quieres venir conmigo, Ludweiss? Nuestro ejército tiene varios médicos capaces.",
  ui_story_5076_50760501_70_dialog_content = "Si no puedes hacer la marcha, siempre puedes quedarte aquí y recuperarte.",
  ui_story_5076_50760501_71_dialog_content = "No, tengo que volver contigo y asegurarme de que Marcela esté bien.",
  ui_story_5076_50760501_72_dialog_content = "Prometí que te traería de vuelta a ella.",
  ui_story_5076_50760501_73_dialog_content = "Entonces, vamos.",
  ui_story_5076_50760501_74_dialog_content = "¡Soldados de la Legión Northwind! Escuchen mi llamado—",
  ui_story_5076_50760501_75_dialog_content = "<color=#e8d9bb>Su voz resonante se hace eco a través de las tiendas, y los soldados responden al unísono.</color>",
  ui_story_5076_50760501_76_dialog_content = "<color=#e8d9bb>Soldados, cuya patria ha sido protegida por su comandante innumerables veces, finalmente llegan a defender el hogar de su comandante.</color>",
  ui_story_5076_50760501_77_dialog_content = "¡No tienen fin, fuera de mi camino!!!",
  ui_story_5076_50760501_78_dialog_content = "¿Por qué hay tantos Eclipsites debajo de la ciudad?",
  ui_story_5076_50760501_79_dialog_content = "¿Se están reuniendo todos aquí?",
  ui_story_5076_50760501_80_dialog_content = "¿Cuántos soldados ha retirado Lucius de la pelea? ¿Cuántas vidas se han perdido por su culpa?!",
  ui_story_5076_50760501_81_dialog_content = "Mantén la calma, Adras. Estamos cerca de la ciudad—",
  ui_story_5076_50760501_82_dialog_content = "Has estado dejando tropas en cada ciudad que pasamos. Por eso parece que hay aún más enemigos con los que luchar ahora.",
  ui_story_5076_50760501_83_dialog_content = "No nos estamos moviendo lo suficientemente rápido... ¡Prometí que los protegería a todos! Les di mi palabra!",
  ui_story_5076_50760501_84_dialog_content = "¡Lo vi! Comandante Adras, los muros de la ciudad están intactos, y parece que la puerta de la ciudad acaba de ser violada.",
  ui_story_5076_50760501_85_dialog_content = "La gente se está refugiando en el templo, Adras.",
  ui_story_5076_50760501_86_dialog_content = "Hay un túnel de escape debajo de él. Si no pueden defender las puertas del templo, pueden usar ese túnel para escapar detrás de la ciudad.",
  ui_story_5076_50760501_87_dialog_content = "Dieter, Vivia, lleven un equipo de caballeros y diríjanse a las afueras de la ciudad. Busquen supervivientes y eliminen a cualquier Eclipsites que merodee por la zona.",
  ui_story_5076_50760501_88_dialog_content = "Quintas, forma una falange y flanquea al enemigo desde ambos lados. No dejes escapar a un solo Eclipsite.",
  ui_story_5076_50760501_89_dialog_content = "Todos los demás, vengan conmigo. ¡Estamos atacando por su retaguardia y forzando nuestro camino hacia la ciudad!",
  ui_story_5076_50760501_90_dialog_content = "Mantente cerca, Ludweiss.",
  ui_story_5076_50760501_91_dialog_content = "<color=#FFB400>¡A la batalla—!!!</color>",
  ui_story_5076_50760501_92_dialog_content = "<color=#FFB400>¡Elimina hasta el último de estos sucios Eclipsites!</color>",
  ui_story_5076_50760501_93_dialog_content = "¡Comandante, el Templo aún no ha caído, y los miembros de la milicia aún están defendiendo dentro del salón principal!",
  ui_story_5076_50760501_94_dialog_content = "Solo un poco más rápido—",
  ui_story_5076_50760501_95_dialog_content = "¡Espérame, Adras!",
  ui_story_5076_50760501_96_dialog_content = "Ay, ¿es mi vieja herida? ¿Por qué está molestando justo ahora de todos los momentos...",
  ui_story_5076_50760501_97_dialog_content = "No, algo anda mal... Algo en mi cabeza...",
  ui_story_5076_50760501_98_dialog_content = "Adras...",
  ui_story_5076_50760502_1_dialog_content = "¡Es Adras!",
  ui_story_5076_50760502_2_dialog_content = "Adras ha venido a nuestro rescate!",
  ui_story_5076_50760502_3_dialog_content = "¡Hola, Adras!",
  ui_story_5076_50760502_4_dialog_content = "Todos están a salvo ahora, así que por favor mantengan la calma. Hemos logrado asegurar una ruta de escape.",
  ui_story_5076_50760502_5_dialog_content = "¿Todos están bien? ¿Ha habido alguna baja?",
  ui_story_5076_50760502_6_dialog_content = "¿Hay alguna otra área que necesite apoyo?",
  ui_story_5076_50760502_7_dialog_content = "No, Comandante Adras, nosotros somos la retaguardia; los demás ya han escapado por el pasaje.",
  ui_story_5076_50760502_8_dialog_content = "Todo gracias a Marcela; ella nos motivó a defender la ciudad, y por eso pudimos aguantar estos días.",
  ui_story_5076_50760502_9_dialog_content = "Si hubieras llegado aquí un poco más tarde, todos podrían haberse ido ya...",
  ui_story_5076_50760502_10_dialog_content = "¿Marcela...? ¿Dónde está ella ahora? ¿Ya escapó?",
  ui_story_5076_50760502_11_dialog_content = "¿Eh? ¿No te encontraste con Marcela en tu camino aquí?",
  ui_story_5076_50760502_12_dialog_content = "Para ganar tiempo para la retirada de todos, ella lideró la vanguardia cerca del Templo para distraer a los Eclipsites...",
  ui_story_5076_50760502_13_dialog_content = "No... No...",
  ui_story_5076_50760502_14_dialog_content = "No me asustes así, mi amor—",
  ui_story_5076_50760502_15_dialog_content = "¡Espera, Adras! ¡Déjame intentar sentir su ubicación!",
  ui_story_5076_50760502_16_dialog_content = "Por favor, Ludweiss...",
  ui_story_5076_50760502_17_dialog_content = "¡No hay necesidad de que el resto de ustedes me siga! Retírense y defiendan a los civiles de la ciudad—",
  ui_story_5076_50760502_18_dialog_content = "No puedo filtrar todos los pensamientos y sentimientos caóticos. Todo lo que puedo decir es que hay Eclipsites reuniéndose al este del templo.",
  ui_story_5076_50760502_19_dialog_content = "¡Fuera de mi camino, monstruos podridos!",
  ui_story_5076_50760502_20_dialog_content = "¡Más rápido! ¡Necesito moverme más rápido!!!",
  ui_story_5076_50760502_21_dialog_content = "Este lugar—",
  ui_story_5076_50760502_22_dialog_content = "La gente en el suelo estaba con la milicia. Qué vista tan horrible...",
  ui_story_5076_50760502_23_dialog_content = "También lograron matar a muchos Eclipsites justo más adelante.",
  ui_story_5076_50760502_24_dialog_content = "Desafortunadamente, este lugar está más allá de salvar—",
  ui_story_5076_50760502_25_dialog_content = "¡Ah! No... es Agustín... Esto no puede ser.",
  ui_story_5076_50760502_26_dialog_content = "Valientes y honorables soldados... May que sus almas finalmente conozcan la paz.",
  ui_story_5076_50760502_27_dialog_content = "... Eclipsites podridos.",
  ui_story_5076_50760502_28_dialog_content = "¡Marcela! ¿¡Puedes oírme!?",
  ui_story_5076_50760502_29_dialog_content = "¡No te preocupes, voy a por ti!",
  ui_story_5076_50760502_30_dialog_content = "(N-No—)",
  ui_story_5076_50760502_31_dialog_content = "¿Quién? ¿Quién está ahí?",
  ui_story_5076_50760502_32_dialog_content = "(Alguien está en mi cabeza, hablándome... ¿Es por mis lesiones anteriores?)",
  ui_story_5076_50760502_33_dialog_content = "(Tienes que despertar—)",
  ui_story_5076_50760502_34_dialog_content = "(No mires hasta el final—)",
  ui_story_5076_50760502_35_dialog_content = "¿Qué?",
  ui_story_5076_50760502_36_dialog_content = "<size=40>¡No... Noooo!!!</size>",
  ui_story_5076_50760502_37_dialog_content = "Adras???",
  ui_story_5076_50760502_38_dialog_content = "Argh, mi cabeza... Me está matando.",
  ui_story_5076_50760502_39_dialog_content = "<size=40>No me asustes así, Marcela—</size>",
  ui_story_5076_50760502_40_dialog_content = "<color=#FFB400><size=45>¡¡¡Marcela!!!</size></color>",
  ui_story_5076_50760502_41_dialog_content = "Que esta pasando...",
  ui_story_5076_50760502_42_dialog_content = "Adras, Marcela...",
  ui_story_5076_50760502_43_dialog_content = "Espérame...",
  ui_story_5076_50760502_44_dialog_content = "!!!",
  ui_story_5076_50760502_45_dialog_content = "Gracias sean a los dioses—",
  ui_story_5076_50760502_46_dialog_content = "Por no robarme a mi amada, mi dulce Marcela—",
  ui_story_5076_50760502_47_dialog_content = "¡Marcela! Soy yo, ¡estoy aquí! Volví, justo como lo prometí.",
  ui_story_5076_50760502_48_dialog_content = "No te preocupes, nos vamos a casa ahora...",
  ui_story_5076_50760502_49_dialog_content = "(Los recuerdos son—)",
  ui_story_5076_50760502_50_dialog_content = "<color=#FFB400>(Una maldición.)</color>",
  ui_story_5076_50760502_51_dialog_content = "(Pero por ahora... Por favor, no te interpongas en su reunión.)",
  ui_story_5076_50760502_52_dialog_content = "Esa voz en mi cabeza... ¿Quién eres...?",
  ui_story_5076_50760502_53_dialog_content = "Por fin has vuelto, Adras.",
  ui_story_5076_50760502_54_dialog_content = "Esperé tanto tiempo... por ti.",
  ui_story_5076_50760502_55_dialog_content = "Guarda tus fuerzas, mi amor. Conseguiré un sanador para atender tus heridas antes de que volvamos a casa.",
  ui_story_5076_50760502_56_dialog_content = "Esas dos barricas de vino que me dejaste... Las compartí con todos.",
  ui_story_5076_50760502_57_dialog_content = "Todos dijeron que estaba delicioso, y que su dulzura los hacía sentir muy felices.",
  ui_story_5076_50760502_58_dialog_content = "Por eso no teníamos miedo, ni siquiera por un momento—",
  ui_story_5076_50760502_59_dialog_content = "Adras... cada vez que pienso en ti, mi corazón se llena de esperanza.",
  ui_story_5076_50760502_60_dialog_content = "Gracias por cumplir tu promesa.",
  ui_story_5076_50760600_1_dialog_content = "<color=#e8d9bb>La ciudad, una vez devastada por monstruos, ahora abraza los días de reconstrucción. La fe proveniente de los héroes llena de esperanza a sus residentes.</color>",
  ui_story_5076_50760600_2_dialog_content = "<color=#e8d9bb>Aun así, en medio de esta atmósfera floreciente, muchos aún se encuentran sin un hogar.</color>",
  ui_story_5076_50760600_3_dialog_content = "¡Ten cuidado al mover los escombros y mantén un ojo en los peatones! Si necesitas ayuda, ¡pide a los soldados de la Legión!",
  ui_story_5076_50760600_4_dialog_content = "¡Sí señor!",
  ui_story_5076_50760600_5_dialog_content = "Vamos.",
  ui_story_5076_50760600_6_dialog_content = "Claro.",
  ui_story_5076_50760600_7_dialog_content = "Adras, ¿qué...?",
  ui_story_5076_50760600_8_dialog_content = "No es nada. Solo vamos a dar un paseo.",
  ui_story_5076_50760600_9_dialog_content = "\"¿Nosotros\"? Oh... ¡Oh! Por favor, no te preocupes demasiado; pronto completaremos la reconstrucción.",
  ui_story_5076_50760600_10_dialog_content = "¿Marcela? Pensé que eras amiga de ese hombre... ¿Por qué al menos no saludaste?",
  ui_story_5076_50760600_11_dialog_content = "... Está bien. Sigamos adelante.",
  ui_story_5076_50760600_12_dialog_content = "¿Adónde te gustaría ir? ¿Al templo, tal vez?",
  ui_story_5076_50760600_13_dialog_content = "¡No! A cualquier lugar menos al templo! Todavía... tengo miedo de ese lugar.",
  ui_story_5076_50760600_14_dialog_content = "Está bien, podemos ir a otro lugar. ¿Por qué no vamos a visitar a los niños? Han estado bien, pero estoy seguro de que todavía estás preocupado por ellos.",
  ui_story_5076_50760600_15_dialog_content = "Lo encontré, Aquiles. Está aquí.",
  ui_story_5076_50760600_16_dialog_content = "...",
  ui_story_5076_50760600_17_dialog_content = "Adras... ¿Estás bien?",
  ui_story_5076_50760600_18_dialog_content = "... ¿Ludweiss?",
  ui_story_5076_50760600_19_dialog_content = "La batalla ha terminado, Adras. ¿Por qué sigues aquí?",
  ui_story_5076_50760600_20_dialog_content = "No queda nadie para defender este lugar. Tengo que proteger a la gente aquí.",
  ui_story_5076_50760600_21_dialog_content = "¡Ah! No tengas miedo, Marcela. Solo es el General Aquiles.",
  ui_story_5076_50760600_22_dialog_content = "Lo siento, pero la batalla realmente afectó a Marcela. Por favor, perdónala si está demasiado asustada para saludar.",
  ui_story_5076_50760600_23_dialog_content = "Adras, Marcela es—",
  ui_story_5076_50760600_24_dialog_content = "¡Aquiles!",
  ui_story_5076_50760600_25_dialog_content = "¿Qué pasa? Ustedes dos están actuando de manera extraña, especialmente tú Ludweiss. ¿Por qué no has venido a visitar a Marcela más a menudo?",
  ui_story_5076_50760600_26_dialog_content = "... Mírame, Adras.",
  ui_story_5076_50760600_27_dialog_content = "¿Sí? Oh, antes de que lo olvide... ¿Se han encargado de los Eclipsites en el frente? ¿Podemos finalmente disfrutar de algo de paz de nuevo?",
  ui_story_5076_50760600_28_dialog_content = "Logramos empujar a los Eclipsites hacia el norte, pero aún no podemos hacer nada con respecto al abismo que encontramos allí.",
  ui_story_5076_50760600_29_dialog_content = "¿Estás dispuesto a volver a la lucha, Adras?",
  ui_story_5076_50760600_30_dialog_content = "Por supuesto. Es mi deber proteger mi hogar y mi país, después de todo.",
  ui_story_5076_50760600_31_dialog_content = "¿Estás dispuesta a dejarme volver a la batalla, verdad Marcela? No te preocupes, siempre cumpliré mi promesa contigo.",
  ui_story_5076_50760600_32_dialog_content = "...",
  ui_story_5076_50760600_33_dialog_content = "Ludweiss, una vez me dijiste que el amor es la fuente del poder de un Caelestite. Impulsados por la fuerza de las emociones, tú y tu gente han logrado cosas extraordinarias.",
  ui_story_5076_50760600_34_dialog_content = "Dime, ¿existe alguna forma de extraer las emociones de un Aurorian y preservarlas?",
  ui_story_5076_50760600_35_dialog_content = "¿Qué estás proponiendo exactamente?",
  ui_story_5076_50760600_36_dialog_content = "En este momento, Adras necesita ser impulsado a la acción por el odio y la venganza. Sin embargo, no quiero que el amor en su corazón sea consumido por ello.",
  ui_story_5076_50760600_37_dialog_content = "¿De qué demonios están hablando ustedes dos?",
  ui_story_5076_50760600_38_dialog_content = "Ludweiss, necesito saber si hay una forma de extraer ese amor y mantenerlo a salvo.",
  ui_story_5076_50760600_39_dialog_content = "Entiendo... Pensaré en algo.",
  ui_story_5076_50760600_40_dialog_content = "¿Estás dispuesto a prestarme tu escudo y fuerza de nuevo, Adras?",
  ui_story_5076_50760600_41_dialog_content = "¡Claro que lo soy!",
  ui_story_5076_50760600_42_dialog_content = "¿Cuánto odias a los Eclipsites? ¿Estás dispuesto a dedicar tu vida y todo lo que eres a su completa aniquilación?",
  ui_story_5076_50760600_43_dialog_content = "Los Eclipsites... ¡Eso va sin decir! No tengo nada más que odio en mi corazón por ellos...",
  ui_story_5076_50760600_44_dialog_content = "Incluso con el peso de la eternidad sobre tus hombros, ¿juras luchar contra este mal con todo tu corazón hasta que no quede nada?",
  ui_story_5076_50760600_45_dialog_content = "Yo... lo juro.",
  ui_story_5076_50760600_46_dialog_content = "Entonces, en nombre de nuestros orgullosos soldados y yo mismo, nuestras vidas están una vez más en tus hábiles manos.",
  ui_story_5076_50760600_47_dialog_content = "Bienvenido de nuevo a la línea de deber, Adras.",
  ui_story_5076_50760600_48_dialog_content = "Bienvenido de nuevo a la guerra.",
  ui_story_5076_50760600_49_dialog_content = "Entonces, ¿por dónde debería empezar?",
  ui_story_5076_50760600_50_dialog_content = "Para erradicar el abismo en el norte, la corte real propuso un nuevo método para mejorar nuestros poderes.",
  ui_story_5076_50760600_51_dialog_content = "Un proyecto que nos consumirá, pero no antes de que purguemos nuestro mundo de todo mal.",
  ui_story_5076_50760600_52_dialog_content = "Y el nombre de ese proyecto es—",
  ui_story_5076_50760600_53_dialog_content = "<color=#FFB400>Los Cazadores Silenciosos.</color>",
  ui_story_5076_50760701_1_dialog_content = "<color=#e8d9bb>Tras un gran triunfo en el frente principal, las fuerzas reales se dispersaron y contraatacaron, con el objetivo de recuperar las ciudades invadidas por los Eclipsites.</color>",
  ui_story_5076_50760701_2_dialog_content = "<color=#e8d9bb>Entre ellos, algunos se han reducido completamente a un \"nido\" de los Eclipsites.</color>",
  ui_story_5076_50760701_3_dialog_content = "<color=#e8d9bb>En ese momento, los \"héroes\" con nuevas fachadas subirán al escenario.</color>",
  ui_story_5076_50760701_4_dialog_content = "¡Informe! Las centinelas han confirmado la condición dentro de la ciudad, ¡ha caído completamente, con Eclipsites corriendo desenfrenados!",
  ui_story_5076_50760701_5_dialog_content = "¿Y la gente? ¿Hay algún signo de su supervivencia?",
  ui_story_5076_50760701_6_dialog_content = "... Ninguno ha sobrevivido.",
  ui_story_5076_50760701_7_dialog_content = "Detén la ofensiva. Tus soldados no tienen forma de abrirse camino hasta la ciudad.",
  ui_story_5076_50760701_8_dialog_content = "Los Eclipsites no conocen el miedo. A menos que hagamos caer la ciudad sobre sus cabezas, no se retirarán.",
  ui_story_5076_50760701_9_dialog_content = "General... No, Capitán, ¿qué hacemos ahora?",
  ui_story_5076_50760701_10_dialog_content = "Uno de mis compañeros de escuadrón ya está en camino. Ponga al resto de sus fuerzas en espera en la retaguardia.",
  ui_story_5076_50760701_11_dialog_content = "Te refieres a... ¡Ah!",
  ui_story_5076_50760701_12_dialog_content = "Tú ahí, soldado. Estás en mi camino, así que por favor da un paso a la derecha.",
  ui_story_5076_50760701_13_dialog_content = "<color=#e8d9bb>Siguiendo las órdenes del comandante desconocido, el soldado se desplaza ligeramente a un lado, y un destello de relámpago estalla de sus yemas de los dedos, demoliendo la puerta de la ciudad que había resistido su ataque prolongado.</color>",
  ui_story_5076_50760701_14_dialog_content = "Las puertas pueden estar abiertas, pero todavía hay muchos Eclipsites astutos escondidos detrás de las murallas de la ciudad. Los dejaré a tu cargo... Cynthia.",
  ui_story_5076_50760701_15_dialog_content = "<color=#e8d9bb>Con el arco largo tenso como una luna creciente, la heroína de tono verde elegante libera una lluvia de flechas. Cada vez que ella tira de la cuerda del arco, los Eclipsites expertos en ataques a distancia caen uno tras otro.</color>",
  ui_story_5076_50760701_16_dialog_content = "¡Buen disparo! Debes haberlos agitado realmente con ese último ataque, porque están empezando a salir en masa de la puerta.",
  ui_story_5076_50760701_17_dialog_content = "¡Conmigo, caballeros! ¡Vamos a cargar en la batalla!",
  ui_story_5076_50760701_18_dialog_content = "Los caballeros no tienen ninguna oportunidad contra esos gigantes Eclipsites, Freya.",
  ui_story_5076_50760701_19_dialog_content = "¡Estarán bien! Friegson, ¡la primera ola es toda tuya!",
  ui_story_5076_50760701_20_dialog_content = "<color=#e8d9bb>Con sus palabras resonantes, un incendio se enciende a lo lejos. Las llamas rugientes engullen sin piedad a esos monstruos fornidos.</color>",
  ui_story_5076_50760701_21_dialog_content = "<color=#e8d9bb>Una ciudad que tomaría días para ser conquistada por fuerzas ordinarias es fácilmente conquistada por ellos.</color>",
  ui_story_5076_50760701_22_dialog_content = "<color=#e8d9bb>La caballería liderada por la Santa Silenciosa Freya aplasta sin esfuerzo a los Eclipsites, su lanza barre con una dominancia inigualable. Los Eclipsites caídos son rápidamente envueltos en lenguas de fuego, retorciéndose de agonía.</color>",
  ui_story_5076_50760701_23_dialog_content = "Qué cruel... No hay necesidad de jugar con ellos así, Friegson.",
  ui_story_5076_50760701_24_dialog_content = "Los Eclipsites no merecen simpatía.",
  ui_story_5076_50760701_25_dialog_content = "¿Dónde está el Vice Capitán?",
  ui_story_5076_50760701_26_dialog_content = "Los Eclipsites se están retirando a la ciudad. Parece que después de todo pueden sentir algún tipo de miedo... Pero estoy seguro de que él ya los está esperando allí.",
  ui_story_5076_50760701_27_dialog_content = "Si no escapan, al menos se les dará una muerte amable... Eso es más de lo que merecen.",
  ui_story_5076_50760701_28_dialog_content = "<color=#e8d9bb>... Mientras los Eclipsites, impulsados por un miedo instintivo, huyen hacia la puerta trasera, hay una figura que se mantiene en pie para bloquear su camino.</color>",
  ui_story_5076_50760701_29_dialog_content = "<color=#e8d9bb>La despiadada magia del agua, junto con esa frígida espada colosal, aplasta sin esfuerzo a aquellos que se atrevieron a avanzar, dejando a los Eclipsites sin medios de escape.</color>",
  ui_story_5076_50760701_30_dialog_content = "Muerte a todos los enemigos... Muerte a todos los enemigos... Muerte a todos los enemigos...",
  ui_story_5076_50760701_31_dialog_content = "¡Eclipsites! <size=45>¡¡¡Muere!!!</size>",
  ui_story_5076_50760702_1_dialog_content = "Eclipsites—Muere—",
  ui_story_5076_50760702_2_dialog_content = "¡Todos ustedes deben morir!",
  ui_story_5076_50760702_3_dialog_content = "Cálmate, Adras... Estás asustando a los soldados.",
  ui_story_5076_50760702_4_dialog_content = "¿M-Marcela? ¡Quedarse atrás, es peligroso aquí!",
  ui_story_5076_50760702_5_dialog_content = "¿Es ese... el Cazador Silencioso?",
  ui_story_5076_50760702_6_dialog_content = "Tan aterrador. Es difícil imaginar que él es un héroe legendario. ¡Míralo! Él es absolutamente...",
  ui_story_5076_50760702_7_dialog_content = "Manténlo bajo; él podría escucharnos.",
  ui_story_5076_50760702_8_dialog_content = "¿La batalla acabo? ¿Todos están a salvo ahora?",
  ui_story_5076_50760702_9_dialog_content = "Lo hiciste bien, Adras.",
  ui_story_5076_50760702_10_dialog_content = "Pero... No quedó ni un solo superviviente en esta ciudad... Esos malditos Eclipsites.",
  ui_story_5076_50760702_11_dialog_content = "Eso no es tu culpa. El resto del equipo viene, ahora vamos.",
  ui_story_5076_50760702_12_dialog_content = "...",
  ui_story_5076_50760702_13_dialog_content = "¡Otra celebración de hoguera para los Cazadores Silenciosos!",
  ui_story_5076_50760702_14_dialog_content = "¿Es eso así? No recuerdo ser parte del equipo, ni a Anthony, ahora que lo mencionas.",
  ui_story_5076_50760702_15_dialog_content = "Deberías regresar, Anthony. Si sigues rondando con nosotros, la gente comenzará a temerte también.",
  ui_story_5076_50760702_16_dialog_content = "Lo siento, General Aquiles, eres un héroe pero...",
  ui_story_5076_50760702_17_dialog_content = "Ya no soy un general, Anthony. No necesitas referirte a mí como uno.",
  ui_story_5076_50760702_18_dialog_content = "Pero...",
  ui_story_5076_50760702_19_dialog_content = "Aquí no hay generales ni comandantes. Solo los Cazadores Silenciosos.",
  ui_story_5076_50760702_20_dialog_content = "No te andes por las ramas, Anthony. Si quieres comer con nosotros, simplemente dilo.",
  ui_story_5076_50760702_21_dialog_content = "Entiendo...",
  ui_story_5076_50760702_22_dialog_content = "¡Oye Ludweiss, no te comas toda la carne cocida tú solo!",
  ui_story_5076_50760702_23_dialog_content = "¿Cuál es el problema? Simplemente pídele a Friegson que haga un poco más para ti.",
  ui_story_5076_50760702_24_dialog_content = "Ella simplemente lo quemaría todo hasta convertirlo en cenizas, idiota. Además, no quiero nada de lo que ella cocina.",
  ui_story_5076_50760702_25_dialog_content = "¿Tienes algo que decirme?",
  ui_story_5076_50760702_26_dialog_content = "Lo que ella quiere decir es que no quiere comer nada cocinado por tu fuego asesino de Eclipsites.",
  ui_story_5076_50760702_27_dialog_content = "¡Así es!",
  ui_story_5076_50760702_28_dialog_content = "Voy a otro lugar a comer.",
  ui_story_5076_50760702_29_dialog_content = "¡No, espera! Solo estaba bromeando... Ugh, todo esto es tu culpa, Cynthia.",
  ui_story_5076_50760702_30_dialog_content = "Solo estaba ayudándote a decir lo que pensabas.",
  ui_story_5076_50760702_31_dialog_content = "No deberíamos pelear mientras comemos—Aquí, toma un poco más.",
  ui_story_5076_50760702_32_dialog_content = "¡Guau, estoy tan conmovido! Eres la razón principal por la que elegí unirme a los Cazadores Silenciosos.",
  ui_story_5076_50760702_33_dialog_content = "Pensé que dijiste que era para proteger al reino y a su gente...",
  ui_story_5076_50760702_34_dialog_content = "\"La Santa Silenciosa\", eh... No puedo pensar en un nombre menos adecuado para alguien como tú.",
  ui_story_5076_50760702_35_dialog_content = "Ah, ¡estoy lleno! Probablemente debería empezar con la tarea de hoy ahora...",
  ui_story_5076_50760702_36_dialog_content = "¿Qué, todavía estás escribiendo ese diario tuyo?",
  ui_story_5076_50760702_37_dialog_content = "El día que dejé mi casa, decidí registrar todo sobre mis viajes. No voy a renunciar a algo así tan fácilmente.",
  ui_story_5076_50760702_38_dialog_content = "Pero desde que Adras me rescató de los Eclipsites, no he viajado fuera del reino.",
  ui_story_5076_50760702_39_dialog_content = "Todavía había muchos lugares que quería ver, pero me encontré con Eclipsites en el momento en que comencé a viajar de nuevo. Ese es el momento en que me salvaste, Freya—",
  ui_story_5076_50760702_40_dialog_content = "Y después de estar atrapado aquí durante tanto tiempo, mis notas ahora son sobre ti y tus compañeros de escuadrón.",
  ui_story_5076_50760702_41_dialog_content = "¿Te aseguraste de escribir sobre lo heroico que fui hoy?",
  ui_story_5076_50760702_42_dialog_content = "Estaba a punto de hacer eso, ¿podrías darme algo de espacio? Vas a derramar mi tinta por todas partes—",
  ui_story_5076_50760702_43_dialog_content = "Me sorprende que aún puedas estar tan alegre después de ver la carnicería que hay afuera hoy.",
  ui_story_5076_50760702_44_dialog_content = "Bueno, considerando que tú fuiste el que estuvo detrás de la mayoría de la carnicería...",
  ui_story_5076_50760702_45_dialog_content = "Eso es suficiente, Freya. También tengo parte de culpa en la batalla de hoy.",
  ui_story_5076_50760702_46_dialog_content = "Ella sí plantea un buen punto, Friegson.",
  ui_story_5076_50760702_47_dialog_content = "No deberías tensarte tanto en batalla. Incluso la cuerda de arco más fuerte se romperá bajo suficiente presión.",
  ui_story_5076_50760702_48_dialog_content = "Friegson ha estado a mi lado durante mucho tiempo... Antes de que me estacionaran en el norte, ambos servíamos como guardias del palacio.",
  ui_story_5076_50760702_49_dialog_content = "En comparación con el resto de ustedes, que están acostumbrados a ver batallas como esta, ella todavía tiene que adaptarse.",
  ui_story_5076_50760702_50_dialog_content = "Como un noble de nacimiento, estoy seguro de que siempre has visto el campo de batalla como un lugar de honor y gloria, Freya. Pero tienes que entender que para quitar la vida, debes estar dispuesto a entregar la tuya.",
  ui_story_5076_50760702_51_dialog_content = "Lo mismo va para ti, Friegson. Todos somos parte de los Cazadores Silenciosos ahora, así que trátalos como tratabas a tus camaradas en el pasado.",
  ui_story_5076_50760702_52_dialog_content = "Perdóname, Capitán...",
  ui_story_5076_50760702_53_dialog_content = "Corrígeme si me equivoco, capitán, pero ¿no eras parte del Consejo de Ancianos antes? Eso te convertiría en un noble aún mayor que cualquiera de nosotros.",
  ui_story_5076_50760702_54_dialog_content = "El General Aquiles creció con el Rey en aquellos días.",
  ui_story_5076_50760702_55_dialog_content = "Eso explicaría cómo alguien tan joven se convirtió en capitán de los guardias del palacio...",
  ui_story_5076_50760702_56_dialog_content = "Pero al final, elegiste convertirte en un \"súper soldado\", igual que nosotros.",
  ui_story_5076_50760702_57_dialog_content = "Preferiría enfrentar al enemigo en la batalla que participar en sus juegos políticos.",
  ui_story_5076_50760702_58_dialog_content = "Pero, incluso si no es tu intención, el Rey está actualmente centrado en suprimir al Consejo de Ancianos. Dudo que confíe en ti como solía hacerlo.",
  ui_story_5076_50760702_59_dialog_content = "De lo contrario, él no te dejaría convertirte...",
  ui_story_5076_50760702_60_dialog_content = "¡Ya basta de eso! Tú también eras un guardia del palacio, ¿verdad Cynthia? Casi nunca te escucho hablar de ti mismo, y el Capitán Aquiles tampoco nos dice nada.",
  ui_story_5076_50760702_61_dialog_content = "Escuché que te acercaste al capitán y te ofreciste voluntario para el proyecto, mientras que él eligió al resto de nosotros.",
  ui_story_5076_50760702_62_dialog_content = "Yo... Yo crecí en el bosque, así que no hay mucho que decir.",
  ui_story_5076_50760702_63_dialog_content = "Si se necesita mi arco en el frente, entonces ahí es donde iré.",
  ui_story_5076_50760702_64_dialog_content = "Si me necesitan para el proyecto, entonces les permitiré que me mejoren como ellos consideren conveniente.",
  ui_story_5076_50760702_65_dialog_content = "\"¿Aumentar\"?",
  ui_story_5076_50760702_66_dialog_content = "¡Ah! N-No es nada, Adras... Oye, ¿no vas a comer?",
  ui_story_5076_50760702_67_dialog_content = "Estaba a punto de...",
  ui_story_5076_50760702_68_dialog_content = "¿Todo es por eso, huh? Ni personas ni monstruos, y nos vimos obligados a comer en un rincón todos solos.",
  ui_story_5076_50760702_69_dialog_content = "Tenemos una misión especial. Nuestro deber es luchar contra Eclipsites aún más poderosos.",
  ui_story_5076_50760702_70_dialog_content = "Dar ese primer paso al infierno... Es mejor si podemos mantener a otras personas alejadas de este tipo de cosas.",
  ui_story_5076_50760702_71_dialog_content = "Incluso si tenemos que pagar el precio, es mejor que dejarlos sacrificar sus propias vidas.",
  ui_story_5076_50760702_72_dialog_content = "Pero Vice Capitán... Renunciaste a tu estatus de comandante para unirte a los Cazadores Silenciosos, igual que el capitán renunció a su estatus de general...",
  ui_story_5076_50760702_73_dialog_content = "Después de pagar ese precio y constantemente arriesgar tu vida, solo para que la gente te tema... ¿No crees que eso es injusto?",
  ui_story_5076_50760702_74_dialog_content = "Los Cazadores Silenciosos son monstruos creados para luchar contra los poderosos Eclipsites. Nuestro propósito es asegurar su destrucción; nada más nos importa ya.",
  ui_story_5076_50760702_75_dialog_content = "Solo manteniéndonos neutrales y mostrando moderación podemos continuar nuestra lucha contra la oscuridad.",
  ui_story_5076_50760702_76_dialog_content = "¿Sientes que te han hecho mal, Freya?",
  ui_story_5076_50760702_77_dialog_content = "Tal vez sólo un poco... ¡Pero no importa!",
  ui_story_5076_50760702_78_dialog_content = "Soy el que tomó la decisión de proteger a los demás. No me importa lo que piensen los demás, siempre y cuando pueda mantener mi decisión.",
  ui_story_5076_50760702_79_dialog_content = "Estoy seguro de que eso se aplica a cada uno de nosotros.",
  ui_story_5076_50760702_80_dialog_content = "¿Cómo te sientes acerca de los cambios en tu cuerpo, Vice Capitán? ¿Te molestan las miradas cuando estás peleando?",
  ui_story_5076_50760702_81_dialog_content = "... ¿Se me permite hacer ese tipo de pregunta, Capitán?",
  ui_story_5076_50760702_82_dialog_content = "Ya lo hiciste.",
  ui_story_5076_50760702_83_dialog_content = "Como una vez dijo el Capitán Aquiles, luchar contra esos monstruos nos corromperá con el tiempo. Estaba completamente preparado para aceptar las consecuencias.",
  ui_story_5076_50760702_84_dialog_content = "Mientras nadie más tenga que sufrir así, estoy en paz con esas consecuencias.",
  ui_story_5076_50760702_85_dialog_content = "¿Cómo... Cómo lo haces?",
  ui_story_5076_50760702_86_dialog_content = "¡Eres como una persona completamente diferente fuera del campo de batalla! ¡Por favor, muéstrame cómo lo haces!",
  ui_story_5076_50760702_87_dialog_content = "¡Yo también! ¡Enséñanos cómo reprimir nuestras emociones como tú!",
  ui_story_5076_50760702_88_dialog_content = "Supongo...",
  ui_story_5076_50760702_89_dialog_content = "Todo comienza... Con amor.",
  ui_story_5076_50760702_90_dialog_content = "jaja?",
  ui_story_5076_50760702_91_dialog_content = "Según Ludweiss, mi amor y anhelo por mi esposa están sellados en esta espada.",
  ui_story_5076_50760702_92_dialog_content = "Mientras lo sostenga en mis manos, nuestros corazones siempre estarán conectados, sin importar la distancia.",
  ui_story_5076_50760702_93_dialog_content = "Protegerla, y evitar que este mal llegue a nuestro feliz hogar... Eso es todo lo que me importa.",
  ui_story_5076_50760702_94_dialog_content = "De repente me siento... realmente frío.",
  ui_story_5076_50760702_95_dialog_content = "Siempre que el Vice Capitán habla de su esposa, todos mis músculos empiezan a sentirse doloridos...",
  ui_story_5076_50760702_96_dialog_content = "Todavía la recuerdo...",
  ui_story_5076_50760702_97_dialog_content = "Se quedó atrás para ayudar a reconstruir su ciudad.",
  ui_story_5076_50760702_98_dialog_content = "No es de extrañar que el Vice Capitán se niegue a ver a alguien cuando no está en una misión—",
  ui_story_5076_50760702_99_dialog_content = "... ¿También eres amigo de su esposa, Ludweiss?",
  ui_story_5076_50760702_100_dialog_content = "¡S-Sí! Esto me recuerda que prometí traerle algunos materiales de enseñanza nuevos la próxima vez que regrese.",
  ui_story_5076_50760702_101_dialog_content = "Entonces, ¿por qué sigues acompañándonos?",
  ui_story_5076_50760702_102_dialog_content = "Eh—¡Para hacer más registros, por supuesto!",
  ui_story_5076_50760702_103_dialog_content = "Supongo que no faltan personas extrañas en el campo de batalla estos días.",
  ui_story_5076_50760702_104_dialog_content = "Basta de eso. Toma, prueba una copa de este vino. Adras lo hizo él mismo, era nuestro favorito en nuestros días militares.",
  ui_story_5076_50760702_105_dialog_content = "¡Salud, a todos!",
  ui_story_5076_50760800_1_dialog_content = "¡Saludos, Adras! ¿Adónde te diriges?",
  ui_story_5076_50760800_2_dialog_content = "Mi esposa y yo estamos mostrando a los niños algunos lugares para el nuevo orfanato.",
  ui_story_5076_50760800_3_dialog_content = "¿Tu esposa? No sabía acerca de tu... De todos modos, ¡felicidades por tu nuevo matrimonio!",
  ui_story_5076_50760800_4_dialog_content = "¿Eh? Marcela y yo hemos estado casados ​​durante mucho tiempo, pero gracias de todos modos. Vamos, querida.",
  ui_story_5076_50760800_5_dialog_content = "No... No quiero acercarme al templo...",
  ui_story_5076_50760800_6_dialog_content = "¿Tampoco allí? Entonces elijamos otro lugar.",
  ui_story_5076_50760800_7_dialog_content = "Ohh... Lo siento mucho, Adras! Es... mi descuido. Eres tan imponente; no vi a Lady Marcela a primera vista.",
  ui_story_5076_50760800_8_dialog_content = "... Por favor ten cuidado en tu camino.",
  ui_story_5076_50760800_9_dialog_content = "Gracias.",
  ui_story_5076_50760800_10_dialog_content = "¿Has estado perdiendo peso de nuevo, Marcela? Apenas pueden verte cuando estás detrás de mí; podrían empezar a pensar que eres otra persona.",
  ui_story_5076_50760800_11_dialog_content = "Hmph... ¿Alguna vez pensaste que tú eres el que está ganando peso?",
  ui_story_5076_50760800_12_dialog_content = "La reconstrucción parece estar yendo bien, Adras. Has estado trabajando duro, ¿no?",
  ui_story_5076_50760800_13_dialog_content = "¡Ludweiss! ¡Mucho tiempo sin verte, mi amigo!",
  ui_story_5076_50760800_14_dialog_content = "Me alegra ver que has estado haciendo tan bien últimamente.",
  ui_story_5076_50760800_15_dialog_content = "¿Está, uh... Marcela también está bien?",
  ui_story_5076_50760800_16_dialog_content = "¡Me estás hablando como si ella no estuviera justo frente a ti! ¿Hmm? ¿Dónde estás mirando, Ludweiss? ¿No ves a Marcela parada detrás de mí?",
  ui_story_5076_50760800_17_dialog_content = "... ¿Adras te ha estado escuchando como un buen esposo, Marcela?",
  ui_story_5076_50760800_18_dialog_content = "No lo molestes demasiado, Ludweiss. No es fácil para él alejarse del frente, y apenas acaba de regresar.",
  ui_story_5076_50760800_19_dialog_content = "Eso me recuerda... ¿No ibas a algún lugar con Freya y los demás? Lo siento, tal vez es porque he estado tan ocupado, pero no parece que pueda recordar.",
  ui_story_5076_50760800_20_dialog_content = "¡Es perfectamente comprensible! Después de todo, estás supervisando la reconstrucción de una ciudad entera. Solo vine a entregar una carta de Aquiles.",
  ui_story_5076_50760800_21_dialog_content = "¿Una carta?",
  ui_story_5076_50760800_22_dialog_content = "Adras, Marcela, ¡hola!",
  ui_story_5076_50760800_23_dialog_content = "¡Hola, Adras!",
  ui_story_5076_50760800_24_dialog_content = "Tonto, ¿por qué solo saludas a Adras? ¿No te enseñé—",
  ui_story_5076_50760800_25_dialog_content = "Ahora, ahora, no te metas con tu hermanito.",
  ui_story_5076_50760800_26_dialog_content = "No te importa, ¿verdad, Marcela?",
  ui_story_5076_50760800_27_dialog_content = "Mmm.",
  ui_story_5076_50760800_28_dialog_content = "Lo siento, Adras, y... Mar-Marcela.",
  ui_story_5076_50760800_29_dialog_content = "Adras, ¿de vuelta de las afueras hoy?",
  ui_story_5076_50760800_30_dialog_content = "Adras, estas uvas son de nuestra propia viña. Tómalas; saben genial y son excelentes para hacer vino.",
  ui_story_5076_50760800_31_dialog_content = "Chicos, hagan espacio! Adras, mira esta tela; es perfecta para hacer ropa nueva para Marcela.",
  ui_story_5076_50760800_32_dialog_content = "Realmente no necesitas hacer esto. Si lo haces, Marcela no me dejará escuchar el final.",
  ui_story_5076_50760800_33_dialog_content = "Ah—¿Marcela?",
  ui_story_5076_50760800_34_dialog_content = "¿A dónde fuiste, mi amor?",
  ui_story_5076_50760800_35_dialog_content = "...¡La vi corriendo de vuelta!",
  ui_story_5076_50760800_36_dialog_content = "¡Sí, debe ser tímida, jaja!",
  ui_story_5076_50760800_37_dialog_content = "O quizás ella está enfadada, todo es tu culpa.",
  ui_story_5076_50760800_38_dialog_content = "Vamos; dejemos un poco de espacio privado para nuestro poderoso héroe, ¿de acuerdo?",
  ui_story_5076_50760800_39_dialog_content = "Lo siento Ludweiss, la gente de aquí puede ser un poco excesiva a veces. ¿Qué estabas diciendo acerca de—",
  ui_story_5076_50760800_40_dialog_content = "¿Ludweiss? ¿P-Por qué estás llorando...? ¿Estás bien?",
  ui_story_5076_50760800_41_dialog_content = "Yo... Yo... Estoy bien, es solo que... Eso fue realmente conmovedor justo ahora.",
  ui_story_5076_50760800_42_dialog_content = "Todos te tratan tan bien a ambos... Estoy tan feliz por ustedes.",
  ui_story_5076_50760800_43_dialog_content = "Eso es porque todos son buenas personas.",
  ui_story_5076_50760800_44_dialog_content = "Lo sé... Realmente son buenas personas...",
  ui_story_5076_50760800_45_dialog_content = "Aquí tienes un pañuelo. Tómalo.",
  ui_story_5076_50760800_46_dialog_content = "¿Te sientes mejor ahora?",
  ui_story_5076_50760800_47_dialog_content = "Sí. Gracias, Adras—",
  ui_story_5076_50760800_48_dialog_content = "Mencionaste algo sobre una carta. ¿El capitán tiene nuevas órdenes para mí?",
  ui_story_5076_50760800_49_dialog_content = "... El rey se está preparando para una nueva expedición. Quiere destruir el mal en su origen.",
  ui_story_5076_50760800_50_dialog_content = "Esta vez, él te está enviando a ti y a los Cazadores Silenciosos para lidiar con el abismo que se descubrió por primera vez en el norte.",
  ui_story_5076_50760800_51_dialog_content = "Entonces, el mundo todavía no está en paz.",
  ui_story_5076_50760800_52_dialog_content = "Acepto.",
  ui_story_5076_50760800_53_dialog_content = "¿Se unirán otras fuerzas a los Cazadores Silenciosos en esta campaña?",
  ui_story_5076_50760800_54_dialog_content = "Por lo que sé, también se han asignado dos legiones a ello.",
  ui_story_5076_50760800_55_dialog_content = "¿Quién los estará liderando?",
  ui_story_5076_50760800_56_dialog_content = "Es el Sumo Sacerdote Lucius... Ha sido restituido por el rey. No solo eso, asumirá el mando total de toda la expedición.",
  ui_story_5076_50760800_57_dialog_content = "¿Qué? ¿Esa escoria traidora?!",
  ui_story_5076_50760800_58_dialog_content = "¡Pero movilizó sus propias fuerzas privadas durante la última guerra! ¡Innumerables personas murieron por su culpa!",
  ui_story_5076_50760800_59_dialog_content = "¡Todas esas ciudades donde nadie sobrevivió fueron el resultado de sus crímenes! ¿Quieres decirme que este hombre está de repente a cargo de nuestra operación?!",
  ui_story_5076_50760800_60_dialog_content = "¡Es su culpa que tantas personas inocentes murieran! ¡Marcela también casi pierde la vida por su culpa!",
  ui_story_5076_50760800_61_dialog_content = "¡No! ¡No merece piedad! No le perdonaré por—",
  ui_story_5076_50760800_62_dialog_content = "Por favor, solo cálmate, Adras. Estas son las órdenes del rey.",
  ui_story_5076_50760800_63_dialog_content = "¡Aun así, me niego a trabajar para alguien como Lucius!",
  ui_story_5076_50760800_64_dialog_content = "Maldígalo—",
  ui_story_5076_50760800_65_dialog_content = "No descargues tu frustración en Ludweiss, Adras.",
  ui_story_5076_50760800_66_dialog_content = "¿Marcela? Estás de vuelta...",
  ui_story_5076_50760800_67_dialog_content = "El rey puede estar rodeado de mentirosos y aduladores ahora... Pero ellos no son a quienes has estado protegiendo, ¿verdad?",
  ui_story_5076_50760800_68_dialog_content = "¿O deseas ver nuestra ciudad destruida por segunda vez?",
  ui_story_5076_50760800_69_dialog_content = "Para que el rey trague su orgullo y deje que Lucius se lleve el crédito de esta campaña solo promoverá sus malvados objetivos.",
  ui_story_5076_50760800_70_dialog_content = "Pero por mucho que me duela, no tengo forma de negarme a él.",
  ui_story_5076_50760800_71_dialog_content = "El capitán me necesita, mis aliados me necesitan... Y las personas inocentes de nuestro reino me necesitan...",
  ui_story_5076_50760800_72_dialog_content = "... Acepto mis órdenes, Ludweiss.",
  ui_story_5076_50760800_73_dialog_content = "Una vez que los niños y yo decidamos una nueva ubicación para el orfanato, reuniré mis equipos y partiré de inmediato.",
  ui_story_5076_50760800_74_dialog_content = "Entendido... Gracias, Adras.",
  ui_story_5076_50760800_75_dialog_content = "Gracias... Por seguir luchando por este mundo.",
  ui_story_5076_50760800_76_dialog_content = "¿Y tú? ¿Cuál es tu próximo curso de acción?",
  ui_story_5076_50760800_77_dialog_content = "¿Yo...? Bueno, en cierto modo quiero ver la aurora por mí mismo—",
  ui_story_5076_50760800_78_dialog_content = "La expedición será extremadamente peligrosa. Es mejor si no vienes esta vez.",
  ui_story_5076_50760800_79_dialog_content = "Deberías irte de este lugar, Ludweiss.",
  ui_story_5076_50760800_80_dialog_content = "El mundo es un lugar vasto e increíble. Estoy seguro de que encontrarás un lugar mucho más interesante sobre el cual escribir en tu diario.",
  ui_story_5076_50760800_81_dialog_content = "... Lo siento, pero no puedo irme todavía. Todavía tengo algunos asuntos que resolver aquí.",
  ui_story_5076_50760800_82_dialog_content = "Además, no me importaría quedarme y hacerle compañía a Marcela. ¿Verdad, Marcela?",
  ui_story_5076_50760800_83_dialog_content = "Entonces la dejaré en tus manos, Ludweiss.",
  ui_story_5076_50760800_84_dialog_content = "Solo vuelve tan pronto como puedas. ¡Nunca se sabe cuándo podría cambiar de opinión, ya sabes!",
  ui_story_5076_50760800_85_dialog_content = "Entonces te haré la misma promesa que le hice a ella—",
  ui_story_5076_50760800_86_dialog_content = "Que volveré pase lo que pase.",
  ui_story_5076_50760800_87_dialog_content = "Y si me encuentro con la aurora durante mis viajes—",
  ui_story_5076_50760800_88_dialog_content = "Seguro que te contaré todo sobre su belleza, mi amigo.",
  ui_story_5076_50760800_89_dialog_content = "Suena como un trato... No puedo esperar a escuchar tu historia, oh poderoso héroe.",
  ui_story_5076_50760900_1_dialog_content = "\"El tiempo siempre parece escaparse cuando menos lo notamos... Y antes de que nos demos cuenta—\"",
  ui_story_5076_50760900_2_dialog_content = "¡Profesor Ludweiss, ven aquí rápido!",
  ui_story_5076_50760900_3_dialog_content = "¿Qué pasa con toda la conmoción? Apenas tengo la oportunidad de escribir en mi diario estos días, ya sabes...",
  ui_story_5076_50760900_4_dialog_content = "Mucho tiempo sin verte, Ludweiss.",
  ui_story_5076_50760900_5_dialog_content = "¿Adras? Tú...",
  ui_story_5076_50760900_6_dialog_content = "Je... Bienvenido a casa, Adras.",
  ui_story_5076_50760900_7_dialog_content = "¡Apúrense y cierren la puerta, niños! Si alguien ve que nuestro poderoso héroe ha regresado, todo el pueblo pisoteará este lugar hasta convertirlo en polvo!",
  ui_story_5076_50760900_8_dialog_content = "Los niños me dicen que has estado administrando el orfanato durante algún tiempo. No puedo agradecerte lo suficiente por tu ayuda, mi amigo.",
  ui_story_5076_50760900_9_dialog_content = "Nunca pensé que criar a un montón de niños podría ser tan difícil. ¿Cómo diablos lo hizo Marcela—Tos, tos, tos!",
  ui_story_5076_50760900_10_dialog_content = "Eso me recuerda, ¿dónde está ella? Los niños dijeron que podría encontrarla aquí contigo.",
  ui_story_5076_50760900_11_dialog_content = "¿Eh? ¿Conmigo?",
  ui_story_5076_50760900_12_dialog_content = "¡Ah! Ella me vio escribiendo en mi diario, así que se fue justo ahora.",
  ui_story_5076_50760900_13_dialog_content = "Lo siento mucho, sé que debes estar muriendo por verla...",
  ui_story_5076_50760900_14_dialog_content = "Está bien, Ludweiss. Mientras tenga esta espada en mis manos, ella nunca estará lejos de mi lado.",
  ui_story_5076_50760900_15_dialog_content = "La expedición al norte fue larga, pero no lo suficientemente larga como para separar nuestros corazones.",
  ui_story_5076_50760900_16_dialog_content = "Aun así, se siente un poco inquietante no escuchar su voz después de un viaje tan largo... ¿Sabes cuándo volverá?",
  ui_story_5076_50760900_17_dialog_content = "No estoy seguro, eso me recuerda, hace unos días nos enteramos de tu victorioso regreso. Escuché que el rey os elogió a todos por vuestro éxito.",
  ui_story_5076_50760900_18_dialog_content = "Así es. A todos nos dieron nuevos títulos también.",
  ui_story_5076_50760900_19_dialog_content = "¡Recuerdo haber leído sobre eso también en la carta de Freya!",
  ui_story_5076_50760900_20_dialog_content = "Tu título es \"Regal\" ahora, ¿verdad? Y Freya es \"Requiem\", Friegson es \"Frostfire\", y Cynthia es \"Mythos\".",
  ui_story_5076_50760900_21_dialog_content = "Aunque se olvidó de decirme el título de Aquiles.",
  ui_story_5076_50760900_22_dialog_content = "\"Claymore.\" Ese es el nuevo título del Capitán Aquiles.",
  ui_story_5076_50760900_23_dialog_content = "Suena imponente... Freya dijo que también le dieron una corona de laureles. ¿Dónde está la tuya?",
  ui_story_5076_50760900_24_dialog_content = "Lo bajé.",
  ui_story_5076_50760900_25_dialog_content = "¿Eh? ¿Por qué?",
  ui_story_5076_50760900_26_dialog_content = "La corona de laurel que llevo a la batalla me fue dada hace muchos años, cuando terminé la guerra contra los rebeldes. En aquel entonces, fui recompensado con amor y honor.",
  ui_story_5076_50760900_27_dialog_content = "Por eso... No necesito otro.",
  ui_story_5076_50760900_28_dialog_content = "Ah, qué lástima. Me hubiera encantado ver a todos siendo recompensados por sus esfuerzos.",
  ui_story_5076_50760900_29_dialog_content = "Aunque rechacé otra corona, aún le pedí al rey una recompensa en forma de tierras y dinero.",
  ui_story_5076_50760900_30_dialog_content = "¡Qué práctico de tu parte!",
  ui_story_5076_50760900_31_dialog_content = "Es por la gente de mi pueblo, perdieron tanto debido a la guerra. Sé que nunca será suficiente para reemplazar lo que se perdió, pero...",
  ui_story_5076_50760900_32_dialog_content = "Solo espero que haga su vida un poco más fácil.",
  ui_story_5076_50760900_33_dialog_content = "Adras...",
  ui_story_5076_50760900_34_dialog_content = "Vi la aurora mientras estaba en el norte, Ludweiss.",
  ui_story_5076_50760900_35_dialog_content = "Para ser honesto, vi la aurora muchas veces durante mi tiempo en el norte, pero nunca la vi como algo especial. No sé por qué, pero se sintió diferente durante esta última expedición por alguna razón.",
  ui_story_5076_50760900_36_dialog_content = "Cuando vi la aurora rasgar la oscuridad e iluminar el cielo, todo en lo que podía pensar era desear que Marcela estuviera allí para verlo.",
  ui_story_5076_50760900_37_dialog_content = "Si no hubiera tanto peligro oculto en el mundo, tal vez todos podrían ver algo tan hermoso como eso.",
  ui_story_5076_50760900_38_dialog_content = "Por esa razón, no quiero contarte más sobre eso... Quiero que lo veas por ti mismo algún día, Ludweiss.",
  ui_story_5076_50760900_39_dialog_content = "Siento que has cambiado, Adras... Pero... No importa. Como estás de tan buen humor, eso debe significar que la campaña salió realmente bien, ¿verdad?",
  ui_story_5076_50760900_40_dialog_content = "Así es. Logramos destruir el abismo, pero a un costo. Afortunadamente, no parece que se hayan perdido soldados normales.",
  ui_story_5076_50760900_41_dialog_content = "Incluso vimos una espectacular lluvia de meteoritos antes de irnos.",
  ui_story_5076_50760900_42_dialog_content = "Freya se conmovió hasta las lágrimas. Parece que a Cynthia y a los demás también les gustó.",
  ui_story_5076_50760900_43_dialog_content = "Poco después, el capitán hizo estas Crestas de Estrella para nosotros.",
  ui_story_5076_50760900_44_dialog_content = "¡Estos están tan bien hechos! No tenía idea de que Aquiles tenía talento para este tipo de cosas.",
  ui_story_5076_50760900_45_dialog_content = "No importa a dónde vayamos, siempre seremos los Cazadores Silenciosos que contemplaron las estrellas ese día.",
  ui_story_5076_50760900_46_dialog_content = "Un recuerdo como este es mucho más precioso que cualquier corona de laurel.",
  ui_story_5076_50760900_47_dialog_content = "Casi suena como si estuvieras diciendo adiós...",
  ui_story_5076_50760900_48_dialog_content = "Eso es porque lo estoy. He decidido retirarme del servicio y pasar el resto de mis días aquí, en paz y con Marcela a mi lado.",
  ui_story_5076_50760900_49_dialog_content = "Freya no mencionó nada sobre eso en su carta. ¿Qué pasará con los Cazadores Silenciosos?",
  ui_story_5076_50760900_50_dialog_content = "Nosotros... Aún no nos hemos disuelto. Pero como subordinados directos de la corona, eventualmente estaremos sujetos al control de Lucius.",
  ui_story_5076_50760900_51_dialog_content = "Me niego a obedecerle. Lo mismo ocurre con el resto de los Silent Hunters.",
  ui_story_5076_50760900_52_dialog_content = "Además, con la amenaza de los Eclipsites desaparecida, el reino ya no nos necesita. Esa podría haber sido la razón por la que ninguno de ellos intentó detenerme cuando me fui.",
  ui_story_5076_50760900_53_dialog_content = "No podría estar más de acuerdo. Debes estar cansado después de tantos años de lucha, Adras; si alguien merece descansar, eres tú.",
  ui_story_5076_50760900_54_dialog_content = "Jeje, todavía no puedo relajarme. Todavía necesito encontrar a Marcela y sorprenderla.",
  ui_story_5076_50760900_55_dialog_content = "Se está haciendo tarde. Estoy seguro de que ella volverá pronto, así que no te vayas corriendo por tu cuenta.",
  ui_story_5076_50760900_56_dialog_content = "¿Estaba hablando en serio? No vio a Marcela aquí, entonces, ¿dónde más podría estar? Mmm...",
  ui_story_5076_50760900_57_dialog_content = "¿Podría ser que su corazón finalmente está comenzando a sanar? Eso es algo bueno... ¿Verdad?",
  ui_story_5076_50760900_58_dialog_content = "<color=#e8d9bb>El héroe regresa después del triunfo, y la ciudad lo celebra con una gran ceremonia.</color>",
  ui_story_5076_50760900_59_dialog_content = "<color=#e8d9bb>El <color=#FFB400>Templo</color>, el lugar de amor para el héroe, está especialmente renovado y solemnemente presentado a él.</color>",
  ui_story_5076_50760900_60_dialog_content = "<color=#e8d9bb>Nadie anticipó que pronto presenciaría un tiempo de gran agitación.</color>",
  ui_story_5076_50760900_61_dialog_content = "¿Cómo pasó esto? El Templo en el que pusimos mucho esfuerzo en renovar...",
  ui_story_5076_50760900_62_dialog_content = "¿Qué demonios pasó aquí?",
  ui_story_5076_50760900_63_dialog_content = "¿Adras? Tú...",
  ui_story_5076_50760900_64_dialog_content = "¿Por qué el templo está en ruinas?",
  ui_story_5076_50760900_65_dialog_content = "Quizás... ¿son los Eclipsites?",
  ui_story_5076_50760900_66_dialog_content = "¡Malditos Eclipsites, cómo se atreven a poner un pie en este lugar, especialmente cuando significa tanto para Marcela y para mí!",
  ui_story_5076_50760900_67_dialog_content = "Por favor, no te enfades. Al menos nadie está herido ahora mismo. Tómalo con calma.",
  ui_story_5076_50760900_68_dialog_content = "... Me alivia escuchar que nadie resultó herido. Deja las reparaciones del templo en mis manos.",
  ui_story_5076_50760900_69_dialog_content = "También ayudaremos.",
  ui_story_5076_50760900_70_dialog_content = "Muy bien, pero mantente alerta. Puede que todavía haya Eclipsites acechando en la zona.",
  ui_story_5076_50760900_71_dialog_content = "¡Tú también tienes que tener cuidado!",
  ui_story_5076_50760900_72_dialog_content = "Traeré mi espada y vigilaré este lugar cuando caiga la noche. No podemos permitir que otra tragedia ocurra en este lugar, y no dejaré que los Eclipsites se salgan con la suya de nuevo...",
  ui_story_5076_50760900_73_dialog_content = "<color=#e8d9bb>Gracias al esfuerzo conjunto del héroe y sus ayudantes trabajadores, el Templo fue reparado rápidamente. Sin embargo—</color>",
  ui_story_5076_50760900_74_dialog_content = "¿Qué es esto?",
  ui_story_5076_50760900_75_dialog_content = "Nunca salí de la ciudad ni una sola vez... ¿Qué tipo de Eclipsite es capaz de evitar mi detección de esta manera?",
  ui_story_5076_50760900_76_dialog_content = "Sigue infiltrándose en la ciudad justo bajo mi nariz... Los habitantes de la ciudad están en peligro...",
  ui_story_5076_50760900_77_dialog_content = "No me preocuparía demasiado. Tal vez el Eclipsite es simplemente demasiado débil para llamar tu atención. Aquí, intentaré sentirlo.",
  ui_story_5076_50760900_78_dialog_content = "¿Eh? Hay algo extraño en estos restos...",
  ui_story_5076_50760900_79_dialog_content = "¿Oye Adras? Dijiste que Marcela tenía demasiado miedo del templo como para siquiera acercarse, ¿no es así?",
  ui_story_5076_50760900_80_dialog_content = "Sí, parece ser el caso. Siempre que vengo al templo, ella se niega a acompañarme.",
  ui_story_5076_50760900_81_dialog_content = "Así que esa es la razón...",
  ui_story_5076_50760900_82_dialog_content = "¡Profesor Ludweiss, mira!",
  ui_story_5076_50760900_83_dialog_content = "Esto parece una marca dejada por una espada...",
  ui_story_5076_50760900_84_dialog_content = "¡Shh—!!!",
  ui_story_5076_50760900_85_dialog_content = "¿Qué es?",
  ui_story_5076_50760900_86_dialog_content = "¡N-No es nada! Este niño solo quiere ayudarte a reconstruir el templo, pero todavía es demasiado joven.",
  ui_story_5076_50760900_87_dialog_content = "Gracias por la oferta, pequeño, pero necesitas regresar. Este lugar no es seguro.",
  ui_story_5076_50760900_88_dialog_content = "¡Vamos, apresúrate a casa!",
  ui_story_5076_50760900_89_dialog_content = "Entonces, ¿lograste percibir algo, Ludweiss?",
  ui_story_5076_50760900_90_dialog_content = "Lo hice... Pero es algo muy pequeño, como un travieso y pequeño Eclipsite. No creo que represente una gran amenaza.",
  ui_story_5076_50760900_91_dialog_content = "Aun así, no podemos permitirnos correr ningún riesgo. Parece que necesitaré tu ayuda para defender el templo, Ludweiss.",
  ui_story_5076_50760900_92_dialog_content = "¿Yo? Entonces... Comenzaré tomando el turno de esta noche. No te preocupes, la milicia estará en espera si algo sucede. Por ahora... Solo vete a casa y descansa antes de que Marcela comience a preocuparse...",
  ui_story_5076_50760900_93_dialog_content = "Ugh, qué noche... El suelo del templo no es el lugar más suave para dormir.",
  ui_story_5076_50760900_94_dialog_content = "Profesor Ludweiss, el Hermano Adras dijo que pasaría esta noche para vigilar. Ah, por cierto, se ve bastante alegre.",
  ui_story_5076_50760900_95_dialog_content = "Suena como si hubiera descansado bastante, lo que significa que el templo no debería haber estado...",
  ui_story_5076_50760900_96_dialog_content = "¿Por qué... Por qué está tan estable de repente? ¿Podría ser que... Vio a Marcela de nuevo?",
  ui_story_5076_50760900_97_dialog_content = "Ludweiss, debes estar cansado después de estar de guardia toda la noche. Puedes retirarte ahora.",
  ui_story_5076_50760900_98_dialog_content = "Si me voy y Adras se acerca de nuevo al templo...",
  ui_story_5076_50760900_99_dialog_content = "No te preocupes, Ludweiss. Tenemos fe en Adras.",
  ui_story_5076_50760900_100_dialog_content = "No podemos tenerlo aquí todo el tiempo. Está bien; le debemos demasiado a Adras, así que todos trabajaremos juntos contigo...",
  ui_story_5076_50760900_101_dialog_content = "... Tengo una idea. Si el templo termina en ruinas nuevamente mañana, necesito que todos sigan el juego con esto—",
  ui_story_5076_50760900_102_dialog_content = "Como se esperaba, el templo fue dañado de nuevo.",
  ui_story_5076_50760900_103_dialog_content = "¿Qué demonios...",
  ui_story_5076_50760900_104_dialog_content = "... ¿Has estado durmiendo bien en casa, Adras?",
  ui_story_5076_50760900_105_dialog_content = "Por supuesto. Después de todo, Marcela está conmigo de nuevo... Pero, ¿por qué preguntas?",
  ui_story_5076_50760900_106_dialog_content = "Suspiro... Parece que estamos de vuelta en el punto de partida otra vez...",
  ui_story_5076_50760900_107_dialog_content = "Aún así, me alegra ver que tu mente está en paz de nuevo.",
  ui_story_5076_50760900_108_dialog_content = "¿De qué estás hablando?",
  ui_story_5076_50760900_109_dialog_content = "Como Caelestite, simplemente... Me siento un poco impotente. Después de todo, esta es la primera vez que he deseado que una <color=#FFB400>enfermedad</color> permanezca sin curar...",
  ui_story_5076_50760900_110_dialog_content = "Adras, ¡atrapamos a ese Eclipsite!",
  ui_story_5076_50760900_111_dialog_content = "¿En serio? ¿Cómo lo hiciste?",
  ui_story_5076_50760900_112_dialog_content = "Era un pequeño Eclipsite, ágil y rápido, solo causaba problemas en las primeras horas. ¡Pero no te preocupes, cayó en nuestra trampa y fue atrapado!",
  ui_story_5076_50760900_113_dialog_content = "Ya hemos eliminado ese Eclipsite. Ahora puedes descansar tranquilo.",
  ui_story_5076_50760900_114_dialog_content = "Sí, hermano Adras, vi con mis propios ojos cómo aplastaban a ese pequeño Eclipsite.",
  ui_story_5076_50760900_115_dialog_content = "Ejem—",
  ui_story_5076_50760900_116_dialog_content = "¡Oh! Por cierto, acabamos de pasar por tu lugar y escuchamos que Marcela podría necesitarte para algo. Será mejor que te apresures a volver.",
  ui_story_5076_50760900_117_dialog_content = "Entendido. Regresaré para ayudar con las reparaciones mañana.",
  ui_story_5076_50760900_118_dialog_content = "No, solo déjanoslo a nosotros! Has hecho tanto por nosotros y no queremos molestarte más. Regresa y pasa más tiempo con Marcela.",
  ui_story_5076_50760900_119_dialog_content = "Sería demasiado vergonzoso si no podemos hacer bien una cosa tan pequeña.",
  ui_story_5076_50760900_120_dialog_content = "Solo haz lo que ellos digan, Adras. Después de unos días—",
  ui_story_5076_50760900_121_dialog_content = "¡Profesor Ludweiss! ¡Ejem!",
  ui_story_5076_50760900_122_dialog_content = "—¡Solo continúa manteniendo tu distancia! Todo está bien ahora, así que solo vigila las cosas desde lejos, ¿de acuerdo?",
  ui_story_5076_50760900_123_dialog_content = "Todos están actuando tan extraño.",
  ui_story_5076_50760900_124_dialog_content = "Pero si Marcela me necesita ahora mismo... Debería irme a casa...",
  ui_story_5076_50760900_125_dialog_content = "Te dejo el resto a ti, Ludweiss.",
  ui_story_5076_50760900_126_dialog_content = "¿Eh? Eh... ¡Claro! Solo... déjalo todo a mí.",
  ui_story_5076_50761000_1_dialog_content = "De hecho, lograron reconstruir esta ciudad.",
  ui_story_5076_50761000_2_dialog_content = "¿Ves? ¡Te dije que Ludweiss no estaba exagerando en su carta!",
  ui_story_5076_50761000_3_dialog_content = "La última vez que nos reunimos aquí, esta ciudad apenas se diferenciaba de una pila de escombros.",
  ui_story_5076_50761000_4_dialog_content = "¿Qué podría haber impulsado a estas personas a hacer que suceda un milagro así?",
  ui_story_5076_50761000_5_dialog_content = "Estoy seguro de que era su fe en su héroe.",
  ui_story_5076_50761000_6_dialog_content = "Nos están mirando de nuevo... Oculta mi rostro, Freya.",
  ui_story_5076_50761000_7_dialog_content = "¡Ey! ¡Aqui!",
  ui_story_5076_50761000_8_dialog_content = "Señorita Ludweiss, ¿quiénes son? ¿Podría presentarlos, por favor?",
  ui_story_5076_50761000_9_dialog_content = "Estos son los amigos de Adras, ¡los legendarios Guerreros Estrella del reino! Han venido a visitarlo.",
  ui_story_5076_50761000_10_dialog_content = "¡Vaya, es un honor tenerlos aquí! Adras y Marcela estarán seguramente llenos de alegría.",
  ui_story_5076_50761000_11_dialog_content = "¿Marcela? Pero Capitana, ¿no dijiste que ella... Ya veo. Todos ustedes han estado cuidando a la Vice Capitana, ¿verdad?",
  ui_story_5076_50761000_12_dialog_content = "Gracias.",
  ui_story_5076_50761000_13_dialog_content = "Jeje, estimados invitados, ¿les gustaría probar nuestras especialidades locales?",
  ui_story_5076_50761000_14_dialog_content = "¿Podrías llevarle algo a Adras también? Él... bueno, él y Marcela también podrían necesitar algo de cuidado.",
  ui_story_5076_50761000_15_dialog_content = "A todos...",
  ui_story_5076_50761000_16_dialog_content = "Jeje, por favor saluda a él y a \"Marcela\" de nuestra parte.",
  ui_story_5076_50761000_17_dialog_content = "Es bueno verlos a todos de nuevo. Quería darles la bienvenida personalmente, pero Marcela se ofreció a hacerlo en mi lugar.",
  ui_story_5076_50761000_18_dialog_content = "Después de todo, ella y Ludweiss ya están en la ciudad. Ambos trabajan ahora en el orfanato.",
  ui_story_5076_50761000_19_dialog_content = "No te preocupes por eso. Marcela nos mostró los campos justo ahora. ¡Son enormes! Debes estar muy ocupado preparándote para la cosecha, ¿verdad?",
  ui_story_5076_50761000_20_dialog_content = "Sí, pero también es muy pacífico ... No podría pedir una vida mejor.",
  ui_story_5076_50761000_21_dialog_content = "Está bien escuchar eso... Adras.",
  ui_story_5076_50761000_22_dialog_content = "¿Cómo han estado todos?",
  ui_story_5076_50761000_23_dialog_content = "Bien, supongo. Volví a servir como guardia del palacio, para poder seguir defendiendo el reino.",
  ui_story_5076_50761000_24_dialog_content = "Ya que ya no somos necesarios, he estado vagando por el reino... Las miradas frías nunca cesan, pero me ha ido bien.",
  ui_story_5076_50761000_25_dialog_content = "El bosque es mucho más pacífico, Friegson. ¿Por qué no te unes a mí en su lugar?",
  ui_story_5076_50761000_26_dialog_content = "... No quiero que mis llamas destruyan tu paraíso.",
  ui_story_5076_50761000_27_dialog_content = "Siempre podrías quedarte aquí, Friegson. Las personas en esta ciudad son amables y no te rechazarán por tus cicatrices.",
  ui_story_5076_50761000_28_dialog_content = "Gracias por la oferta, Vice Capitán. Puedo decir que son buenas personas, pero... Es mejor si no me quedo.",
  ui_story_5076_50761000_29_dialog_content = "Una reunión como esta es difícil de encontrar, así que ¿por qué no quedarse un poco más y contarle a Adras sobre sus vidas? Incluso podemos construir una fogata, como antes.",
  ui_story_5076_50761000_30_dialog_content = "Marcela tiene razón. Deberíamos hacer una hoguera esta noche, como en los viejos tiempos. Me encantaría sentarme y hablar un poco más con todos también.",
  ui_story_5076_50761000_31_dialog_content = "... No veo por qué no.",
  ui_story_5076_50761000_32_dialog_content = "¡Por mí está bien! Ha pasado mucho tiempo desde que probé la cocina casera del Vice Capitán. ¡Apuesto a que también hay muchas bodegas de vino por aquí—",
  ui_story_5076_50761000_33_dialog_content = "¡Vamos Friegson, vamos a agarrar un barril de lo bueno!",
  ui_story_5076_50761000_34_dialog_content = "¿Estaría bien eso, Vice Capitán?",
  ui_story_5076_50761000_35_dialog_content = "Por supuesto. Marcela puede mostrarte dónde está.",
  ui_story_5076_50761000_36_dialog_content = "Pero...",
  ui_story_5076_50761000_37_dialog_content = "La bodega de vinos es bastante fácil de encontrar. La entrada está en el cobertizo detrás de la casa.",
  ui_story_5076_50761000_38_dialog_content = "¡Vamos a agarrar unos cuantos barriles más y hacer de esto una verdadera fiesta! ¡Ahora deja de holgazanear y échanos una mano, Cynthia!",
  ui_story_5076_50761000_39_dialog_content = "Pero tengo que observar la etiqueta adecuada mientras...",
  ui_story_5076_50761000_40_dialog_content = "¡Oh, simplemente supéralo y ayúdanos!",
  ui_story_5076_50761000_41_dialog_content = "¿Has estado bien últimamente, Capitán?",
  ui_story_5076_50761000_42_dialog_content = "La autoridad de Lucius va más allá de su estatus como Sumo Sacerdote. Es lo suficientemente poderoso como para enfrentarse al Consejo de Ancianos ahora... Y mi familia desea que me ponga de su lado.",
  ui_story_5076_50761000_43_dialog_content = "Pero los Cazadores Silenciosos no son asesinos. Ahora que el reino está a salvo de los Eclipsites, no tenemos razón para involucrarnos en estos asuntos.",
  ui_story_5076_50761000_44_dialog_content = "Solo quiero pasar tiempo con todos, Adras. Justo así.",
  ui_story_5076_50761000_45_dialog_content = "... Lo entiendo. Espero que encuentres algo de paz aquí, aunque solo sea por un corto tiempo.",
  ui_story_5076_50761000_46_dialog_content = "Vamos a preparar la cena de esta noche, Marcela.",
  ui_story_5076_50761000_47_dialog_content = "¿Crees que él está feliz, Ludweiss?",
  ui_story_5076_50761000_48_dialog_content = "Por lo que puedo decir, definitivamente está feliz ahora...",
  ui_story_5076_50761000_49_dialog_content = "Hemos estado continuando con esta mentira, pero si—",
  ui_story_5076_50761000_50_dialog_content = "Marcela una vez dijo que Adras está dispuesto a luchar por su gente por el resto de su vida.",
  ui_story_5076_50761000_51_dialog_content = "Y las personas aquí están haciendo todo lo posible para proteger el último pedazo de paz y felicidad de su héroe.",
  ui_story_5076_50761000_52_dialog_content = "No es solo una mentira, Capitán Aquiles. Al menos no de la forma en que yo lo veo.",
  ui_story_5076_50761000_53_dialog_content = "Aquellos que se esconden de su dolor eventualmente despertarán incluso del sueño más cuidadosamente elaborado. Cuando eso suceda... ¿Sufrirá aún más? ¿O estará feliz con esa fugaz sensación de felicidad?",
  ui_story_5076_50761000_54_dialog_content = "Él está mejorando.",
  ui_story_5076_50761000_55_dialog_content = "No siento que la corrupción se esté extendiendo en él anymore. Si acaso, se ha vuelto aún más enérgico.",
  ui_story_5076_50761000_56_dialog_content = "Así que si algún día despierta de su sueño... Estaré allí para soportar cualquier resentimiento que pueda tener.",
  ui_story_5076_50761000_57_dialog_content = "Soy su capitán, Ludweiss. Si ese día llega, seré yo quien asuma la responsabilidad de todo.",
  ui_story_5076_50761000_58_dialog_content = "Esto me recuerda; escuché que el orfanato ahora es completamente capaz de funcionar por sí mismo. ¿Planeas volver a tus viajes pronto?",
  ui_story_5076_50761000_59_dialog_content = "¡Bueno, siempre he querido ver las estrellas fugaces en el norte!",
  ui_story_5076_50761000_60_dialog_content = "¿Estrellas fugaces? ¿No es la aurora?",
  ui_story_5076_50761000_61_dialog_content = "De nuevo, eres libre de hacer lo que desees. Al menos, puedes escapar de tus ataduras... Y ver el mundo en nuestro lugar.",
  ui_story_5076_50761000_62_dialog_content = "Lo haré, y serás el primero en leer sobre todo lo que vea allí.",
  ui_story_5076_50761000_63_dialog_content = "¡Trago, trago, trago! ¡Vamos, tú puedes hacerlo!",
  ui_story_5076_50761000_64_dialog_content = "Glug, glug, glug—",
  ui_story_5076_50761000_65_dialog_content = "Me rindo... No puedo beber más.",
  ui_story_5076_50761000_66_dialog_content = "¡Levántate, Friegson! ¿Cómo pudiste perder ante Cynthia otra vez?!",
  ui_story_5076_50761000_67_dialog_content = "Un capitán... Dos capitanes...",
  ui_story_5076_50761000_68_dialog_content = "Oh, ella está realmente borracha ahora.",
  ui_story_5076_50761000_69_dialog_content = "¿Eres el siguiente, Freya?",
  ui_story_5076_50761000_70_dialog_content = "¡E-Ejem, quiero que sepas que soy una noble muy culta! ¿Cómo podría yo posiblemente entregarme a este tipo de comportamiento?",
  ui_story_5076_50761000_71_dialog_content = "... Cobarde.",
  ui_story_5076_50761000_72_dialog_content = "¿Te importaría ayudar a Friegson a su habitación, Marcela?",
  ui_story_5076_50761000_73_dialog_content = "... Me alegro por ti, Vice Capitán.",
  ui_story_5076_50761000_74_dialog_content = "Estás haciendo mucho mejor que cualquiera de nosotros... Nadie te trata como a un monstruo, ni te hace hacer su trabajo sucio.",
  ui_story_5076_50761000_75_dialog_content = "Estás borracho, Friegson. Deberías acostarte.",
  ui_story_5076_50761000_76_dialog_content = "¿Por qué todos en el reino me miran de esa manera? ¡No es como si quisiera terminar así!",
  ui_story_5076_50761000_77_dialog_content = "¡No hice nada malo! Solo quería protegerlos...",
  ui_story_5076_50761000_78_dialog_content = "Llévala de vuelta a la cama, Freya.",
  ui_story_5076_50761000_79_dialog_content = "Pero Capitán... Ella está llorando.",
  ui_story_5076_50761000_80_dialog_content = "Está exhausta. Creo que necesita desahogarse.",
  ui_story_5076_50761000_81_dialog_content = "¡No hice nada! Soy un cazador de monstruos, no un monstruo!",
  ui_story_5076_50761000_82_dialog_content = "¡Solo quería ayudar a ese anciano a encontrar su camino! ¿Por qué me maldijo tan pronto como me vio?!",
  ui_story_5076_50761000_83_dialog_content = "Estaba claramente asustado de mí, ¡pero eso no lo detuvo! ¿Por qué? ¿Es porque sabía que no le haría daño? ¿Quién es el que está siendo irrazonable aquí—",
  ui_story_5076_50761000_84_dialog_content = "...",
  ui_story_5076_50761000_85_dialog_content = "No llores, Friegson. Realmente no te queda nada bien.",
  ui_story_5076_50761000_86_dialog_content = "Vice ¿Capitán? Yo... Realmente estoy feliz por ti. Al menos tú puedes ser un héroe. Pero, ¿por qué el reino nos ve al resto de nosotros como monstruos...?",
  ui_story_5076_50761000_87_dialog_content = "¿Por qué, Vice Capitán...? ¿Qué deberíamos hacer...?",
  ui_story_5076_50761000_88_dialog_content = "El amor en mi corazón casi se ha ido ahora... ¿Qué debería hacer...?",
  ui_story_5076_50761000_89_dialog_content = "La gente aquí todavía puede verte como el héroe que siempre has sido... Entonces, ¿por qué todos los demás son tan estúpidos?",
  ui_story_5076_50761000_90_dialog_content = "Friegson...",
  ui_story_5076_50761000_91_dialog_content = "No te preocupes demasiado por ella, Adras. Ha guardado estos sentimientos para sí misma durante demasiado tiempo, y finalmente encontró a alguien con quien compartirlos.",
  ui_story_5076_50761000_92_dialog_content = "... ¡Bebamos, Vice Capitán! Vamos... a emborracharnos juntos...!",
  ui_story_5076_50761000_93_dialog_content = "Salud, Friegson. Esta copa es para ti.",
  ui_story_5076_50761000_94_dialog_content = "¡Vamos, Cynthia! ¡Parece que el Capitán Vice necesita un buen desafío!",
  ui_story_5076_50761000_95_dialog_content = "Deberías saber que tengo mucha confianza en mí mismo.",
  ui_story_5076_50761000_96_dialog_content = "Bueno, no lo estoy, así que parece que estoy destinado a perder.",
  ui_story_5076_50761000_97_dialog_content = "Glug, glug, glug—",
  ui_story_5076_50761000_98_dialog_content = "¡Que sigan viniendo! ¡Te mostraré el valor de la Legión Northwind!",
  ui_story_5076_50761000_99_dialog_content = "Marcela... ¿Dónde estás...? No puedo alcanzarte.",
  ui_story_5076_50761000_100_dialog_content = "¿Una canción? Pero no estamos trabajando... Ah, supongo que una canción no haría daño.",
  ui_story_5076_50761000_101_dialog_content = "\"¡Toma mi mano—\"",
  ui_story_5076_50761000_102_dialog_content = "El Vice Capitán debe estar realmente borracho... No creo que haya escuchado nunca una canción tan única antes...",
  ui_story_5076_50761000_103_dialog_content = "No te preocupes, su canto no es mucho mejor cuando está sobrio.",
  ui_story_5076_50761000_104_dialog_content = "\"Llévame a casa—\"",
  ui_story_5076_50761000_105_dialog_content = "¿Esa era la canción de la Legión Northwind? Es tan... llena de emoción.",
  ui_story_5076_50761000_106_dialog_content = "Gracias...",
  ui_story_5076_50761000_107_dialog_content = "Me pregunto si alguna vez tendremos un hogar?",
  ui_story_5076_50761000_108_dialog_content = "Así se hace, Vice Capitán. Nuestros problemas no pueden molestarnos si estamos demasiado borrachos para recordarlos, ¿verdad?",
  ui_story_5076_50761000_109_dialog_content = "Es genial...",
  ui_story_5076_50761000_110_dialog_content = "No creo que haya visto a Adras tan feliz antes.",
  ui_story_5076_50761000_111_dialog_content = "¿Está realmente bien, Capitán?",
  ui_story_5076_50761000_112_dialog_content = "Parece que Friegson está casi en su límite, y a pesar del aparente optimismo de Freya, estoy seguro de que ella también...",
  ui_story_5076_50761000_113_dialog_content = "Este mundo ya no nos necesita. Si acaso, nuestra existencia es demasiado amenazante para la paz.",
  ui_story_5076_50761000_114_dialog_content = "Te lo dije antes, ¿no? No somos más que armas a disposición del reino. Tarde o temprano, nos van a usar de nuevo.",
  ui_story_5076_50761000_115_dialog_content = "Incluso ahora, siento como si mi conciencia estuviera siendo devorada.",
  ui_story_5076_50761000_116_dialog_content = "¿Cuánto tiempo más antes de que uno de nosotros cometa un error?",
  ui_story_5076_50761000_117_dialog_content = "Eso es suficiente, Cynthia. No hay nada más valioso para nosotros que la racionalidad, pero eso no nos hace desalmados.",
  ui_story_5076_50761000_118_dialog_content = "Pero si no nos ocupamos pronto, uno de estos días, nosotros—",
  ui_story_5076_50761000_119_dialog_content = "¡Estas no son las cosas en las que deberías estar pensando! ¡No somos como monstruos en un cuento de hadas!",
  ui_story_5076_50761000_120_dialog_content = "¡Dejen de pelear, ustedes dos! Es raro que todos nosotros pasemos tiempo juntos así...",
  ui_story_5076_50761000_121_dialog_content = "Me niego a lastimar a mis amigos de cualquier manera.",
  ui_story_5076_50761000_122_dialog_content = "Es fácil decir eso cuando todavía tenemos una opción... ¿Pero qué pasa cuando no la tenemos?",
  ui_story_5076_50761000_123_dialog_content = "¿Estás seguro de que no te arrepentirás?",
  ui_story_5076_50761000_124_dialog_content = "Mientras siga siendo Aquiles, juro por mi nombre que nunca levantaré mi espada contra mis camaradas.",
  ui_story_5076_50761000_125_dialog_content = "Solo me uní al ejército para evitar que las llamas de la guerra alcanzaran el bosque...",
  ui_story_5076_50761000_126_dialog_content = "En el momento en que puse un pie fuera de mi casa, me di cuenta de que este mundo es simplemente un bosque aún más grande.",
  ui_story_5076_50761000_127_dialog_content = "Desearía poder disculparme contigo con toda mi alma...",
  ui_story_5076_50761000_128_dialog_content = "Pero desafortunadamente, no estoy seguro si este cuerpo todavía tiene un alma o no.",
  ui_story_5076_50761000_129_dialog_content = "De cualquier manera, lo siento.",
  ui_story_5076_50761101_1_dialog_content = "Regal, hay una nueva orden para ti.",
  ui_story_5076_50761101_2_dialog_content = "Frostfire, tu compañero Cazador Silencioso, ha enloquecido en otra ciudad.",
  ui_story_5076_50761101_3_dialog_content = "¡¿Qué?!",
  ui_story_5076_50761101_4_dialog_content = "Usa tu magia de agua para detenerla.",
  ui_story_5076_50761101_5_dialog_content = "Si es necesario... sin piedad, bájala.",
  ui_story_5076_50761101_6_dialog_content = "Friegson... ¿Por qué...",
  ui_story_5076_50761101_7_dialog_content = "Este es-",
  ui_story_5076_50761101_8_dialog_content = "¿La ciudad entera... Ha sido quemada hasta los cimientos?",
  ui_story_5076_50761101_9_dialog_content = "¡Centinelas, informen la situación! ¿Hay sobrevivientes en la ciudad?",
  ui_story_5076_50761101_10_dialog_content = "¡Informe! Sin sobrevivientes en la ciudad, ¡y ella sigue fuera de control!",
  ui_story_5076_50761101_11_dialog_content = "¡Rápido! Despliega el nuevo \"monstruo\" y déjalos luchar, ¡o sino otros lugares podrían estar en peligro!",
  ui_story_5076_50761101_12_dialog_content = "Friegson... Friegson...",
  ui_story_5076_50761101_13_dialog_content = "Vice Capitán...? Por favor... Ayúdame...",
  ui_story_5076_50761101_14_dialog_content = "No... Tú eres—¡Un Eclipsite!",
  ui_story_5076_50761101_15_dialog_content = "<size=45>¡¡¡Un Eclipsito!!!</size>",
  ui_story_5076_50761101_16_dialog_content = "<size=45>¡¡¡Muere!!!</size>",
  ui_story_5076_50761102_1_dialog_content = "Aaaaaaah—¡Muere, Eclipsite!!!",
  ui_story_5076_50761102_2_dialog_content = "¡Alto, los dos!",
  ui_story_5076_50761102_3_dialog_content = "No puedo—Tengo que quemarlo todo—",
  ui_story_5076_50761102_4_dialog_content = "¡Despierten, ustedes dos! Ludweiss, usa tus poderes para hacerles entrar en razón!",
  ui_story_5076_50761102_5_dialog_content = "Por favor despierta—",
  ui_story_5076_50761102_6_dialog_content = "C... ¿Capitán?",
  ui_story_5076_50761102_7_dialog_content = "¿Ludweiss?",
  ui_story_5076_50761102_8_dialog_content = "Finalmente han vuelto a ser ustedes mismos... ¿¡Por qué estaban peleando de esta manera?!",
  ui_story_5076_50761102_9_dialog_content = "Capitán, yo...",
  ui_story_5076_50761102_10_dialog_content = "¿Grilletes? ¿Por qué están en mí...?",
  ui_story_5076_50761102_11_dialog_content = "Mira a tu alrededor, Friegson. Estas cadenas son para protegerte.",
  ui_story_5076_50761102_12_dialog_content = "Monstruos... ¿Por qué seguir manteniendo a estos seres peligrosos alrededor...",
  ui_story_5076_50761102_13_dialog_content = "Juraste proteger este lugar, pero lo quemaste junto con los Eclipsites que lo estaban atacando.",
  ui_story_5076_50761102_14_dialog_content = "¿Cómo pasó esto?",
  ui_story_5076_50761102_15_dialog_content = "Alguien... Alguien trasladó a los guardias a otro puesto, y dejó que una horda de Eclipsites infiltrara la ciudad y matara a innumerables inocentes...",
  ui_story_5076_50761102_16_dialog_content = "No podía creer que alguien pudiera hacer algo tan horrible.",
  ui_story_5076_50761102_17_dialog_content = "¿Así que sabías que te estaban incriminando desde el principio?",
  ui_story_5076_50761102_18_dialog_content = "Sí, pero... ya no podía controlarme más.",
  ui_story_5076_50761102_19_dialog_content = "Alguien sacrificó todas esas vidas inocentes solo para destrozar mi corazón en pedazos...",
  ui_story_5076_50761102_20_dialog_content = "En el momento que me di cuenta de eso, la oscuridad nubló mi vista. Perdí... Y antes de que me diera cuenta, perdí toda apariencia de quien solía ser.",
  ui_story_5076_50761102_21_dialog_content = "Ya no soy un héroe.",
  ui_story_5076_50761102_22_dialog_content = "Friegson...",
  ui_story_5076_50761102_23_dialog_content = "Tienes que mantener la cabeza en alto, Friegson. No te rindas.",
  ui_story_5076_50761102_24_dialog_content = "Siempre estaremos a tu lado.",
  ui_story_5076_50761102_25_dialog_content = "Pero, ¿qué debería hacer ahora, Capitán? ¿Soy yo...?",
  ui_story_5076_50761102_26_dialog_content = "Te escoltaré a la capital real y le diré al rey la verdad de lo que sucedió aquí. Solicitaremos un juicio justo para ti.",
  ui_story_5076_50761102_27_dialog_content = "¿Qué? ¡No puedes hacer eso, Capitán!",
  ui_story_5076_50761102_28_dialog_content = "Lo escuchaste tú mismo: Friegson fue incriminada, ¡y es probable que la persona responsable sea parte de la corte real! Enviarla allí no sería diferente a enviarla a su muerte!",
  ui_story_5076_50761102_29_dialog_content = "¡Así es, debe haber sido Lucius! Siempre ha estado en contra nuestra, y ahora nos está eliminando uno por uno...",
  ui_story_5076_50761102_30_dialog_content = "Ya no importa, Vice Capitán. No es como si tuviera un hogar al que regresar, de todos modos...",
  ui_story_5076_50761102_31_dialog_content = "No, ¡esto no es justo para ti! Las manos de Lucius ya están en el cuello de nuestro amigo, Capitán; ¿cuánto tiempo más dejarás que esto continúe?",
  ui_story_5076_50761102_32_dialog_content = "Tenemos que... detener a ese hombre...",
  ui_story_5076_50761102_33_dialog_content = "¡Cálmate, Adras! ¡Freya y Cynthia aún están siendo vigilados!",
  ui_story_5076_50761102_34_dialog_content = "También tienes que pensar en toda la ciudad y su gente... Ahora no es el momento para tomar decisiones imprudentes.",
  ui_story_5076_50761102_35_dialog_content = "Tenemos que trabajar juntos y encontrar una manera de probar la inocencia de Friegson, ¿entiendes?",
  ui_story_5076_50761102_36_dialog_content = "Capitán... ¿Por qué no dices nada? Solías proteger incluso al más bajo de tus subordinados, pero ahora ni siquiera levantas un dedo para defender a uno de tus amigos más cercanos?",
  ui_story_5076_50761102_37_dialog_content = "Capitán... ¿Por qué...",
  ui_story_5076_50761102_38_dialog_content = "Adras, Friegson... Lo siento.",
  ui_story_5076_50761102_39_dialog_content = "El costo de restaurar la paz en nuestro reino es demasiado alto. No puedo permitir que caiga en el caos una vez más.",
  ui_story_5076_50761102_40_dialog_content = "Si decido hacer un frente, el Consejo de Ancianos y Lucius iniciarán otra guerra. No quieres ver otra sangrienta rebelión, ¿verdad?",
  ui_story_5076_50761102_41_dialog_content = "Así que por favor... Perdóname.",
  ui_story_5076_50761102_42_dialog_content = "Por doloroso que sea ceder, todo lo que podemos hacer ahora es soportarlo—",
  ui_story_5076_50761200_1_dialog_content = "<color=#e8d9bb>La pérdida de control del héroe despierta rápidamente el miedo en todo el reino, con quejas inundando la capital desde todos los rincones.</color>",
  ui_story_5076_50761200_2_dialog_content = "<color=#e8d9bb>Frostfire, quien desencadenó todo, ahora está encadenado y obligado a \"seguir luchando\" bajo la atenta mirada del reino.</color>",
  ui_story_5076_50761200_3_dialog_content = "<color=#e8d9bb>El resto de los Cazadores Silenciosos se dividen y se despliegan para guarnecer las ciudades fronterizas. Incluso los Caelestites cercanos están bajo arresto domiciliario.</color>",
  ui_story_5076_50761200_4_dialog_content = "¡Vete! Mantén esas cosas espeluznantes lejos de nuestro lugar.",
  ui_story_5076_50761200_5_dialog_content = "Solo soy un soldado y esta es mi arma. Si te niegas a hacer negocios conmigo, al menos deja que mi esposa se vaya.",
  ui_story_5076_50761200_6_dialog_content = "¿Esposa...? Qué lunático. ¡Piérdete!",
  ui_story_5076_50761200_7_dialog_content = "Sería prudente que cambiaras tu tono y retiraras tus comentarios groseros.",
  ui_story_5076_50761200_8_dialog_content = "Déjalo ir, Adras... Todavía eres su protector, así que pelear con ellos sobre estas cosas no sirve de nada.",
  ui_story_5076_50761200_9_dialog_content = "... Bien.",
  ui_story_5076_50761200_10_dialog_content = "Resulta que los rumores son ciertos. Los Cazadores Silenciosos son realmente un montón de lunáticos...",
  ui_story_5076_50761200_11_dialog_content = "No me gusta aquí, Marcela.",
  ui_story_5076_50761200_12_dialog_content = "Está bien, Adras. Simplemente no te entienden, eso es todo.",
  ui_story_5076_50761200_13_dialog_content = "Estoy seguro de que te tratarían mejor si simplemente tuvieran la oportunidad de conocerte—",
  ui_story_5076_50761200_14_dialog_content = "Mira, ese tipo está ahí de nuevo...",
  ui_story_5076_50761200_15_dialog_content = "Ugh, parece que podría perderlo en cualquier momento. Quién sabe cuándo podría...",
  ui_story_5076_50761200_16_dialog_content = "¿Cómo está todos hoy?",
  ui_story_5076_50761200_17_dialog_content = "¡Pierdete! ¡Muévete!",
  ui_story_5076_50761200_18_dialog_content = "...",
  ui_story_5076_50761200_19_dialog_content = "No te sientas desanimado. ¿Quizás te encuentres con alguien más amable la próxima vez?",
  ui_story_5076_50761200_20_dialog_content = "<color=#e8d9bb> Aferrándose a una esperanza tenue, el héroe anhela que alguien más venga al rescate.</color>",
  ui_story_5076_50761200_21_dialog_content = "Mira, aquí viene el \"Eclipsite.\"",
  ui_story_5076_50761200_22_dialog_content = "¿Un Eclipsito? ¿Dónde?",
  ui_story_5076_50761200_23_dialog_content = "¡Pónganse detrás de mí, niños! Tú también, Marcela!",
  ui_story_5076_50761200_24_dialog_content = "Me encargaré del Eclipsite—",
  ui_story_5076_50761200_25_dialog_content = "¡Jah! ¡Idiota!",
  ui_story_5076_50761200_26_dialog_content = "¡Un tonto igual que el Eclipsite! ¡Jajaja!",
  ui_story_5076_50761200_27_dialog_content = "Esos niños... ¿Están empezando a pensar como los adultos?",
  ui_story_5076_50761200_28_dialog_content = "¿Qué hice mal?",
  ui_story_5076_50761200_29_dialog_content = "<color=#e8d9bb>La situación continúa día tras día...</color>",
  ui_story_5076_50761200_30_dialog_content = "¿Por qué todos aquí me tienen miedo...?",
  ui_story_5076_50761200_31_dialog_content = "¿Es por estas malditas cicatrices...?",
  ui_story_5076_50761200_32_dialog_content = "¡No soy un Eclipsite! Sé que no lo soy—",
  ui_story_5076_50761200_33_dialog_content = "¿Ves eso? Ese tipo se volvería loco sin ninguna razón.",
  ui_story_5076_50761200_34_dialog_content = "Escuché sobre un Cazador Silencioso que era así, quemando una ciudad entera al final.",
  ui_story_5076_50761200_35_dialog_content = "No sé por qué Su Majestad aún los conserva; es demasiado amable.",
  ui_story_5076_50761200_36_dialog_content = "<color=#e8d9bb>Sigue recibiendo ataques por la espalda, contra los cuales está completamente indefenso.</color>",
  ui_story_5076_50761200_37_dialog_content = "Si me preguntas, todos deberían ser ejecutados. ¿Quién sabe lo que solían ser?",
  ui_story_5076_50761200_38_dialog_content = "¿Quién es \"Marcela\"? Cuando ese chico grita ese nombre, parece realmente triste...",
  ui_story_5076_50761200_39_dialog_content = "Quizás sea alguien a quien una vez mató, una pobre alma. Escuché que algunos Eclipsites entienden el Universese, y usan mentiras para engañar a otros y acercarse a ellos.",
  ui_story_5076_50761200_40_dialog_content = "¿Es eso cierto? Demasiado aterrador, ¿no es así?",
  ui_story_5076_50761200_41_dialog_content = "<color=#e8d9bb>Las estrellas que una vez brillaron se están apagando rápidamente.</color>",
  ui_story_5076_50761200_42_dialog_content = "Marcela... ¿Es esto lo que les pasó a Friegson y a los demás? ¿Es este el tipo de vida que llevaban?",
  ui_story_5076_50761200_43_dialog_content = "En aquel entonces, no sabía cómo se sentía ella.",
  ui_story_5076_50761200_44_dialog_content = "Si hubiera entendido en ese momento, podría haber estado allí para ella. ¿Las cosas habrían terminado de manera diferente para ella?",
  ui_story_5076_50761200_45_dialog_content = "<color=#e8d9bb>Entonces, los corazones de esas estrellas son apresados y arrastrados al abismo.</color>",
  ui_story_5076_50761200_46_dialog_content = "Oh, ¿Marcela? Finalmente recibí una carta de Ludweiss hoy.",
  ui_story_5076_50761200_47_dialog_content = "Parece que finalmente tuvo la oportunidad de escaparse y vendrá a visitarnos pronto. Aun así, me gustaría que visitara a sus antiguos vecinos primero—",
  ui_story_5076_50761200_48_dialog_content = "¿Mmm? ¿Qué estás haciendo?",
  ui_story_5076_50761200_49_dialog_content = "\"Mar—ce—la—\"",
  ui_story_5076_50761200_50_dialog_content = "¡Hay una respuesta! ¡Oh, no, él está mirando hacia aquí! ¡CORRE!",
  ui_story_5076_50761200_51_dialog_content = "¿Qué... Qué soy exactamente para ellos?",
  ui_story_5076_50761200_52_dialog_content = "¿Y por qué has dejado de susurrar en mi oído? Marcela...",
  ui_story_5076_50761200_53_dialog_content = "<color=#e8d9bb>¿Cuando las estrellas se deslizan por el cielo y caen a la tierra, finalmente volverán a la paz que merecen? ¿O es simplemente una caída desde los cielos distantes?</color>",
  ui_story_5076_50761200_54_dialog_content = "<color=#e8d9bb>Estrellas que una vez brillaron sobre las masas, ¿alguna vez encontrarán un lugar al que pertenecer?</color>",
  ui_story_5076_50761200_55_dialog_content = "<color=#e8d9bb>Si el futuro se queda solo con desesperación cuando el hermoso sueño se hace añicos... ¿la lucha aún tiene algún significado en ese punto?</color>",
  ui_story_5076_50761200_56_dialog_content = "¡Aléjate de mí, mocoso! ¡Deja de seguirme!",
  ui_story_5076_50761200_57_dialog_content = "\"Marcela—Marcela—\"",
  ui_story_5076_50761200_58_dialog_content = "Parece que está a punto de llorar.",
  ui_story_5076_50761200_59_dialog_content = "¡Apresúrate, vámonos! El \"Eclipsite\" va a perder la paciencia.",
  ui_story_5076_50761200_60_dialog_content = "Muere... Muere... Muere... Muere—",
  ui_story_5076_50761200_61_dialog_content = "<size=45>¡¡¡Eclipsito!!!</size>",
  ui_story_5076_50761200_62_dialog_content = "No lo veo... ¿Dónde está el Eclipsite?",
  ui_story_5076_50761200_63_dialog_content = "¿Y dónde estás, Marcela?",
  ui_story_5076_50761200_64_dialog_content = "Por favor, solo llámame como solías hacerlo...",
  ui_story_5076_50761300_1_dialog_content = "<color=#e8d9bb>Se suponía que el poder del reino estaba delicadamente equilibrado, pero la persistente actitud del Rey finalmente aplastó al Consejo de Ancianos que odiaba.</color>",
  ui_story_5076_50761300_2_dialog_content = "<color=#e8d9bb>Desde la expulsión del Anciano Principal, el Sumo Sacerdote Lucius ha iniciado su purga.</color>",
  ui_story_5076_50761300_3_dialog_content = "<color=#e8d9bb>¿Las acciones del Sumo Sacerdote están realmente impulsadas por sus motivos egoístas? ¿O siempre ha sido un portavoz para alguien más?</color>",
  ui_story_5076_50761300_4_dialog_content = "¡Abrir, Adras!",
  ui_story_5076_50761300_5_dialog_content = "¿Quiénes son ustedes? Espera... ¿Capitán?",
  ui_story_5076_50761300_6_dialog_content = "¿Qué pasa? ¿Ya olvidaste nuestras caras?",
  ui_story_5076_50761300_7_dialog_content = "Eso es duro, Vice Capitán. Especialmente porque vinimos a refugiarnos aquí contigo.",
  ui_story_5076_50761300_8_dialog_content = "¿Qué paso?",
  ui_story_5076_50761300_9_dialog_content = "Se descubrió una conspiración rebelde dentro del Consejo de Ancianos. Bajo órdenes secretas del rey, Lucius quería usar a los Silent Hunters para suprimirla.",
  ui_story_5076_50761300_10_dialog_content = "Pero Friegson y Freya se negaron a cumplir, y como resultado... Fueron arrestados y encarcelados.",
  ui_story_5076_50761300_11_dialog_content = "Me niego a desatar mis llamas sobre la gente, incluso si eso significa que tengo que morir.",
  ui_story_5076_50761300_12_dialog_content = "Fue entonces cuando Aquiles organizó un rescate peligroso y me sacó del arresto domiciliario para rematar.",
  ui_story_5076_50761300_13_dialog_content = "Pero todo fue gracias a Cynthia y Ludweiss que pudimos escapar de la capital de manera segura.",
  ui_story_5076_50761300_14_dialog_content = "Pronto se harán llamados para su captura inmediata. Quiero que los escoltes fuera del reino antes de eso.",
  ui_story_5076_50761300_15_dialog_content = "¿Y tú?",
  ui_story_5076_50761300_16_dialog_content = "Asumo toda la responsabilidad por todo esto, por lo que regresaré a la capital y aceptaré el castigo del rey.",
  ui_story_5076_50761300_17_dialog_content = "Cree que al entregarse, puede asegurar nuestra libertad.",
  ui_story_5076_50761300_18_dialog_content = "¿Qué? ¿Estás loco, Aquiles? ¡Tenemos que permanecer juntos!",
  ui_story_5076_50761300_19_dialog_content = "El hombre que se sienta en el trono fue una vez mi hermano de armas. Como dos lados de una falange, salvó mi vida innumerables veces.",
  ui_story_5076_50761300_20_dialog_content = "Nunca podría darle la espalda.",
  ui_story_5076_50761300_21_dialog_content = "Descansa tranquilo, encontraré la manera de hablar con el rey. Todavía hay esperanza para un mejor resultado.",
  ui_story_5076_50761300_22_dialog_content = "No hay forma de cambiar la decisión del Capitán una vez que decide hacer algo. Solo ríndete, Vice Comandante.",
  ui_story_5076_50761300_23_dialog_content = "Al menos permítenos pasar un tiempo juntos antes de separarnos de nuevo.",
  ui_story_5076_50761300_24_dialog_content = "Con las cosas como están hoy en día, ¿incluso importa ya?",
  ui_story_5076_50761300_25_dialog_content = "Nada bueno saldrá de que nos reunamos así.",
  ui_story_5076_50761300_26_dialog_content = "No digas eso, Friegson. Aquiles luchó duro para rescatar a todos y traernos aquí.",
  ui_story_5076_50761300_27_dialog_content = "Lo siento.",
  ui_story_5076_50761300_28_dialog_content = "¡Creo que es una gran idea! Ha pasado mucho tiempo desde que probé el Vice vino del Capitán, y solo pensar en ello realmente me lleva de vuelta.",
  ui_story_5076_50761300_29_dialog_content = "Entonces solo espera aquí por mí. Volveré en un minuto.",
  ui_story_5076_50761300_30_dialog_content = "No deberíamos simplemente sentarnos y esperar la bebida. ¡Preparemos algo para comer mientras tanto!",
  ui_story_5076_50761300_31_dialog_content = "Este lugar ha visto días mejores. ¿El Vice Capitán siempre ha sido tan desordenado?",
  ui_story_5076_50761300_32_dialog_content = "... ¿Alguien nota algo diferente en el estado mental del Vice Capitán?",
  ui_story_5076_50761300_33_dialog_content = "¿De qué estás hablando? Aparte del Capitán, él siempre ha hecho mejor que cualquiera de nosotros.",
  ui_story_5076_50761300_34_dialog_content = "Ese amor puro y poderoso en su corazón ha mantenido a raya su corrupción durante años.",
  ui_story_5076_50761300_35_dialog_content = "Pero Freya, puedo oler algo en él... El aroma de la desesperación.",
  ui_story_5076_50761300_36_dialog_content = "Es uno de nosotros, después de todo.",
  ui_story_5076_50761300_37_dialog_content = "¡De ninguna manera! No puedo pensar en algo más esperanzador—",
  ui_story_5076_50761300_38_dialog_content = "<size=50>¡¡¡¡Aaaaahhhh!!!!</size>",
  ui_story_5076_50761300_39_dialog_content = "¿Qué fue eso? ¡Vamos, Aquiles!",
  ui_story_5076_50761300_40_dialog_content = "¿Era esa... La voz del Vice Capitán?",
  ui_story_5076_50761300_41_dialog_content = "¿Qué pasaría si te dijera que la persona más gravemente herida en nuestro grupo no es otra que nuestro \"escudo\"?",
  ui_story_5076_50761300_42_dialog_content = "¿Todavía crees que hay esperanza, Freya?",
  ui_story_5076_50761300_43_dialog_content = "<size=45>¡Aahhhh!!!</size>",
  ui_story_5076_50761300_44_dialog_content = "<size=45>¡Eclipsitos! ¡¡¡Eclipsitos!!!</size>",
  ui_story_5076_50761300_45_dialog_content = "¿Qué es esto?",
  ui_story_5076_50761300_46_dialog_content = "Tanta destrucción... Es como si ni un solo centímetro de este lugar se hubiera salvado...",
  ui_story_5076_50761300_47_dialog_content = "¡¿Por qué?! ¿Qué hacen los Eclipsites en el sótano de mi casa?!",
  ui_story_5076_50761300_48_dialog_content = "¡¿Por qué no los noté antes?!",
  ui_story_5076_50761300_49_dialog_content = "Estas marcas de corte fueron hechas por una espada, Ludweiss...",
  ui_story_5076_50761300_50_dialog_content = "<size=45>¿Por qué? ¡¿Por qué?!?</size>",
  ui_story_5076_50761300_51_dialog_content = "Cálmate, Adras. Todos estamos aquí ahora, y no hay Eclipsites alrededor.",
  ui_story_5076_50761300_52_dialog_content = "¡No! ¡Mintieron! ¡Todos me mintieron!",
  ui_story_5076_50761300_53_dialog_content = "¡Nunca se deshicieron del Eclipsite que estaba destruyendo el templo, y ahora me siguió a casa!",
  ui_story_5076_50761300_54_dialog_content = "Todos estaban demasiado asustados para matarlo, pero yo no he podido encontrarlo por mí mismo...",
  ui_story_5076_50761300_55_dialog_content = "¿Cómo puede haber un Eclipsite tan poderoso como este? No tengo forma de derrotarlo, y Marcela no saldrá de su escondite por culpa de él...",
  ui_story_5076_50761300_56_dialog_content = "¿Puedes sentir su ubicación, Ludweiss? ¡No puedo permitir que lastime a nadie más!",
  ui_story_5076_50761300_57_dialog_content = "No dejaré que nadie más caiga a manos de los Eclipsites. No de nuevo...",
  ui_story_5076_50761300_58_dialog_content = "Capitán... Creo que finalmente...",
  ui_story_5076_50761300_59_dialog_content = "¿Así que incluso un amor tan puro como el suyo no puede detener la propagación de esta horrible corrupción?",
  ui_story_5076_50761300_60_dialog_content = "Realmente no hay futuro para nosotros después de todo.",
  ui_story_5076_50761300_61_dialog_content = "¿No puedes usar tus poderos de Caelestite para estabilizar su mente, Ludweiss?",
  ui_story_5076_50761300_62_dialog_content = "Lo siento, Aquiles, pero habría hecho eso hace mucho tiempo si fuera posible...",
  ui_story_5076_50761300_63_dialog_content = "¡Pónganse detrás de mí, todos! No se sabe cuándo atacará ese Eclipsite, ¡así que manténganse alerta!",
  ui_story_5076_50761300_64_dialog_content = "Es demasiado poderoso para...",
  ui_story_5076_50761300_65_dialog_content = "A...",
  ui_story_5076_50761300_66_dialog_content = "¿Qué hiciste?",
  ui_story_5076_50761300_67_dialog_content = "Acabo de hacer que duerma por un rato...",
  ui_story_5076_50761300_68_dialog_content = "Lo hiciste tan fácilmente, como si estuviera completamente indefenso.",
  ui_story_5076_50761300_69_dialog_content = "Debe estar tan cansado. Todo este tiempo, él ha sido el más solitario de todos nosotros.",
  ui_story_5076_50761300_70_dialog_content = "¿Crees que él todavía puede tener buenos sueños?",
  ui_story_5076_50761300_71_dialog_content = "Ciertamente lo espero.",
  ui_story_5076_50761300_72_dialog_content = "Tenías razón, Cynthia: ahora siento mucho arrepentimiento. ¿Fui demasiado arrogante?",
  ui_story_5076_50761300_73_dialog_content = "Pensé que podía cargar con todo, pero no he ayudado a una sola persona.",
  ui_story_5076_50761300_74_dialog_content = "Si hubiera tomado mi decisión en aquel entonces y los hubiera liberado a todos de su dolor—",
  ui_story_5076_50761300_75_dialog_content = "Planeabas acabar con nosotros en esa cueva durante nuestra última misión, ¿no es así? Pero al final, no pudiste hacerlo.",
  ui_story_5076_50761300_76_dialog_content = "Todo esto es mi culpa.",
  ui_story_5076_50761300_77_dialog_content = "No es tu culpa que las cosas hayan terminado así, ni la culpa de nadie más.",
  ui_story_5076_50761300_78_dialog_content = "Matar con un arma en tiempos de guerra no es un pecado, pero en tiempos de paz... La mera existencia de un arma es un pecado.",
  ui_story_5076_50761300_79_dialog_content = "¿Esas personas comunes que nos rechazan realmente nos odian desde el fondo de sus corazones? No, creo que simplemente no han tenido la oportunidad de entendernos.",
  ui_story_5076_50761300_80_dialog_content = "Todo lo que se necesita es la oportunidad correcta... Al igual que cómo el Vice Capitán y su esposa protegieron a estas personas, y ellos a cambio cuidaron de él...",
  ui_story_5076_50761300_81_dialog_content = "Desafortunadamente, no tenemos forma de hacer que todo el mundo nos entienda.",
  ui_story_5076_50761300_82_dialog_content = "Si hay alguien o algo a quien culpar por todo esto, es al destino.",
  ui_story_5076_50761300_83_dialog_content = "Aun así, no tengo remordimientos.",
  ui_story_5076_50761300_84_dialog_content = "De acuerdo. Acepté voluntariamente este resultado a cambio de salvar nuestra tierra de los Eclipsites. Si tengo que arder por esa causa, que así sea.",
  ui_story_5076_50761300_85_dialog_content = "Eso no me hace un cobarde, ¿verdad?",
  ui_story_5076_50761300_86_dialog_content = "Friegson, todos... Si alguna vez llega el día en que me convierta completamente en un Eclipsite, no se atrevan a mostrarme ninguna piedad.",
  ui_story_5076_50761300_87_dialog_content = "Creo que me iré antes que tú... Así que hasta entonces, mantén tu rayo tan preciso como hoy.",
  ui_story_5076_50761300_88_dialog_content = "... ¿Es esta realmente la única salida para todos?",
  ui_story_5076_50761300_89_dialog_content = "Como mínimo, me niego a aceptarlo.",
  ui_story_5076_50761300_90_dialog_content = "¿Todavía estás escribiendo en tu diario, eh?",
  ui_story_5076_50761300_91_dialog_content = "Hacer un registro de esto no cambiará nada.",
  ui_story_5076_50761300_92_dialog_content = "Incluso monstruos inmortales como nosotros no podemos ver nuestro propio futuro claramente.",
  ui_story_5076_50761300_93_dialog_content = "Apenas me aferro a mis recuerdos del pasado tal como están. Todos esos días felices están siendo lentamente corroídos por la oscuridad...",
  ui_story_5076_50761300_94_dialog_content = "Quizás las cosas serían mejores si todos fuéramos olvidados—",
  ui_story_5076_50761300_95_dialog_content = "¡Por supuesto que hace una diferencia!",
  ui_story_5076_50761300_96_dialog_content = "Soy un Caelestite, ¿recuerdas? ¡Nadie entiende los sentimientos y recuerdos mejor que mi gente!",
  ui_story_5076_50761300_97_dialog_content = "Si alguien alguna vez lee este diario... Al menos sabrán sobre las estrellas que guiaron a la gente de nuestro tiempo.",
  ui_story_5076_50761300_98_dialog_content = "Y si esa persona resulta ser otro Caelestite, heredará mis recuerdos y mi voluntad, y sabrá exactamente cómo me siento acerca de todos ustedes...",
  ui_story_5076_50761300_99_dialog_content = "Incluso las estrellas fugaces tienen un hogar en los corazones de aquellos que ven su belleza.",
  ui_story_5076_50761300_100_dialog_content = "Definitivamente significa algo, así que por favor... Solo déjame seguir escribiendo.",
  ui_story_5076_50761300_101_dialog_content = "Bien, pero vas a empapar todas tus páginas si no dejas de llorar.",
  ui_story_5076_50761300_102_dialog_content = "Puedes ser tan terco a veces, Ludweiss... Así que hagámoslo juntos.",
  ui_story_5076_50761300_103_dialog_content = "Después de todo... Una persona no podría posiblemente escribir todos nuestros recuerdos juntos, ¿verdad?",
  ui_story_5076_50761300_104_dialog_content = "¡Permítenos ayudarte a mantener viva la esperanza!",
  ui_story_5076_50761300_105_dialog_content = "Al menos uno de nosotros está destinado a llegar lejos en el futuro. Cuando eso suceda, no importa quién sea—",
  ui_story_5076_50761300_106_dialog_content = "Por favor, no te olvides de nosotros.",
  ui_story_5076_50761400_1_dialog_content = "<color=#e8d9bb>Mientras los viajeros cruzan la frontera, el capitán se da la vuelta como estaba planeado.</color>",
  ui_story_5076_50761400_2_dialog_content = "<color=#e8d9bb>Actuaría como un \"sacrificio\", entregándose a los perseguidores para asegurar la libertad de los otros cinco.</color>",
  ui_story_5076_50761400_3_dialog_content = "<color=#e8d9bb>¿Pero realmente estos Guerreros Estelares aceptarían tal intercambio?</color>",
  ui_story_5076_50761400_4_dialog_content = "Están en tus manos ahora, Ludweiss. Si alguno de ellos se despierta, haz que vuelvan a dormir de inmediato.",
  ui_story_5076_50761400_5_dialog_content = "¿Realmente tienes la intención de rescatar a Aquiles tú solo, Adras?",
  ui_story_5076_50761400_6_dialog_content = "¿No estás olvidando quién soy? Soy Adras, el hombre que terminó una guerra. Soy más que suficiente para gente como ellos.",
  ui_story_5076_50761400_7_dialog_content = "Regresa por ahora. El capitán y yo te alcanzaremos pronto.",
  ui_story_5076_50761400_8_dialog_content = "Adras...",
  ui_story_5076_50761400_9_dialog_content = "¿Se ha ido el Vice Capitán?",
  ui_story_5076_50761400_10_dialog_content = "Todavía puedo oír débilmente sus pasos. Dejémosle avanzar un poco más primero.",
  ui_story_5076_50761400_11_dialog_content = "¿E-Eh?",
  ui_story_5076_50761400_12_dialog_content = "Somos los Cazadores Silenciosos. Ya no hay otros como nosotros en el mundo.",
  ui_story_5076_50761400_13_dialog_content = "Puede que no tengamos un hogar, pero mientras permanezcamos juntos, eso es más que suficiente para nosotros.",
  ui_story_5076_50761400_14_dialog_content = "Vagando por la tierra como un grupo de marginados odiados... Eso me suena bien.",
  ui_story_5076_50761400_15_dialog_content = "Incluso si el mundo entero niega nuestro futuro, aún nos negamos a rendirnos.",
  ui_story_5076_50761400_16_dialog_content = "¿Sigues planeando detenernos, Ludweiss?",
  ui_story_5076_50761400_17_dialog_content = "Tenía la sensación de que me seguían, y justo como pensé...",
  ui_story_5076_50761400_18_dialog_content = "Nos encontramos de nuevo, héroe. ¿Seguramente esto debe ser el destino?",
  ui_story_5076_50761400_19_dialog_content = "¡Lucius, villano! Por el futuro del reino, juro que yo—",
  ui_story_5076_50761400_20_dialog_content = "Tú y los otros Cazadores ya han elegido traicionarnos. ¿Qué derecho tienes para hablar sobre el futuro del reino?",
  ui_story_5076_50761400_21_dialog_content = "¡Guardias! ¡Arresten a este supuesto \"héroe\"!",
  ui_story_5076_50761400_22_dialog_content = "¡Hazte a un lado! ¡No creas que puedes detenerme!",
  ui_story_5076_50761400_23_dialog_content = "¡Me niego a levantar mi espada contra personas inocentes!",
  ui_story_5076_50761400_24_dialog_content = "Un sentimiento conmovedor, pero totalmente inútil. Echa un vistazo a estos soldados, Adras; ¡no son diferentes a ti!",
  ui_story_5076_50761400_25_dialog_content = "¿Qué?",
  ui_story_5076_50761400_26_dialog_content = "¡Rarrr! ¡Grrrr!",
  ui_story_5076_50761400_27_dialog_content = "¿Todos son Eclipsites?!",
  ui_story_5076_50761400_28_dialog_content = "¡Pero están usando uniformes de soldado! ¡Esto no puede estar bien!",
  ui_story_5076_50761400_29_dialog_content = "Al igual que tú, ahora no son más que monstruos modificados. Concedido, no son casi tan fuertes como tú, pero son mucho más obedientes.",
  ui_story_5076_50761400_30_dialog_content = "¿A qué te refieres con \"modificado\"? ¿Qué has hecho con los orgullosos soldados de nuestro reino?!",
  ui_story_5076_50761400_31_dialog_content = "¿Ya te olvidaste, Adras? ¿Quizás la corrupción finalmente se ha extendido a tu mente?",
  ui_story_5076_50761400_32_dialog_content = "Si es así, solo sería aún más risible.",
  ui_story_5076_50761400_33_dialog_content = "No le escuches, Adras! Una vez que esté libre, yo—",
  ui_story_5076_50761400_34_dialog_content = "¡Guardias, sometan al capitán!",
  ui_story_5076_50761400_35_dialog_content = "¡Aquiles! Tú monstruo, Lucius! ¿Cómo pudiste hacer algo tan horrible a estos leales soldados? Yo—",
  ui_story_5076_50761400_36_dialog_content = "Jejeje, son un poco más fuertes de lo que anticipaste, ¿no?",
  ui_story_5076_50761400_37_dialog_content = "Eso es porque son el último lote de soldados aumentados del proyecto Cazadores Silenciosos.",
  ui_story_5076_50761400_38_dialog_content = "Espléndidos, ¿no? ¡Están incluso más cerca de ser Eclipsitas que cualquier versión anterior!",
  ui_story_5076_50761400_39_dialog_content = "Son más seguros, más fáciles de controlar y completamente carentes de razón. Después de todo, solo se interpondría en su camino.",
  ui_story_5076_50761400_40_dialog_content = "Deja de hablar, Lucius, o no podré contenerme más.",
  ui_story_5076_50761400_41_dialog_content = "Oh no, no podrías matarme. Soy el asesor de confianza del rey, ¿recuerdas? Si levantas siquiera un dedo hacia mí, destruiré todo lo que has trabajado tanto para proteger.",
  ui_story_5076_50761400_42_dialog_content = "Además, ya has tolerado tanto. ¿Por qué parar ahora?",
  ui_story_5076_50761400_43_dialog_content = "Por poderosos que sean los Cazadores Silenciosos, todos han sido corrompidos por Darkflow. Tu rápido deterioro psicológico es la razón por la que creo que todos deberían ser erradicados.",
  ui_story_5076_50761400_44_dialog_content = "Dime, poderoso héroe: ¿cuántos de tus preciados recuerdos han sido engullidos por la oscuridad en tu corazón? ¿O has estado viviendo en un estado de delirio todo este tiempo?",
  ui_story_5076_50761400_45_dialog_content = "¡Muere, monstruo!",
  ui_story_5076_50761400_46_dialog_content = "¡Suéltame!",
  ui_story_5076_50761400_47_dialog_content = "¡Lucius! Por jugar con las vidas de las personas y pisotear nuestra lealtad, ¡no mereces nada más que la peor de las muertes!",
  ui_story_5076_50761400_48_dialog_content = "Si eso es lo que merezco, ¿qué pasa con una abominación medio Eclipsite como tú?",
  ui_story_5076_50761400_49_dialog_content = "Echa un vistazo al reflejo en tu espada, Adras. ¿Te ves claramente ahora?",
  ui_story_5076_50761400_50_dialog_content = "Parece que realmente has olvidado la verdad. El monstruo del que has estado aullando...",
  ui_story_5076_50761400_51_dialog_content = "¡No es otro que tú!",
  ui_story_5076_50761400_52_dialog_content = "¡No le hagas caso, Adras!",
  ui_story_5076_50761400_53_dialog_content = "¡Él tiene razón, Adras! ¡No eres un monstruo!",
  ui_story_5076_50761400_54_dialog_content = "¿Marcela? ¿Cuándo llegaste aquí?",
  ui_story_5076_50761400_55_dialog_content = "¿No sabes lo peligroso que es aquí? ¡Ponte detrás de mí, rápido!",
  ui_story_5076_50761400_56_dialog_content = "¿Es este verdaderamente el hombre por el que has arriesgado vida y miembro para proteger, Aquiles? ¿Un completo loco?",
  ui_story_5076_50761400_57_dialog_content = "¡Retrocede! ¡No dejaré que la lastimes!",
  ui_story_5076_50761400_58_dialog_content = "Urgh—",
  ui_story_5076_50761400_59_dialog_content = "¡Has perdido demasiada sangre, Adras! ¡Deja de intentar defenderme!",
  ui_story_5076_50761400_60_dialog_content = "Esto no es nada, Marcela. Solo quédate atrás y déjamelo todo a mí...",
  ui_story_5076_50761400_61_dialog_content = "¡No! No quiero verte lastimado por mi culpa!",
  ui_story_5076_50761400_62_dialog_content = "¡Alto, todos! Él es el héroe más grande de nuestro reino—",
  ui_story_5076_50761400_63_dialog_content = "¡No lastimes más a mi pobre Adras!",
  ui_story_5076_50761400_64_dialog_content = "<size=45>¡¡¡Marcela!!!</size>",
  ui_story_5076_50761400_65_dialog_content = "Está bien, Adras... Siempre estaré contigo...",
  ui_story_5076_50761400_66_dialog_content = "¿Por qué... Esto no puede ser...",
  ui_story_5076_50761400_67_dialog_content = "Has estado gritando ese nombre como un lunático todo este tiempo. Marcela...",
  ui_story_5076_50761400_68_dialog_content = "Ese era el nombre de tu esposa fallecida, ¿no?",
  ui_story_5076_50761400_69_dialog_content = "¿Muerta? ¡No, ella no estaba muerta! ¡La salvé!",
  ui_story_5076_50761400_70_dialog_content = "Llegué a ella justo a tiempo...",
  ui_story_5076_50761400_71_dialog_content = "Por fin has vuelto, Adras.",
  ui_story_5076_50761400_72_dialog_content = "Esperé tanto tiempo... Por ti.",
  ui_story_5076_50761400_73_dialog_content = "¿En serio?",
  ui_story_5076_50761400_74_dialog_content = "Creo que ahora recuerdas la verdad, Adras. Tu esposa hace mucho tiempo que...",
  ui_story_5076_50761400_75_dialog_content = "<size=45>¡Lucius!</size>",
  ui_story_5076_50761400_76_dialog_content = "No... Eso no puede ser... Dime que no es verdad, Marcela...",
  ui_story_5076_50761400_77_dialog_content = "Todos esos días felices que pasamos juntos después... Todas esas veces que me recibiste de vuelta del frente... Dime que no fue una mentira, Marcela...",
  ui_story_5076_50761400_78_dialog_content = "Ese día...",
  ui_story_5076_50761400_79_dialog_content = "Urgh... Mi cabeza... No...",
  ui_story_5076_50761400_80_dialog_content = "¡Nooo!!!",
  ui_story_5076_50761400_81_dialog_content = "¡¡¡No me hagas verlo de nuevo!!!",
  ui_story_5076_50761400_82_dialog_content = "Al unirte a los Silent Hunters, debes aceptar que las modificaciones te dotarán de una porción del poder de Eclipsite.",
  ui_story_5076_50761400_83_dialog_content = "Cuando las modificaciones estén completas, serás más fuerte que nunca, pero también debes resistir la corrupción de Darkflow en todo momento.",
  ui_story_5076_50761400_84_dialog_content = "Puede interferir con tu cordura, o incluso privarte de tus recuerdos.",
  ui_story_5076_50761400_85_dialog_content = "Yo... Ya no me importa.",
  ui_story_5076_50761400_86_dialog_content = "Para evitar que tus recuerdos de Marcela sean destruidos, le pedí a Ludweiss que extrajera tu amor por ella y lo sellara dentro de tu espada.",
  ui_story_5076_50761400_87_dialog_content = "No deberías tener problemas con tus alucinaciones nunca más... Mírame, Adras. ¿Recuerdas algo más?",
  ui_story_5076_50761400_88_dialog_content = "Marcela... En aquel entonces, ella...",
  ui_story_5076_50761400_89_dialog_content = "No, no, no—",
  ui_story_5076_50761400_90_dialog_content = "¡No más!",
  ui_story_5076_50761400_91_dialog_content = "... No cumplí con mi promesa. La decepcioné.",
  ui_story_5076_50761400_92_dialog_content = "La abandoné, y ella <size=45>murió en oscuridad y desesperación</size>.",
  ui_story_5076_50761400_93_dialog_content = "No quiero pensar en nada más, así que modifícame tanto como sea posible... Además, ya lo he perdido todo.",
  ui_story_5076_50761400_94_dialog_content = "Haré cualquier cosa si eso significa que puedo seguir matando a los Eclipsites.",
  ui_story_5076_50761400_95_dialog_content = "En el momento en que Marcela murió, él comenzó a tener esas alucinaciones... Nadie debería tener que vivir así.",
  ui_story_5076_50761400_96_dialog_content = "¿Estás seguro de que no hay manera de eliminar sus recuerdos sobre su muerte, Ludweiss?",
  ui_story_5076_50761400_97_dialog_content = "Los recuerdos no son como una cuerda, Aquiles. No puedo simplemente cortar una pieza y atar el resto.",
  ui_story_5076_50761400_98_dialog_content = "Si intento eliminar un recuerdo tan doloroso como ese, también afectará el resto de sus recuerdos de Marcela.",
  ui_story_5076_50761400_99_dialog_content = "¿O me estás pidiendo que la borre completamente de su mente? Porque eso sería mucho más cruel que cualquier otra cosa.",
  ui_story_5076_50761400_100_dialog_content = "Solo déjalo así. Al menos, el amor en su hoja está a salvo de la corrupción en su cuerpo. Va a lograrlo, estoy seguro de ello...",
  ui_story_5076_50761400_101_dialog_content = "Aunque no estuvieras de acuerdo con mi uso del odio para impulsarlo a la batalla, quería protegerlo igual que tú.",
  ui_story_5076_50761400_102_dialog_content = "¿Realmente crees que esto es lo mejor? ¿Dejarlo atrapado en una ilusión, buscando constantemente un <color=#FFB400>falso</color> consuelo? Si algo alguna vez lo despierta de esta <color=#FFB400>dulce ilusión</color>...",
  ui_story_5076_50761400_103_dialog_content = "Mientras <color=#FFB400>su espada esté a su lado</color>, la ilusión continuará preservando su sentido de identidad, así como sus recuerdos de Marcela.",
  ui_story_5076_50761400_104_dialog_content = "Confía en mí, es mejor que dejarlo enfrentar la cruel realidad de su muerte y permitir que el odio deforme su corazón...",
  ui_story_5076_50761400_105_dialog_content = "¿M-Marcela? ¡Quedarse atrás, es peligroso aquí!",
  ui_story_5076_50761400_106_dialog_content = "¿Es ese... el Cazador Silencioso?",
  ui_story_5076_50761400_107_dialog_content = "Tan aterrador. Es difícil imaginar que es un héroe legendario. ¡Míralo! Está completamente... <color=#FFB400>LOCO</color>!",
  ui_story_5076_50761400_108_dialog_content = "Si te niegas a hacer negocios conmigo, al menos deja que mi esposa entre.",
  ui_story_5076_50761400_109_dialog_content = "<color=#FFB400>¿Esposa? ¿Cuándo conseguiste una esposa? ¡Vete, estás loco!</color>",
  ui_story_5076_50761400_110_dialog_content = "Parece que realmente has olvidado la verdad. El monstruo del que has estado aullando...",
  ui_story_5076_50761400_111_dialog_content = "¡No es otro que tú!",
  ui_story_5076_50761400_112_dialog_content = "El templo—",
  ui_story_5076_50761400_113_dialog_content = "Marcela tiene miedo del templo—",
  ui_story_5076_50761400_114_dialog_content = "No, eso no es. Soy yo quien tiene miedo de eso... Porque ese montón de escombros es donde Marcela <color=#FFB400>murió</color>.",
  ui_story_5076_50761400_115_dialog_content = "Por eso tengo que destruirlo—",
  ui_story_5076_50761400_116_dialog_content = "<color=#FFB400>¡Tengo que destruirlo todo!</color>",
  ui_story_5076_50761400_117_dialog_content = "<size=45>¡Aaaaaah!!!</size>",
  ui_story_5076_50761400_118_dialog_content = "<size=45>¡Muere, Eclipsites!!!</size>",
  ui_story_5076_50761400_119_dialog_content = "<size=50>¡Todos ustedes deben morir!!!</size>",
  ui_story_5076_50761500_1_dialog_content = "¿Qué pasó aquí? El suelo... ¡Está cubierto con restos de Eclipsite!",
  ui_story_5076_50761500_2_dialog_content = "Es el Vice Capitán. Debe haber enloquecido de nuevo.",
  ui_story_5076_50761500_3_dialog_content = "¡Tenemos que detenerlo antes de que lastime a Ludweiss!",
  ui_story_5076_50761500_4_dialog_content = "Veo a alguien intentando escapar de allá...",
  ui_story_5076_50761500_5_dialog_content = "¡Ven aquí, Cynthia! Nosotros... ¡Ya no podemos contener al Capitán Vice!",
  ui_story_5076_50761500_6_dialog_content = "¡Marcela—Marcela—!",
  ui_story_5076_50761500_7_dialog_content = "¿Por qué... Por qué no podría haber sido yo...",
  ui_story_5076_50761500_8_dialog_content = "¡Eclipsites! ¡Muere, monstruos!!!",
  ui_story_5076_50761500_9_dialog_content = "¿Qué le pasó a él?",
  ui_story_5076_50761500_10_dialog_content = "Fue empujado demasiado lejos justo ahora, y sus recuerdos se desmoronaron a través de la ilusión que lo estaba protegiendo.",
  ui_story_5076_50761500_11_dialog_content = "¿Entonces qué debemos hacer?",
  ui_story_5076_50761500_12_dialog_content = "¡Todavía nos queda una última opción! ¿Recuerdas, Ludweiss?",
  ui_story_5076_50761500_13_dialog_content = "Pero si hacemos eso...",
  ui_story_5076_50761500_14_dialog_content = "¿Estás diciendo que quieres dejarlo así?",
  ui_story_5076_50761500_15_dialog_content = "¿Todavía recuerdas de lo que hablamos ese día, capitán?",
  ui_story_5076_50761500_16_dialog_content = "No creo que al Vice Capitán le importe si eres tú quien lo hace—",
  ui_story_5076_50761500_17_dialog_content = "¡No! Solo... Déjame encargarme de eso.",
  ui_story_5076_50761500_18_dialog_content = "¡Contamos contigo, Ludweiss...",
  ui_story_5076_50761500_19_dialog_content = "Lo siento mucho, Adras... Esta vez, eliminaré el origen de tu sufrimiento!",
  ui_story_5076_50761500_20_dialog_content = "¿Qué estás haciendo, Ludweiss?!",
  ui_story_5076_50761500_21_dialog_content = "¡Estoy eliminando completamente los recuerdos de Marcela de su mente! De esa manera, finalmente puede comenzar a buscar un nuevo futuro...",
  ui_story_5076_50761500_22_dialog_content = "No...",
  ui_story_5076_50761500_23_dialog_content = "No quiero un nuevo futuro, así que...",
  ui_story_5076_50761500_24_dialog_content = "¡No te atrevas a tocar mis recuerdos de ella! ¡Es todo lo que me queda!!!",
  ui_story_5076_50761500_25_dialog_content = "¡Cuidado!",
  ui_story_5076_50761500_26_dialog_content = "¡Ludweiss!",
  ui_story_5076_50761500_27_dialog_content = "(Estaba tan cerca... Pero no pude terminarlo...)",
  ui_story_5076_50761500_28_dialog_content = "¿Qué estás leyendo?",
  ui_story_5076_50761500_29_dialog_content = "Oh, solo un viejo y fragmentado diario que la señorita Sheol me vendió barato. Aunque le faltan muchas páginas, ¡lo que está escrito aquí es realmente interesante!",
  ui_story_5076_50761500_30_dialog_content = "(¿Es esto... Un recuerdo? Pero este sentimiento... Es tan lejano... No puedo verlo claramente...)",
  ui_story_5076_50761500_31_dialog_content = "... Por alguna razón, se siente extrañamente familiar.",
  ui_story_5076_50761500_32_dialog_content = "¡Entiendo lo que quieres decir! Tan pronto como lo recogí, sentí como si estuviera de vuelta en Eraveil.",
  ui_story_5076_50761500_33_dialog_content = "¿Eraveil?",
  ui_story_5076_50761500_34_dialog_content = "¿Eh? ¿Dijiste algo?",
  ui_story_5076_50761500_35_dialog_content = "No escuché a nadie hablar.",
  ui_story_5076_50761500_36_dialog_content = "Eso es extraño... De todos modos, este diario es un registro de los viajes de un Caelestite. Aunque no puedo leer su escritura, puedo ver los recuerdos del Caelestite solo con tenerlo en mis manos.",
  ui_story_5076_50761500_37_dialog_content = "¿Puedes mostrarme también?",
  ui_story_5076_50761500_38_dialog_content = "¿En serio? Esta es la primera vez que te veo tan interesado en algo.",
  ui_story_5076_50761500_39_dialog_content = "¡Claro, veámoslos juntos! Debería poder usar mis habilidades psíquicas en ti y en el diario al mismo tiempo...",
  ui_story_5076_50761500_40_dialog_content = "Solo avísame si algo no se siente bien—",
  ui_story_5076_50761500_41_dialog_content = "<color=#FFB400>Regal.</color>",
  ui_story_5076_50761500_42_dialog_content = "¿Estabas soñando con el futuro lejano, Adras? ¿O soñaste conmigo después de todos esos años?",
  ui_story_5076_50761500_43_dialog_content = "¿Podría ser... Que en aquel entonces...",
  ui_story_5076_50761500_44_dialog_content = "Finalmente despierto, ¿eh?",
  ui_story_5076_50761500_45_dialog_content = "¿Capitán...? ¿Qué pasó? ¿Dónde estamos?",
  ui_story_5076_50761500_46_dialog_content = "¿Puedes recordar algo?",
  ui_story_5076_50761500_47_dialog_content = "Yo... Soy Regal, y yo...",
  ui_story_5076_50761500_48_dialog_content = "Se supone que debo hacer algo... Pero no puedo recordar qué es.",
  ui_story_5076_50761500_49_dialog_content = "Capitán, él...",
  ui_story_5076_50761500_50_dialog_content = "El reino está a salvo de los Eclipsites, lo que significa que finalmente puedo volver a casa y disfrutar de una vida pacífica... Pero, ¿dónde está mi casa?",
  ui_story_5076_50761500_51_dialog_content = "Hay este calor en mi pecho... No puedo describirlo realmente, pero me siento mucho más ligera ahora.",
  ui_story_5076_50761500_52_dialog_content = "Siento como si me faltara alguien. Por alguna razón, no puedo recordar su cara, pero aún me siento satisfecho.",
  ui_story_5076_50761500_53_dialog_content = "¿Es esta la felicidad de la que me hablabas, Capitán?",
  ui_story_5076_50761500_54_dialog_content = "¿Capitán? ¿Qué sucede?",
  ui_story_5076_50761500_55_dialog_content = "... Vete.",
  ui_story_5076_50761500_56_dialog_content = "¿Irme? ¿Pero a dónde debería ir?",
  ui_story_5076_50761500_57_dialog_content = "Yo... Yo no sé. Pero si tu corazón te dice que vayas a algún lugar, simplemente síguelo.",
  ui_story_5076_50761500_58_dialog_content = "Vete y no vuelvas nunca más, Adras.",
  ui_story_5076_50761500_59_dialog_content = "¿Mi corazón...?",
  ui_story_5076_50761500_60_dialog_content = "Es cierto... Quiero vivir una vida tranquila y pacífica... Pero, ¿a dónde debería ir para hacer eso?",
  ui_story_5076_50761500_61_dialog_content = "Lo siento mucho, todos. Todo esto es mi culpa... No pude hacerlo.",
  ui_story_5076_50761500_62_dialog_content = "Quería que tus sueños terminaran en el momento perfecto, pero no pude hacerlo... No pude apuntarte con mi espada.",
  ui_story_5076_50761500_63_dialog_content = "Así que por favor, simplemente mantente alejado. No muestres tus caras en el reino nunca más.",
  ui_story_5076_50761500_64_dialog_content = "¿Estás seguro de que no puedes venir con nosotros, Capitán?",
  ui_story_5076_50761500_65_dialog_content = "El reino está descendiendo nuevamente al caos. No puedo simplemente dejarlo así.",
  ui_story_5076_50761500_66_dialog_content = "Ese cobarde sumo sacerdote logró escapar... Parece que todo está estrechamente vinculado al rey. ¿Realmente no hay nada que podamos hacer?",
  ui_story_5076_50761500_67_dialog_content = "Yo... Yo juré un juramento de nunca atacar a los civiles, así que cuéntame fuera.",
  ui_story_5076_50761500_68_dialog_content = "Olvídalo, Cynthia. Enfrentarse al rey no cambiará nada, incluso si logramos vengarnos de él. Solo crearía más agitación para el reino.",
  ui_story_5076_50761500_69_dialog_content = "La verdad es que el rey solo está tratando de aferrarse a su poder. Aparte de eso, definitivamente es digno de liderar a sus súbditos.",
  ui_story_5076_50761500_70_dialog_content = "¿Pero sus súbditos no merecen justicia también? Si no se hace nada, ¿cómo podrán prevenir que más personas salgan lastimadas?",
  ui_story_5076_50761500_71_dialog_content = "El reino está en ruinas y nos ven como nada más que monstruos. No hay razón para que avivemos las llamas.",
  ui_story_5076_50761500_72_dialog_content = "Ya veo... Desde permanecer juntos hasta separarnos, todo lo que se necesita es un solo paso.",
  ui_story_5076_50761500_73_dialog_content = "Cynthia?",
  ui_story_5076_50761500_74_dialog_content = "Parece que nuestros caminos son diferentes después de todo. En ese caso, me voy ahora.",
  ui_story_5076_50761500_75_dialog_content = "Respetaré la decisión de todos y me abstendré de hacer cualquier cosa.",
  ui_story_5076_50761500_76_dialog_content = "... Espero que encuentres la paz algún día, Cynthia. Adiós.",
  ui_story_5076_50761500_77_dialog_content = "¿Cuáles son tus pensamientos, Friegson?",
  ui_story_5076_50761500_78_dialog_content = "No importa a dónde vaya, siempre seré visto como un criminal. Por eso... quiero ir contigo y entregarme, Capitán.",
  ui_story_5076_50761500_79_dialog_content = "Freya y Adras, cuídense mucho.",
  ui_story_5076_50761500_80_dialog_content = "¿Cuánto tiempo más vas a trabajar para ese hombre?",
  ui_story_5076_50761500_81_dialog_content = "No trabajaré para él, Freya. Después de todo esto, no tengo esperanzas de algo así.",
  ui_story_5076_50761500_82_dialog_content = "Pero el reino necesita su Claymore si quiere extinguir la rebelión inminente.",
  ui_story_5076_50761500_83_dialog_content = "Al igual que tú, tengo un deber que simplemente no puedo abandonar.",
  ui_story_5076_50761500_84_dialog_content = "Mi único consejo para ti es que tomes a Ludweiss y vayas a un lugar muy lejos de aquí.",
  ui_story_5076_50761500_85_dialog_content = "Nuestros caminos nunca pueden cruzarse de nuevo.",
  ui_story_5076_50761500_86_dialog_content = "Tengo el deber de eliminar cualquier amenaza para nuestro reino. La próxima vez que nos encontremos, no tendré más opción que...",
  ui_story_5076_50761601_1_dialog_content = "Adras!",
  ui_story_5076_50761601_2_dialog_content = "¿Por fin estás despierto? Has estado durmiendo durante tanto tiempo.",
  ui_story_5076_50761601_3_dialog_content = "¿Por qué el Vice Capitán te atacó de repente así? Afortunadamente, la herida no fue demasiado grave. Ya me encargué de ella por ti.",
  ui_story_5076_50761601_4_dialog_content = "Pero, juzgando por tus viejas heridas, parece que todavía existe un riesgo de corrupción... ¿Cómo has logrado mantenerlo a raya todo este tiempo? ¿Es este otro de tus poderes de Caelestite?",
  ui_story_5076_50761601_X4_dialog_content = "... ¿Dónde está el resto?",
  ui_story_5076_50761601_5_dialog_content = "Todos se han ido ahora, incluso nuestro Vice Capitán amnésico. Él tampoco sabía a dónde iba.",
  ui_story_5076_50761601_6_dialog_content = "Pero para ser justos, yo tampoco. Es bueno que todavía estés aquí... Al menos podemos seguir vagando juntos.",
  ui_story_5076_50761601_7_dialog_content = "No pude borrar completamente sus recuerdos de Marcela... Si él la recuerda de nuevo...",
  ui_story_5076_50761601_8_dialog_content = "Pero parece que el Vice Capitán ya ha perdido la mayoría de sus recuerdos... ¿Me pregunto a dónde vagará ahora?",
  ui_story_5076_50761601_9_dialog_content = "Es cierto... Con tu larga vida, tiene mucho sentido que deambules...",
  ui_story_5076_50761601_10_dialog_content = "¿Ludweiss?",
  ui_story_5076_50761601_11_dialog_content = "¿Confías en mí, Freya?",
  ui_story_5076_50761601_12_dialog_content = "Si lo haces, entonces ayúdame a buscar a todos de nuevo.",
  ui_story_5076_50761601_13_dialog_content = "De esa manera, podría haber una oportunidad para cambiar las cosas para nosotros.",
  ui_story_5076_50761601_14_dialog_content = "Estas ruinas... ¿Qué es este lugar? ¿Por qué vine aquí sin darme cuenta?",
  ui_story_5076_50761601_15_dialog_content = "Se siente tan familiar... ¿He estado aquí antes?",
  ui_story_5076_50761601_16_dialog_content = "Quizás.",
  ui_story_5076_50761601_17_dialog_content = "¿Eh? Freya... ¿Eres tú?",
  ui_story_5076_50761601_18_dialog_content = "No me hagas caso, sigue buscando. Estoy seguro de que hay algo familiar para ti escondido aquí.",
  ui_story_5076_50761601_19_dialog_content = "Estas huellas de fuego y destrucción... ¿Fueron los Eclipsites responsables de esto?",
  ui_story_5076_50761601_20_dialog_content = "También hay una tumba aquí... Pero, ¿quién pondría esto dentro de una casa?",
  ui_story_5076_50761601_21_dialog_content = "Este lugar está cubierto de malas hierbas, ¿eh?",
  ui_story_5076_50761601_22_dialog_content = "¿Qué es esto—",
  ui_story_5076_50761601_23_dialog_content = "¿Un mural quemado...?",
  ui_story_5076_50761601_24_dialog_content = "¿Todavía lo recuerdas?",
  ui_story_5076_50761601_25_dialog_content = "¿Qué? No recuerdo nada... Pero este mural parece representar una ceremonia de algún tipo.",
  ui_story_5076_50761601_26_dialog_content = "¿Qué podría ser...?",
  ui_story_5076_50761601_27_dialog_content = "\"Dicen que la primera persona en pintar un mural así fue un loco.\"",
  ui_story_5076_50761601_28_dialog_content = "\"Y que para escapar del sufrimiento en su vida, creó una realidad completamente nueva.\"",
  ui_story_5076_50761601_29_dialog_content = "\"¿Puso fin a su sufrimiento?\"",
  ui_story_5076_50761601_30_dialog_content = "\"No. Solo lo selló.\"",
  ui_story_5076_50761601_31_dialog_content = "\"Ya veo...\"",
  ui_story_5076_50761601_32_dialog_content = "M... ¿Marcela?",
  ui_story_5076_50761601_33_dialog_content = "Mientras trabajamos hacia nuestro sueño, sigamos creando hermosos recuerdos juntos.",
  ui_story_5076_50761601_34_dialog_content = "Prometo apreciar cada maravilloso momento de nuestras vidas—",
  ui_story_5076_50761601_35_dialog_content = "Ah... Ahhh...",
  ui_story_5076_50761601_36_dialog_content = "Marcela... Mi dulce Marcela...",
  ui_story_5076_50761601_37_dialog_content = "Finalmente... Estoy a tu lado una vez más...",
  ui_story_5076_50761601_38_dialog_content = "Y así termina la historia del gran héroe Adras. Dime, Freya; ¿por qué insistimos en vivir?",
  ui_story_5076_50761601_39_dialog_content = "¿Cuál es el punto de sobrevivir en este mundo retorcido si eso significa perder todo lo que nos importa?",
  ui_story_5076_50761601_40_dialog_content = "Este mundo ya no nos necesita.",
  ui_story_5076_50761601_41_dialog_content = "Quizás finalmente sea el momento de liberar a Adras de su miseria... Y a nosotros mismos.",
  ui_story_5076_50761601_42_dialog_content = "Ludweiss dijo que encontró un camino hacia un nuevo futuro para nosotros, aunque a un costo.",
  ui_story_5076_50761601_43_dialog_content = "¿Aún estás dispuesto a confiar en otras personas?",
  ui_story_5076_50761601_44_dialog_content = "Así es. Siempre pondré mi fe en la esperanza.",
  ui_story_5076_50761601_45_dialog_content = "Vamos, Cynthia. Es hora de que los Cazadores Silenciosos tengan una última reunión.",
  ui_story_5076_50761601_X45_dialog_content = "<color=#e8d9bb>Entonces, las estrellas se lanzaron una vez más, negándose a inclinarse. Después de todas esas batallas luchadas por el Dios de Luz en retirada, esta vez, su lucha es finalmente por ellos mismos.</color>",
  ui_story_5076_50761601_46_dialog_content = "Están aquí, Aquiles.",
  ui_story_5076_50761601_47_dialog_content = "Adras, Freya, Friegson, e incluso Cynthia... Todos están aquí ahora.",
  ui_story_5076_50761601_48_dialog_content = "¿Y estás seguro de que esto funcionará, Ludweiss?",
  ui_story_5076_50761601_49_dialog_content = "No completamente, pero... Mi corazón me dice que confíe en lo que vi cuando estaba inconsciente.",
  ui_story_5076_50761601_50_dialog_content = "En mil años, todavía estarán esperando un lugar al que llamar hogar. Cuando llegue ese momento... Finalmente serán libres.",
  ui_story_5076_50761601_51_dialog_content = "Estoy seguro de que entonces encontrarán su felicidad.",
  ui_story_5076_50761601_52_dialog_content = "Confío en ti, Ludweiss. Pero, ¿qué tipo de precio tendrás que pagar para sellarlos de esta manera?",
  ui_story_5076_50761601_53_dialog_content = "¿No te dije que no subestimes a los Caelestites? ¡Nadie comprende el poder del alma mejor que nosotros!",
  ui_story_5076_50761601_54_dialog_content = "A los Cazadores Silenciosos se les otorgaron cuerpos inmortales como resultado de sus modificaciones.",
  ui_story_5076_50761601_55_dialog_content = "Y al capturar sus poderosas emociones y convertirlas en \"piedras angulares\", sus almas pueden ser selladas en un estado latente.",
  ui_story_5076_50761601_56_dialog_content = "Permanecerán vigilantes dentro de su sueño de mil años, pero más allá de eso... Tendrán que usar sus recuerdos para resistir el paso del tiempo.",
  ui_story_5076_50761601_57_dialog_content = "Pero...",
  ui_story_5076_50761601_58_dialog_content = "¡Ahora!",
  ui_story_5076_50761601_59_dialog_content = "¿Qué es esto... ¿Una formación mágica? Espera, ¿qué crees que estás haciendo, Capitán?!",
  ui_story_5076_50761601_60_dialog_content = "¿No nos llamaste a la arena para...",
  ui_story_5076_50761601_61_dialog_content = "Lo siento, pero esta es la única forma en que puedo asegurar tu paz eterna... Te deseo a todos los más dulces sueños.",
  ui_story_5076_50761601_62_dialog_content = "<color=#e8d9bb>La pasión dentro de Friegson había sido consumida por el fuego hace mucho tiempo, dejando solo un puñado de cenizas.</color>",
  ui_story_5076_50761601_63_dialog_content = "<color=#e8d9bb>Entonces, la única emoción que queda para sellarla podría ser el odio.</color>",
  ui_story_5076_50761601_64_dialog_content = "<color=#e8d9bb>Los Caelestites ordinarios no pueden lograr tal hazaña, mucho menos aquellos atormentados por viejas heridas.</color>",
  ui_story_5076_50761601_65_dialog_content = "<color=#e8d9bb>Sin embargo, si un Caelestite está dispuesto a sacrificar su vida, quemándose a sí mismo para preservar las emociones de los demás...</color>",
  ui_story_5076_50761601_66_dialog_content = "¡Duerme!",
  ui_story_5076_50761601_67_dialog_content = "¿Por qué...?",
  ui_story_5076_50761601_68_dialog_content = "Puedes descansar tranquilo ahora, Friegson. Prometo que tus sueños estarán libres de tristeza de ahora en adelante.",
  ui_story_5076_50761601_69_dialog_content = "No importa... Mientras sean ustedes los que me traicionan... No me importa...",
  ui_story_5076_50761601_70_dialog_content = "¿Qué le has hecho a Friegson, Capitán? ¿¡Por qué la emboscarías de esta manera?!",
  ui_story_5076_50761601_71_dialog_content = "¿Todavía estamos en la oscuridad? El rey desea deshacerse de ustedes, criaturas peligrosas, y Aquiles ha elegido ponerse del lado de su rey.",
  ui_story_5076_50761601_72_dialog_content = "¿Lucius? ¿Cómo sigues vivo...?",
  ui_story_5076_50761601_73_dialog_content = "¿No vas a negar sus palabras, Capitán? ¡Solo dime que está mintiendo y te creeré!",
  ui_story_5076_50761601_74_dialog_content = "¡Guardias! ¡Atrapen a estos viles fugitivos!",
  ui_story_5076_50761601_75_dialog_content = "Dejo el resto a usted, Capitán. Confío en que no decepcionará a Su Majestad, ¿verdad?",
  ui_story_5076_50761601_76_dialog_content = "¡¡¡Capitán!!!",
  ui_story_5076_50761601_77_dialog_content = "¡Estos Eclipsites parecen aún más fuertes que antes! Cynthia, mantente en tu...",
  ui_story_5076_50761601_78_dialog_content = "¡Cuidado!",
  ui_story_5076_50761601_79_dialog_content = "Cynthia? Tú...",
  ui_story_5076_50761601_80_dialog_content = "Como dije, Freya... Me iré antes que tú. Si hay un futuro para nosotros allá afuera, espero que tú—",
  ui_story_5076_50761601_81_dialog_content = "Cynthia!",
  ui_story_5076_50761601_82_dialog_content = "Como dije antes, tengo el deber de destruir todas y cada una de las amenazas al reino.",
  ui_story_5076_50761601_83_dialog_content = "Ya no soy tu capitán. Soy un verdugo al servicio del reino.",
  ui_story_5076_50761601_84_dialog_content = "Ven, Regal.",
  ui_story_5076_50761601_85_dialog_content = "Ahora que finalmente recuerdas, concentra toda tu ira y odio... Y desátalo sobre mí.",
  ui_story_5076_50761601_86_dialog_content = "<size=45>Tú—</size>",
  ui_story_5076_50761601_87_dialog_content = "<size=45>Claymore—¡¡¡</size>",
  ui_story_5076_50761602_1_dialog_content = "<color=#e8d9bb>A pesar de la evidente vulnerabilidad en sus emociones de Adras, su fuerza y voluntad de combate son increíblemente formidables.</color>",
  ui_story_5076_50761602_2_dialog_content = "<color=#e8d9bb>Para apoderarse de la espada que contiene la última memoria de Adras, Aquiles toma intencionalmente un golpe de la espada.</color>",
  ui_story_5076_50761602_3_dialog_content = "Perdóname... Adras.",
  ui_story_5076_50761602_4_dialog_content = "<color=#e8d9bb>Después de clavar la espada que acababa de arrebatar de vuelta en Adras, perdió instantáneamente la fuerza, colapsando al suelo.</color>",
  ui_story_5076_50761602_5_dialog_content = "<color=#e8d9bb>Mientras tanto, el sello que apunta a Freya y Cynthia también ha sido completado.</color>",
  ui_story_5076_50761602_6_dialog_content = "Has hecho bien, leal capitán del rey. ¡Ahora erradica a estos monstruos de una vez por todas!",
  ui_story_5076_50761602_7_dialog_content = "Capitán Aquiles... ¿Por qué...?",
  ui_story_5076_50761602_8_dialog_content = "Ludweiss dice que esta es la única forma de cambiar nuestro destino, Adras... Pero no te preocupes, nos volveremos a ver algún día.",
  ui_story_5076_50761602_9_dialog_content = "Cuando llegue ese día, espero que encuentres tu felicidad una vez más.",
  ui_story_5076_50761602_10_dialog_content = "¿Ya terminó, Ludweiss?",
  ui_story_5076_50761602_11_dialog_content = "Sus almas han sido selladas dentro de sus cuerpos inmortales... Donde permanecerán dormidas... hasta...",
  ui_story_5076_50761602_12_dialog_content = "Dijiste que este sueño profundo, junto con su corrupción, tiene la posibilidad de dañar sus recuerdos e incluso su cordura...",
  ui_story_5076_50761602_13_dialog_content = "Pero incluso si es solo Adras... Tiene tan poca alegría en su vida como está. Al menos... Debería poder aferrarse a sus recuerdos felices, ¿verdad?",
  ui_story_5076_50761602_14_dialog_content = "Lo siento... Pero el Caelestite no es todopoderoso... Todo lo que podemos hacer ahora... es esperar.",
  ui_story_5076_50761602_15_dialog_content = "Espero que su locura se extinga después de mil años... Si pueden recordar incluso un solo recuerdo feliz para entonces... Todo habrá valido la pena.",
  ui_story_5076_50761602_16_dialog_content = "Urgh, estoy casi en mi límite... Pero todavía no he llegado a Adras...",
  ui_story_5076_50761602_17_dialog_content = "(Mira hacia el cielo, y las estrellas brillarán en respuesta.)",
  ui_story_5076_50761602_18_dialog_content = "(El calor de su luz sigue siendo el mismo, incluso después de mil años.)",
  ui_story_5076_50761602_19_dialog_content = "(¡Déjame ayudarte esta vez!)",
  ui_story_5076_50761602_20_dialog_content = "Esta voz... ¿Eres de aquel tiempo distante?",
  ui_story_5076_50761602_X20_dialog_content = "¡Despierta, Regal!",
  ui_story_5076_50761602_X21_dialog_content = "Entonces veámoslos juntos... <color=#FFB400>Regal</color>.",
  ui_story_5076_50761602_21_dialog_content = "Ya veo... Parece que mis esfuerzos no fueron en vano después de todo...",
  ui_story_5076_50761602_22_dialog_content = "Esos recuerdos iluminados por las estrellas resistieron la prueba del tiempo, y ahora finalmente están en las manos de otro Caelestite...",
  ui_story_5076_50761602_23_dialog_content = "He estado sintiendo anhelo todo este tiempo, y esas voces han estado intentando tan duro alcanzarme.",
  ui_story_5076_50761602_24_dialog_content = "Nuestras emociones comunes nos unen, creando lazos que trascienden el flujo del tiempo...",
  ui_story_5076_50761602_25_dialog_content = "Adras! Ya puedo verlo... Ese futuro es real.",
  ui_story_5076_50761602_26_dialog_content = "Dentro de incontables años, alguien estará esperando tu regreso triunfal.",
  ui_story_5076_50761602_27_dialog_content = "No quiero...",
  ui_story_5076_50761602_28_dialog_content = "No quiero vida eterna. No necesito la eternidad...",
  ui_story_5076_50761602_29_dialog_content = "Todo lo que quiero... es el momento que se me escapó de las manos... Eso es correcto... Todo lo que necesito es Marcela.",
  ui_story_5076_50761602_30_dialog_content = "¡Así que por favor... Solo déjame ir! ¡No quiero ser sellado! Déjame yacer al lado de Marcela y dormir por el resto del tiempo!",
  ui_story_5076_50761602_31_dialog_content = "Si eso es lo que quieres...",
  ui_story_5076_50761602_32_dialog_content = "Ayúdame, Marcela... Y tú también, mi distante amigo—",
  ui_story_5076_50761602_33_dialog_content = "¡Ayúdame a convertir su anhelo en la fuerza que necesita para sobrevivir!",
  ui_story_5076_50761602_34_dialog_content = "(Deja que la persona en sus recuerdos permanezca a su lado—)",
  ui_story_5076_50761602_35_dialog_content = "... Marcela?",
  ui_story_5076_50761602_36_dialog_content = "No llores, Adras... Estoy justo aquí...",
  ui_story_5076_50761602_37_dialog_content = "Espera, Marcela! ¡No te vayas!",
  ui_story_5076_50761602_38_dialog_content = "No me voy a ninguna parte, mi dulce Adras. Siempre estaré contigo, ahora y para siempre...",
  ui_story_5076_50761602_39_dialog_content = "Así que no tengas miedo... Todos tus amigos quieren que duermas, ahora descansa tu cansada cabeza...",
  ui_story_5076_50761602_40_dialog_content = "Dormir... Así que finalmente podemos—",
  ui_story_5076_50761602_41_dialog_content = "¡No! ¡Por favor!",
  ui_story_5076_50761602_42_dialog_content = "¡Marcela! ¡No te vayas!",
  ui_story_5076_50761602_43_dialog_content = "No llores, Adras.",
  ui_story_5076_50761602_44_dialog_content = "Nuestros recuerdos, nuestra voluntad... Incluso nuestra fe.",
  ui_story_5076_50761602_45_dialog_content = "Los dejamos todos con Marcela, para que siempre pueda estar a tu lado.",
  ui_story_5076_50761602_46_dialog_content = "Mientras aún tengas un poco de apego a este mundo y estés dispuesto a poner tu fe en la esperanza.",
  ui_story_5076_50761602_47_dialog_content = "(Tus sueños nunca estarán solos.)",
  ui_story_5076_50761602_48_dialog_content = "Siempre estarás juntos.",
  ui_story_5076_50761602_49_dialog_content = "(Ven conmigo, <color=#FFB400>Adras</color>. Es hora de despertar de tu <color=#FFB400>sueño</color> de mil años—)",
  ui_story_5076_50761602_50_dialog_content = "Cuando finalmente <color=#FFB400>despiertes</color>, es posible que no recuerdes nada. Si eso sucede, por favor no estés triste.",
  ui_story_5076_50761602_51_dialog_content = "Esos recuerdos preciosos siempre estarán durmiendo en tu corazón, Adras.",
  ui_story_5076_50761602_52_dialog_content = "Los sentimientos asociados a ellos siempre serán parte de tu alma.",
  ui_story_5076_50761602_53_dialog_content = "Nunca volverás a estar solo.",
  ui_story_5076_50761602_54_dialog_content = "Ahora por favor, tranquilízate y simplemente duerme...",
  ui_story_5076_50761602_55_dialog_content = "Algún día habrá un <color=#FFB400>hogar</color> para ti, siempre y cuando mantengas viva la esperanza en tu corazón. Cuando lo encuentres, la paz volverá a ti—",
  ui_story_5076_50761602_56_dialog_content = "Marcela... Todos...",
  ui_story_5076_50761602_57_dialog_content = "*Tos* Lo siento, Aquiles.",
  ui_story_5076_50761602_58_dialog_content = "Pero parece que... Mi viaje finalmente ha llegado a su fin.",
  ui_story_5076_50761602_59_dialog_content = "Ludweiss... ¿Así que este es el precio que se debe pagar? Ya veo... Incluso un Caelestite no puede soportar tanta tragedia...",
  ui_story_5076_50761602_60_dialog_content = "Por eso... Dejo el futuro en tus manos.",
  ui_story_5076_50761602_61_dialog_content = "¿Realmente merecemos esto?",
  ui_story_5076_50761602_62_dialog_content = "¿Es esa incluso una pregunta? Jeje... Estoy tan agradecido de haber conocido a todos ustedes. Gracias a ustedes, este Celestita errante finalmente encontró el valor para mirar las estrellas.",
  ui_story_5076_50761602_63_dialog_content = "Gracias a todos... Por iluminar con su luz <color=#FFB400>este mundo</color>.",
  ui_story_5076_50761602_64_dialog_content = "Entiendo... Descansa tranquilo, Ludweiss.",
  ui_story_5076_50761602_65_dialog_content = "Tus recuerdos, tu voluntad, tus vidas...",
  ui_story_5076_50761602_66_dialog_content = "Llevaré a todos sobre mis hombros.",
  ui_story_5076_50761602_67_dialog_content = "Puede que no haya un lugar para mí en el futuro, ¡pero eso no me impedirá despejar un camino para mis amigos!",
  ui_story_5076_50761602_68_dialog_content = "¿Qué crees que estás haciendo, Aquiles? ¿Por qué aún no los has matado? ¿No estarás planeando algo, verdad?!",
  ui_story_5076_50761602_69_dialog_content = "¡Para! ¡No te acerques a mí!",
  ui_story_5076_50761602_70_dialog_content = "Hay algo que debo hacer... Algo que debería haber hecho hace mucho tiempo.",
  ui_story_5076_50761602_71_dialog_content = "¿Achilles? ¡¿Cuál es el significado de esto?!",
  ui_story_5076_50761602_72_dialog_content = "Ahora que soy el único que queda... Tengo que encontrar una manera... De verlos a todos ustedes de nuevo...",
  ui_story_5076_50761602_73_dialog_content = "Mi última misión... Es tomar mi <color=#FFB400>anhelo</color>... Y convertirlo en la piedra angular de un sello.",
  ui_story_5076_50761602_74_dialog_content = "...",
  ui_story_5076_50761602_75_dialog_content = "No llores, Adras... Hay alguien esperándote en tu futuro.",
  ui_story_5076_50761602_76_dialog_content = "Las cosas buenas siempre sucederán mientras mantengas la esperanza en tu corazón...",
  ui_story_5076_50761602_77_dialog_content = "Así que por favor no llores más.",
  ui_story_5076_50761602_78_dialog_content = "<color=#e8d9bb>Todo este tiempo, todos se han acostumbrado a la imponente presencia del gran héroe Adras.</color>",
  ui_story_5076_50761602_79_dialog_content = "<color=#e8d9bb>Es tan reconfortante, pero tan... solitario. Si debe ser puesto en un sueño de mil años, al menos, debería tener compañía.</color>",
  ui_story_5076_50761602_80_dialog_content = "<color=#e8d9bb>Esta es la primera vez que \"yo\" toco una espada. Un arma pesada, no algo que un Caelestite querría manejar jamás.</color>",
  ui_story_5076_50761602_81_dialog_content = "<color=#e8d9bb>Pero esto es diferente.</color>",
  ui_story_5076_50761602_82_dialog_content = "<color=#e8d9bb>Este no es un arma; es un corazón cálido, albergando el amor sincero de mi querido amigo.</color>",
  ui_story_5076_50761602_83_dialog_content = "<color=#e8d9bb>Cuando lo dibujo y lo coloco en el abrazo de Adras, una sonrisa adorna su rostro, como un niño que acaba de encontrar su posesión perdida hace mucho tiempo.</color>",
  ui_story_5076_50761602_84_dialog_content = "<color=#e8d9bb>Debe ser increíblemente difícil soportar períodos tan prolongados de soledad.</color>",
  ui_story_5076_50761602_85_dialog_content = "<color=#e8d9bb>Todo lo que puedo hacer es ofrecer mis mejores deseos, esperando que pueda encontrar consuelo con el que está en su corazón mientras cierra los ojos.</color>",
  ui_story_5076_50761602_86_dialog_content = "<color=#e8d9bb>Si las estrellas que surcan el cielo pudieran algún día encontrar su lugar en la suavidad del tiempo...</color>",
  ui_story_5076_50761602_87_dialog_content = "<color=#e8d9bb>May recibes felicidad tardía.</color>",
  ui_story_5076_50761602_88_dialog_content = "Dulces sueños, Adras."
}
return config
